const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:36,000",arabic:"وَإِنِّي آلَيْتُ عَلَى نَفْسِي أَنْ أَسْمَحَ لِلنَّاسِ جَمِيعًا...",segs:[{ar:"وَإِنِّي آلَيْتُ عَلَى نَفْسِي",uz:"men o‘z zimmamga qasam bilan ahd oldim"},{ar:"أَنْ أَسْمَحَ",uz:"ruxsat berishga"},{ar:"لِلنَّاسِ جَمِيعًا",uz:"barcha odamlarga"}],full_uz:"Men barcha odamlarga ruxsat berishga o‘z zimmamga qasam bilan ahd oldim...",note:"آلَى عَلَى نَفْسِهِ — «o‘ziga qasam bilan ahd yukladi». آلَيْتُ — «men qasam ichdim»."},
{num:2,time:"00:00:36,000 --> 00:00:40,000",arabic:"أَنْ يَخُوضُوا فِي كُلِّ مَسْأَلَةٍ لِلْعَقْلِ فِيهَا نَصِيبٌ.",segs:[{ar:"أَنْ يَخُوضُوا",uz:"muhokamaga kirishishlariga"},{ar:"فِي كُلِّ مَسْأَلَةٍ",uz:"har bir masalada"},{ar:"لِلْعَقْلِ فِيهَا نَصِيبٌ",uz:"unda aqlning hissasi bo‘lgan"}],full_uz:"Aqlning hissasi bo‘lgan har bir masalani muhokama qilishlariga.",note:"خَاضَ فِي مَسْأَلَةٍ — «bir masalaning muhokamasiga kirishdi». نَصِيبٌ — ulush, hissa."},
{num:3,time:"00:00:40,000 --> 00:00:48,000",arabic:"اللَّهُمَّ إِلَّا مُلْحِدًا يُجَاهِرُ بِالْمُعَادَاةِ لِلَّهِ سُبْحَانَهُ وَتَعَالَى.",segs:[{ar:"اللَّهُمَّ إِلَّا مُلْحِدًا",uz:"faqat bir dinsiz bundan mustasno"},{ar:"يُجَاهِرُ بِالْمُعَادَاةِ لِلَّهِ",uz:"Allohga dushmanligini oshkora bildiradigan"},{ar:"سُبْحَانَهُ وَتَعَالَى",uz:"U pok va yuksakdir"}],full_uz:"Faqat pok va yuksak Allohga dushmanligini oshkora bildiradigan dinsiz bundan mustasno.",note:"اللَّهُمَّ إِلَّا bu yerda istisnoni kuchaytiradi. جَاهَرَ بِـ — «...ni oshkora bildirdi»."},
{num:4,time:"00:00:48,000 --> 00:00:56,000",arabic:"وَلَكِنْ أَلَا يُغْضِبُ هَذَا مَنْ لَا يَرَوْنَ لِلْعَقْلِ دَوْرًا؟",segs:[{ar:"وَلَكِنْ أَلَا يُغْضِبُ هَذَا",uz:"lekin bu g‘azablantirmaydimi"},{ar:"مَنْ لَا يَرَوْنَ",uz:"deb bilmaydiganlarni"},{ar:"لِلْعَقْلِ دَوْرًا",uz:"aqlning o‘rni bor"}],full_uz:"Lekin bu aqlning o‘rni bor deb bilmaydiganlarni g‘azablantirmaydimi?",note:"أَغْضَبَ — «g‘azablantirdi»; غَضِبَ — «g‘azablandi». دَوْرٌ — vazifa, o‘rin."},
{num:5,time:"00:00:56,000 --> 00:00:59,000",arabic:"وَاعْتَمَدُوا فِي دِينِهِمْ عَلَى النَّقْلِ فَحَسْبُ.",segs:[{ar:"وَاعْتَمَدُوا فِي دِينِهِمْ",uz:"va dinlarida tayandilar"},{ar:"عَلَى النَّقْلِ فَحَسْبُ",uz:"faqat naqlga"}],full_uz:"Va dinlarida faqat naqlga tayanganlarni.",note:"اِعْتَمَدَ عَلَى — «...ga tayandi». النَّقْلُ — rivoyat orqali yetkazilgan diniy ma’lumot. فَحَسْبُ — «faqat, xolos»."},
{num:6,time:"00:00:59,000 --> 00:01:04,719",arabic:"فَضَلُّوا فِي فَهْمِ النُّصُوصِ وَأَضَلُّوا بِغَيْرِ عِلْمٍ.",segs:[{ar:"فَضَلُّوا",uz:"natijada adashdilar"},{ar:"فِي فَهْمِ النُّصُوصِ",uz:"matnlarni tushunishda"},{ar:"وَأَضَلُّوا بِغَيْرِ عِلْمٍ",uz:"va bilmasdan boshqalarni ham adashtirdilar"}],full_uz:"Natijada matnlarni tushunishda adashdilar va bilmasdan boshqalarni ham adashtirdilar.",note:"ضَلَّ — «adashdi»; أَضَلَّ — «adashtirdi». Ikki fe’lning farqiga e’tibor bering."},
{num:7,time:"00:01:04,719 --> 00:01:10,920",arabic:"ثُمَّ زَادُوا الطِّينَ بِلَّةً فَرَمَوْا بِالْبِدْعَةِ كُلَّ مَنْ لَمْ يَأْخُذْ بِرَأْيِهِمْ.",segs:[{ar:"ثُمَّ زَادُوا الطِّينَ بِلَّةً",uz:"keyin vaziyatni yanada og‘irlashtirdilar"},{ar:"فَرَمَوْا بِالْبِدْعَةِ",uz:"bid’atda aybladilar"},{ar:"كُلَّ مَنْ لَمْ يَأْخُذْ بِرَأْيِهِمْ",uz:"ularning fikrini qabul qilmagan har bir kishini"}],full_uz:"Keyin vaziyatni yanada og‘irlashtirib, ularning fikrini qabul qilmagan har bir kishini bid’atda aybladilar.",note:"زَادَ الطِّينَ بِلَّةً so‘zma-so‘z «loyning namligini oshirdi»; «vaziyatni battar qildi». رَمَاهُ بِـ — «uni ...da aybladi»."},
{num:8,time:"00:01:10,920 --> 00:01:15,079",arabic:"تَحْتَ شِعَارٍ يُسَمُّونَهُ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ.",segs:[{ar:"تَحْتَ شِعَارٍ",uz:"bir shior ostida"},{ar:"يُسَمُّونَهُ",uz:"ular uni ataydilar"},{ar:"أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ",uz:"Ahli sunna val jamoa deb"}],full_uz:"Ular «Ahli sunna val jamoa» deb ataydigan shior ostida.",note:"تَحْتَ شِعَارٍ — «bir shior ostida». سَمَّاهُ — «uni nomladi, deb atadi»."},
{num:9,time:"00:01:15,079 --> 00:01:20,079",arabic:"فَلَا سُنَّةً أَقَامُوا وَلَا جَمَاعَةً أَبْقَوْا.",segs:[{ar:"فَلَا سُنَّةً أَقَامُوا",uz:"na sunnatni barpo etdilar"},{ar:"وَلَا جَمَاعَةً أَبْقَوْا",uz:"na jamoani saqlab qoldilar"}],full_uz:"Na sunnatni barpo etdilar, na jamoani saqlab qoldilar.",note:"أَقَامَ — «barpo etdi, amal qildi». أَبْقَى — «saqlab qoldi». To‘ldiruvchilar ta’kid uchun fe’llardan oldin kelgan."},
{num:10,time:"00:01:20,079 --> 00:01:28,099",arabic:"سَأَحْرِصُ عَلَى أَلَّا يَتَعَرَّضَ أَحَدٌ مِنْ هَؤُلَاءِ الَّذِينَ تَتَحَدَّثُ عَنْهُمْ لِأَيِّ مُسْلِمٍ بَعْدَ الْيَوْمِ.",segs:[{ar:"سَأَحْرِصُ عَلَى",uz:"qat’iy e’tibor beraman"},{ar:"أَلَّا يَتَعَرَّضَ أَحَدٌ",uz:"hech kim tegmasligiga"},{ar:"مِنْ هَؤُلَاءِ الَّذِينَ تَتَحَدَّثُ عَنْهُمْ",uz:"siz gapirayotgan bu kishilardan"},{ar:"لِأَيِّ مُسْلِمٍ",uz:"biror musulmonga"},{ar:"بَعْدَ الْيَوْمِ",uz:"bugundan keyin"}],full_uz:"Bugundan keyin siz gapirayotgan bu kishilardan hech kim biror musulmonga tegmasligiga qat’iy e’tibor beraman.",note:"حَرَصَ عَلَى — «...ga astoydil e’tibor berdi». تَعَرَّضَ لَهُ bu yerda «unga tegdi, ozor berdi»."},
{num:11,time:"00:01:28,099 --> 00:01:31,640",arabic:"بَارَكَ اللَّهُ فِيكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Alloh sizga baraka bersin, ey mo‘minlar amiri.",note:null},
{num:12,time:"00:01:31,640 --> 00:01:35,099",arabic:"وَجَزَاكَ اللَّهُ خَيْرًا عَنِ الْإِسْلَامِ وَأَهْلِهِ.",segs:[{ar:"وَجَزَاكَ اللَّهُ خَيْرًا",uz:"Alloh sizni yaxshilik bilan mukofotlasin"},{ar:"عَنِ الْإِسْلَامِ وَأَهْلِهِ",uz:"Islom va uning ahliga qilgan xizmatingiz uchun"}],full_uz:"Alloh sizni Islom va uning ahliga qilgan xizmatingiz uchun yaxshilik bilan mukofotlasin.",note:"جَزَاهُ خَيْرًا عَنْ — «...uchun uni yaxshilik bilan mukofotladi»."},
{num:13,time:"00:01:35,099 --> 00:01:45,179",arabic:"أَعْطِنِيهِ عَنْكَ يَا أَحْمَدُ، فَإِنَّهُ لَا يَدَعُكَ تَرْتَاحُ.",segs:[{ar:"أَعْطِنِيهِ عَنْكَ",uz:"uni menga bering"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"},{ar:"فَإِنَّهُ لَا يَدَعُكَ تَرْتَاحُ",uz:"axir u dam olishingizga qo‘ymayapti"}],full_uz:"Uni menga bering, Ahmad. Axir u dam olishingizga qo‘ymayapti.",note:"أَعْطِنِيهِ — «uni menga bering»: ـنِي «menga», ـهِ «uni». لَا يَدَعُكَ — «sizni qo‘ymaydi»."},
{num:14,time:"00:01:45,179 --> 00:01:47,379",arabic:"دَعِيهِ يَا عَبَّاسَةُ، فَقَلَّمَا أَرَاهُ.",segs:[{ar:"دَعِيهِ",uz:"uni qo‘ying"},{ar:"يَا عَبَّاسَةُ",uz:"ey Abbosa"},{ar:"فَقَلَّمَا أَرَاهُ",uz:"axir uni kam ko‘raman"}],full_uz:"Uni qo‘ying, Abbosa. Axir uni kam ko‘raman.",note:"دَعِي ayolga qaratilgan buyruq. قَلَّمَا — «kamdan-kam»."},
{num:15,time:"00:01:47,379 --> 00:01:50,879",arabic:"كَانَ اللَّهُ فِي عَوْنِكَ.",segs:null,full_uz:"Alloh sizga yordam bersin.",note:"Shaklan o‘tgan zamonli bo‘lsa-da, duo ma’nosidagi turg‘un ibora."},
{num:16,time:"00:01:50,879 --> 00:01:53,359",arabic:"لَا أَدْرِي مَتَى تَرْتَاحُ.",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"مَتَى تَرْتَاحُ",uz:"qachon dam olishingizni"}],full_uz:"Qachon dam olishingizni bilmayman.",note:null},
{num:17,time:"00:01:53,359 --> 00:01:55,959",arabic:"فِي النَّهَارِ مَعَ طُلَّابِكَ.",segs:[{ar:"فِي النَّهَارِ",uz:"kunduzi"},{ar:"مَعَ طُلَّابِكَ",uz:"talabalaringiz bilan"}],full_uz:"Kunduzi talabalaringiz bilan.",note:null},
{num:18,time:"00:01:55,959 --> 00:01:57,840",arabic:"وَفِي اللَّيْلِ فِي صَلَاتِكَ.",segs:[{ar:"وَفِي اللَّيْلِ",uz:"kechasi esa"},{ar:"فِي صَلَاتِكَ",uz:"namozingizda"}],full_uz:"Kechasi esa namozdasiz.",note:null},
{num:19,time:"00:01:57,840 --> 00:02:00,280",arabic:"هَذَا مِنْ فَضْلِ اللَّهِ عَلَيْنَا يَا عَبَّاسَةُ.",segs:[{ar:"هَذَا مِنْ فَضْلِ اللَّهِ عَلَيْنَا",uz:"bu Allohning bizga bergan fazlidandir"},{ar:"يَا عَبَّاسَةُ",uz:"ey Abbosa"}],full_uz:"Bu Allohning bizga bergan fazlidandir, Abbosa.",note:"فَضْلُ اللَّهِ عَلَيْنَا — «Allohning bizga bergan marhamati, fazli»."},
{num:20,time:"00:02:00,280 --> 00:02:04,960",arabic:"فَمَا خَطَوْتُ خُطْوَةً إِلَّا كُتِبَ لَكِ مِثْلُ أَجْرِي.",segs:[{ar:"فَمَا خَطَوْتُ خُطْوَةً إِلَّا",uz:"qanday qadam tashlamayin"},{ar:"كُتِبَ لَكِ",uz:"sizga ham yoziladi"},{ar:"مِثْلُ أَجْرِي",uz:"mening ajrimga teng ajr"}],full_uz:"Qanday qadam tashlamayin, sizga ham mening ajrimga teng ajr yoziladi.",note:"خَطَا خُطْوَةً — «bir qadam tashladi». كُتِبَ majhul nisbatda: «yozildi». لَكِ ayolga qaratilgan."},
{num:21,time:"00:02:04,960 --> 00:02:09,219",arabic:"فَقَدْ تَحَمَّلْتِ مِنِّي الْكَثِيرَ وَمَا رَأَيْتُ مِنْكِ إِلَّا الصَّبْرَ الْجَمِيلَ.",segs:[{ar:"فَقَدْ تَحَمَّلْتِ مِنِّي الْكَثِيرَ",uz:"siz men sababli ko‘p narsaga chidadingiz"},{ar:"وَمَا رَأَيْتُ مِنْكِ إِلَّا",uz:"sizdan esa faqat ...ko‘rdim"},{ar:"الصَّبْرَ الْجَمِيلَ",uz:"go‘zal sabrni"}],full_uz:"Siz men sababli ko‘p narsaga chidadingiz. Sizdan esa faqat go‘zal sabr ko‘rdim.",note:"تَحَمَّلَ — «ko‘tardi, chidadi». تَحَمَّلْتِ va مِنْكِ ayol kishiga murojaatni bildiradi."},
{num:22,time:"00:02:15,539 --> 00:02:20,259",arabic:"إِنَّ كُلَّ مَا نَقُولُ بِهِ لَا يَتَعَدَّى تَنْزِيهَ اللَّهِ سُبْحَانَهُ وَتَعَالَى عَمَّا لَا يَلِيقُ بِهِ.",segs:[{ar:"إِنَّ كُلَّ مَا نَقُولُ بِهِ",uz:"biz ilgari surayotgan barcha fikrlar"},{ar:"لَا يَتَعَدَّى تَنْزِيهَ اللَّهِ",uz:"Allohni pok deb bilishdan nariga o‘tmaydi"},{ar:"سُبْحَانَهُ وَتَعَالَى",uz:"U pok va yuksakdir"},{ar:"عَمَّا لَا يَلِيقُ بِهِ",uz:"Unga munosib bo‘lmagan narsalardan"}],full_uz:"Biz ilgari surayotgan barcha fikrlar pok va yuksak Allohni Unga munosib bo‘lmagan narsalardan pok deb bilishdan nariga o‘tmaydi.",note:"قَالَ بِرَأْيٍ — «bir fikrni qabul qildi, ilgari surdi». تَنْزِيهٌ — noloyiq sifat va nuqsonlardan pok deb bilish."},
{num:23,time:"00:02:20,259 --> 00:02:26,599",arabic:"أَنُوسَمُ بِالْخَطَإِ لِأَنَّنَا نُنَزِّهُ اللَّهَ سُبْحَانَهُ وَتَعَالَى عَمَّا يَقُولُهُ الْأَدْعِيَاءُ الضُّلَّالُ؟",segs:[{ar:"أَنُوسَمُ بِالْخَطَإِ",uz:"bizga xatokor tamg‘asi bosiladimi"},{ar:"لِأَنَّنَا نُنَزِّهُ اللَّهَ",uz:"Allohni pok deb bilganimiz uchun"},{ar:"سُبْحَانَهُ وَتَعَالَى",uz:"U pok va yuksakdir"},{ar:"عَمَّا يَقُولُهُ",uz:"ular aytayotgan narsalardan"},{ar:"الْأَدْعِيَاءُ الضُّلَّالُ",uz:"adashgan soxta da’vogarlar"}],full_uz:"Pok va yuksak Allohni adashgan soxta da’vogarlar aytayotgan narsalardan pok deb bilganimiz uchun bizga xatokor tamg‘asi bosiladimi?",note:"وَسَمَ — «tamg‘a bosdi, belgiladi». نُوسَمُ — majhul nisbat: «bizga tamg‘a bosiladi». أَدْعِيَاءُ — soxta da’vogarlar."},
{num:24,time:"00:02:26,599 --> 00:02:32,239",arabic:"وَقَوْلُنَا إِنَّ الْقُرْآنَ مَخْلُوقٌ مُؤَيَّدٌ بِالْأَدِلَّةِ وَالْبَرَاهِينِ.",segs:[{ar:"وَقَوْلُنَا",uz:"bizning gapimiz"},{ar:"إِنَّ الْقُرْآنَ مَخْلُوقٌ",uz:"Qur’on yaratilgandir degan"},{ar:"مُؤَيَّدٌ بِالْأَدِلَّةِ وَالْبَرَاهِينِ",uz:"dalillar va isbotlar bilan tasdiqlangan"}],full_uz:"Bizning «Qur’on yaratilgandir» degan gapimiz dalillar va isbotlar bilan tasdiqlangan.",note:"مُؤَيَّدٌ — «quvvatlangan, tasdiqlangan». بَرَاهِينُ — بُرْهَانٌ («isbot, qat’iy dalil»)ning ko‘pligi."},
{num:25,time:"00:02:32,239 --> 00:02:35,039",arabic:"أَمَّا إِنْكَارُ الْعَوَامِّ ذَلِكَ...",segs:[{ar:"أَمَّا إِنْكَارُ الْعَوَامِّ",uz:"avomning inkor etishiga kelsak"},{ar:"ذَلِكَ",uz:"buni"}],full_uz:"Avomning buni inkor etishiga kelsak...",note:"إِنْكَارُ الْعَوَامِّ da الْعَوَامِّ inkorni amalga oshirayotgan kishilarni bildiradi."},
{num:26,time:"00:02:35,039 --> 00:02:37,680",arabic:"فَأَوْهَنُ مِنْ أَنْ يَدْعَمَهُ دَلِيلٌ.",segs:[{ar:"فَأَوْهَنُ مِنْ",uz:"u juda zaif"},{ar:"أَنْ يَدْعَمَهُ دَلِيلٌ",uz:"uni biror dalil quvvatlashi uchun"}],full_uz:"U shu qadar zaifki, uni biror dalil quvvatlay olmaydi.",note:"أَوْهَنُ — «zaifroq». أَفْعَلُ مِنْ أَنْ tuzilishi ko‘pincha bir ishning amalga oshishi uchun daraja yetmasligini bildiradi."},
{num:27,time:"00:02:37,680 --> 00:02:41,879",arabic:"قُلْ هَاتُوا بُرْهَانَكُمْ إِنْ كُنْتُمْ صَادِقِينَ.",segs:[{ar:"قُلْ",uz:"ayting"},{ar:"هَاتُوا بُرْهَانَكُمْ",uz:"dalilingizni keltiring"},{ar:"إِنْ كُنْتُمْ صَادِقِينَ",uz:"agar rostgo‘y bo‘lsangiz"}],full_uz:"Ayting: «Agar rostgo‘y bo‘lsangiz, dalilingizni keltiring».",note:"هَاتُوا — ko‘plikka qaratilgan «keltiringlar». صَادِقِينَ — كَانَ ning ko‘plikdagi mansub xabari."},
{num:28,time:"00:02:41,879 --> 00:02:48,259",arabic:"فَهَلْ بَعْدَ هَذَا الْكَلَامِ كَلَامٌ؟",segs:[{ar:"فَهَلْ بَعْدَ هَذَا الْكَلَامِ",uz:"bu gapdan keyin"},{ar:"كَلَامٌ",uz:"yana gap bormi"}],full_uz:"Bu gapdan keyin yana aytiladigan gap bormi?",note:"So‘roq bu yerda javob kutishdan ko‘ra, fikrni yakuniy deb ko‘rsatish uchun ishlatilgan."},
{num:29,time:"00:02:48,259 --> 00:02:51,180",arabic:"مَنْ تَقْصِدُ بِالْعَوَامِّ يَا أَيُّهَا الْجَاهِلُ؟",segs:[{ar:"مَنْ تَقْصِدُ بِالْعَوَامِّ",uz:"avom deb kimni nazarda tutyapsiz"},{ar:"يَا أَيُّهَا الْجَاهِلُ",uz:"ey johil"}],full_uz:"Avom deb kimni nazarda tutyapsiz, ey johil?",note:"قَصَدَ بِكَلَامِهِ فُلَانًا — «gapi bilan falonchini nazarda tutdi»."},
{num:30,time:"00:02:51,180 --> 00:02:55,180",arabic:"تَقْصِدُ بِهِمْ شُيُوخَ بَغْدَادَ وَعُلَمَاءَهَا؟",segs:[{ar:"تَقْصِدُ بِهِمْ",uz:"ular bilan nazarda tutyapsizmi"},{ar:"شُيُوخَ بَغْدَادَ وَعُلَمَاءَهَا",uz:"Bag‘dod shayxlari va olimlarini"}],full_uz:"Bag‘dod shayxlari va olimlarini nazarda tutyapsizmi?",note:null},
{num:31,time:"00:02:55,180 --> 00:02:59,900",arabic:"لَقَدْ أَضَلَّتْكُمْ عُقُولُكُمْ وَأَوْرَدَتْكُمْ حِيَاضَ الْبِدْعَةِ وَالْمُبْتَدِعَةِ.",segs:[{ar:"لَقَدْ أَضَلَّتْكُمْ عُقُولُكُمْ",uz:"aqllaringiz sizni adashtirdi"},{ar:"وَأَوْرَدَتْكُمْ",uz:"va sizni olib kirdi"},{ar:"حِيَاضَ الْبِدْعَةِ وَالْمُبْتَدِعَةِ",uz:"bid’at va bid’atchilar havzalariga"}],full_uz:"Aqllaringiz sizni adashtirib, bid’at va bid’atchilar havzalariga olib kirdi.",note:"أَوْرَدَهُ — «uni bir joyga olib bordi». حِيَاضٌ — حَوْضٌ («hovuz, havza»)ning ko‘pligi; bu yerda ko‘chma ifoda."},
{num:32,time:"00:02:59,900 --> 00:03:04,580",arabic:"مَنْ تَقْصِدُ بِالْمُبْتَدِعَةِ أَيُّهَا الْأَحْمَقُ؟",segs:[{ar:"مَنْ تَقْصِدُ بِالْمُبْتَدِعَةِ",uz:"bid’atchilar deb kimni nazarda tutyapsiz"},{ar:"أَيُّهَا الْأَحْمَقُ",uz:"ey ahmoq"}],full_uz:"Bid’atchilar deb kimni nazarda tutyapsiz, ey ahmoq?",note:"مُبْتَدِعٌ — bid’at chiqaruvchi kishi. الْمُبْتَدِعَةُ bu yerda shunday kishilar guruhini bildiradi."},
{num:33,time:"00:03:04,580 --> 00:03:06,740",arabic:"غَفَرَ اللَّهُ لَكَ وَهَدَاكَ إِلَى الْحَقِّ.",segs:[{ar:"غَفَرَ اللَّهُ لَكَ",uz:"Alloh sizni kechirsin"},{ar:"وَهَدَاكَ إِلَى الْحَقِّ",uz:"va haq yo‘lga boshlasin"}],full_uz:"Alloh sizni kechirsin va haq yo‘lga boshlasin.",note:null},
{num:34,time:"00:03:06,740 --> 00:03:11,800",arabic:"الْمُبْتَدِعَةُ هُمْ مَنْ مَلَؤُوا صَحْنَ عَقْلِكَ هَذَا بِالشُّبُهَاتِ.",segs:[{ar:"الْمُبْتَدِعَةُ هُمْ مَنْ",uz:"bid’atchilar o‘sha kishilarki"},{ar:"مَلَؤُوا صَحْنَ عَقْلِكَ هَذَا",uz:"bu aqlingiz kosasini to‘ldirganlar"},{ar:"بِالشُّبُهَاتِ",uz:"shubhali fikrlar bilan"}],full_uz:"Bid’atchilar bu aqlingiz kosasini shubhali fikrlar bilan to‘ldirgan kishilardir.",note:"صَحْنُ عَقْلِكَ — aqlni idishga o‘xshatgan ko‘chma ifoda. شُبُهَاتٌ — haqiqatga o‘xshab ko‘rinadigan, shubha tug‘diruvchi fikrlar."},
{num:35,time:"00:03:11,800 --> 00:03:16,740",arabic:"لِتُثِيرَ بَيْنَ النَّاسِ الْفِتْنَةَ فَتُفْسِدَ عَلَيْهِمْ دِينَهُمْ وَدُنْيَاهُمْ.",segs:[{ar:"لِتُثِيرَ بَيْنَ النَّاسِ الْفِتْنَةَ",uz:"odamlar orasida fitna qo‘zg‘atishingiz uchun"},{ar:"فَتُفْسِدَ عَلَيْهِمْ",uz:"va ularga buzib berishingiz uchun"},{ar:"دِينَهُمْ وَدُنْيَاهُمْ",uz:"dinlari va dunyolarini"}],full_uz:"Odamlar orasida fitna qo‘zg‘atib, ularning dini va dunyosini buzishingiz uchun.",note:"أَثَارَ الْفِتْنَةَ — «fitna qo‘zg‘atdi». أَفْسَدَ عَلَيْهِ أَمْرَهُ — «uning ishini buzdi»."},
{num:36,time:"00:03:16,740 --> 00:03:19,240",arabic:"أَمْسِكْ عَلَيْكَ لِسَانَكَ أَيُّهَا الضَّالُّ الْمُضِلُّ.",segs:[{ar:"أَمْسِكْ عَلَيْكَ لِسَانَكَ",uz:"tilingizni tiying"},{ar:"أَيُّهَا الضَّالُّ الْمُضِلُّ",uz:"ey adashgan va adashtiruvchi"}],full_uz:"Tilingizni tiying, ey adashgan va adashtiruvchi!",note:"ضَالٌّ — o‘zi adashgan; مُضِلٌّ — boshqalarni adashtiradigan. أَمْسِكْ لِسَانَكَ — «tilingizni tiying»."},
{num:37,time:"00:03:19,240 --> 00:03:22,520",arabic:"وَإِيَّاكَ أَنْ تَذْكُرَ مَشَايِخِي بِسُوءٍ يَا رَبِيبَ الْجَهَالَةِ وَالضَّلَالِ.",segs:[{ar:"وَإِيَّاكَ أَنْ تَذْكُرَ مَشَايِخِي بِسُوءٍ",uz:"ustozlarimni yomonlab tilga ola ko‘rmang"},{ar:"يَا رَبِيبَ الْجَهَالَةِ وَالضَّلَالِ",uz:"ey johillik va adashish qo‘lida ulg‘aygan"}],full_uz:"Ustozlarimni yomonlab tilga ola ko‘rmang, ey johillik va adashish qo‘lida ulg‘aygan!",note:"إِيَّاكَ أَنْ — qat’iy ogohlantirish: «...qila ko‘rmang». رَبِيبٌ — birovning tarbiyasida ulg‘aygan kishi."},
{num:38,time:"00:03:22,520 --> 00:03:24,200",arabic:"هَيَّا انْصَرِفْ.",segs:null,full_uz:"Qani, keting.",note:"اِنْصَرَفَ — «ketdi, joyni tark etdi». اِنْصَرِفْ — buyruq shakli."},
{num:39,time:"00:03:24,200 --> 00:03:26,120",arabic:"وَلَا تُنَجِّسْ مَسَاجِدَنَا.",segs:[{ar:"وَلَا تُنَجِّسْ",uz:"va bulg‘amang"},{ar:"مَسَاجِدَنَا",uz:"masjidlarimizni"}],full_uz:"Va masjidlarimizni bulg‘amang.",note:"نَجَّسَ — «najas qildi, bulg‘adi». لَا تُنَجِّسْ taqiq shakli."},
{num:40,time:"00:03:26,120 --> 00:03:28,939",arabic:"بِفَسَادِ عَقَائِدِكَ وَضَلَالِ مَذَاهِبِكَ.",segs:[{ar:"بِفَسَادِ عَقَائِدِكَ",uz:"buzuq e’tiqodlaringiz bilan"},{ar:"وَضَلَالِ مَذَاهِبِكَ",uz:"va adashgan yo‘nalishlaringiz bilan"}],full_uz:"Buzuq e’tiqodlaringiz va adashgan yo‘nalishlaringiz bilan.",note:"عَقَائِدُ — عَقِيدَةٌ ning, مَذَاهِبُ — مَذْهَبٌ ning ko‘pligi."},
{num:41,time:"00:03:28,939 --> 00:03:30,080",arabic:"اِذْهَبْ، هَدَاكَ اللَّهُ.",segs:[{ar:"اِذْهَبْ",uz:"keting"},{ar:"هَدَاكَ اللَّهُ",uz:"Alloh sizni hidoyat qilsin"}],full_uz:"Keting, Alloh sizni hidoyat qilsin.",note:null},
{num:42,time:"00:03:30,080 --> 00:03:32,020",arabic:"اِذْهَبْ.",segs:null,full_uz:"Keting.",note:null},
{num:43,time:"00:03:32,020 --> 00:03:34,980",arabic:"اِهْدَأْ يَا أَبَا نَصْرٍ.",segs:[{ar:"اِهْدَأْ",uz:"tinchlaning"},{ar:"يَا أَبَا نَصْرٍ",uz:"ey Abu Nasr"}],full_uz:"Tinchlaning, Abu Nasr.",note:"هَدَأَ — «tinchlandi». اِهْدَأْ — «tinchlaning»."},
{num:44,time:"00:03:34,980 --> 00:03:38,580",arabic:"إِنَّهُمْ أَقَلُّ مِنْ أَنْ تَبْخَعَ نَفْسَكَ عَلَى آثَارِهِمْ.",segs:[{ar:"إِنَّهُمْ أَقَلُّ مِنْ",uz:"ular bunga arzimaydi"},{ar:"أَنْ تَبْخَعَ نَفْسَكَ",uz:"o‘zingizni halok qilishingizga"},{ar:"عَلَى آثَارِهِمْ",uz:"ularning ortidan"}],full_uz:"Ular ortidan kuyinib, o‘zingizni halok qilishingizga arzimaydi.",note:"بَخَعَ نَفْسَهُ — qattiq qayg‘u yoki g‘azab bilan o‘zini halok qilish darajasiga yetkazish."},
{num:45,time:"00:03:38,580 --> 00:03:40,640",arabic:"مَلَؤُوا الْهَوَاءَ بِسُمُومِهِمْ.",segs:[{ar:"مَلَؤُوا الْهَوَاءَ",uz:"havoni to‘ldirdilar"},{ar:"بِسُمُومِهِمْ",uz:"zaharlari bilan"}],full_uz:"Havoni zaharlari bilan to‘ldirdilar.",note:"سُمُومٌ — سَمٌّ («zahar»)ning ko‘pligi; bu nutqda zararli deb hisoblangan fikrlarga ko‘chma ma’noda ishlatilgan."},
{num:46,time:"00:03:40,640 --> 00:03:42,800",arabic:"حَتَّى مَسَاجِدُ الرَّحْمَٰنِ...",segs:null,full_uz:"Hatto Rahmonning masjidlari ham...",note:null},
{num:47,time:"00:03:42,800 --> 00:03:45,020",arabic:"لَمْ تَسْلَمْ مِنْ بِدَعِهِمْ.",segs:[{ar:"لَمْ تَسْلَمْ",uz:"omon qolmadi"},{ar:"مِنْ بِدَعِهِمْ",uz:"ularning bid’atlaridan"}],full_uz:"Ularning bid’atlaridan omon qolmadi.",note:"سَلِمَ مِنْ — «...dan omon qoldi». Fe’l oldingi مَسَاجِدُ ga qaytib, birlik muannasda kelgan."},
{num:48,time:"00:03:45,020 --> 00:03:46,939",arabic:"إِلَى هَذَا الْحَدِّ...",segs:null,full_uz:"Shu darajagacha...",note:null},
{num:49,time:"00:03:46,939 --> 00:03:49,120",arabic:"وَصَلَتْ وَقَاحَةُ أَهْلِ الْبِدَعِ.",segs:[{ar:"وَصَلَتْ وَقَاحَةُ",uz:"surbetligi yetib bordi"},{ar:"أَهْلِ الْبِدَعِ",uz:"bid’at ahlining"}],full_uz:"Bid’at ahlining surbetligi yetib bordi.",note:"وَقَاحَةٌ — surbetlik, uyatsizlik. Fikr oldingi banddagi إِلَى هَذَا الْحَدِّ bilan to‘liq bo‘ladi."},
{num:50,time:"00:03:49,120 --> 00:03:52,260",arabic:"كُلُّ هَذَا بِسَبَبِ تَسَاهُلِ الْمَأْمُونِ.",segs:[{ar:"كُلُّ هَذَا",uz:"bularning barchasi"},{ar:"بِسَبَبِ تَسَاهُلِ الْمَأْمُونِ",uz:"Ma’munning yon berishi sababli"}],full_uz:"Bularning barchasi Ma’munning yon berishi sababli.",note:"تَسَاهُلٌ — yumshoq munosabatda bo‘lish, talabchanlik qilmaslik, yon berish."},
{num:51,time:"00:03:56,620 --> 00:04:04,139",arabic:"لِأَبِي عَبْدِ الرَّحْمَٰنِ الْفَضْلُ أَنْ شَرَّفَنِي بِرُؤْيَةِ وَجْهِ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"لِأَبِي عَبْدِ الرَّحْمَٰنِ الْفَضْلُ",uz:"Abu Abdurahmonning xizmatidir"},{ar:"أَنْ شَرَّفَنِي",uz:"meni musharraf qilgani"},{ar:"بِرُؤْيَةِ وَجْهِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining yuzini ko‘rishga"}],full_uz:"Mo‘minlar amirining yuzini ko‘rishga musharraf bo‘lishim Abu Abdurahmonning xizmatidir.",note:"لَهُ الْفَضْلُ — «bu uning xizmati, yaxshiligi». شَرَّفَهُ بِـ — «uni ...bilan sharafladi»."},
{num:52,time:"00:04:04,139 --> 00:04:06,659",arabic:"وَهَدَانِي إِلَى طَرِيقِ الْحَقِّ.",segs:[{ar:"وَهَدَانِي",uz:"va meni boshladi"},{ar:"إِلَى طَرِيقِ الْحَقِّ",uz:"haq yo‘liga"}],full_uz:"Va meni haq yo‘liga boshladi.",note:null},
{num:53,time:"00:04:06,659 --> 00:04:09,299",arabic:"وَخَلَّصَنِي مِنْ طَرِيقِ الضَّلَالَةِ.",segs:[{ar:"وَخَلَّصَنِي",uz:"va meni qutqardi"},{ar:"مِنْ طَرِيقِ الضَّلَالَةِ",uz:"adashish yo‘lidan"}],full_uz:"Va meni adashish yo‘lidan qutqardi.",note:"خَلَّصَهُ مِنْ — «uni ...dan qutqardi»."},
{num:54,time:"00:04:17,300 --> 00:04:20,719",arabic:"إِذَنْ فَلِلشَّيْخِ الْمَرِيسِيِّ...",segs:[{ar:"إِذَنْ",uz:"unday bo‘lsa"},{ar:"فَلِلشَّيْخِ الْمَرِيسِيِّ",uz:"shayx Marisiyga tegishli ekan"}],full_uz:"Unday bo‘lsa, shayx Marisiyga tegishli ekan...",note:"لِلشَّيْخِ oldinga chiqqan xabar. Unga tegishli bo‘lgan narsa keyingi bandda aytiladi."},
{num:55,time:"00:04:20,720 --> 00:04:26,620",arabic:"مُطْلَقُ الْوَلَاءِ وَنِهَايَةُ الْوَفَاءِ مِنْكَ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"مُطْلَقُ الْوَلَاءِ",uz:"to‘liq sadoqat"},{ar:"وَنِهَايَةُ الْوَفَاءِ مِنْكَ",uz:"va sizdan eng yuksak vafo"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Sizning to‘liq sadoqatingiz va eng yuksak vafoingiz, Abu Abbos.",note:"مُطْلَقُ الْوَلَاءِ — cheklanmagan sadoqat. نِهَايَةُ الْوَفَاءِ — vafoning eng yuqori darajasi."},
{num:56,time:"00:04:26,620 --> 00:04:29,780",arabic:"يَا مَوْلَايَ، أَعَزَّكَ اللَّهُ.",segs:[{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"},{ar:"أَعَزَّكَ اللَّهُ",uz:"Alloh sizni aziz qilsin"}],full_uz:"Hukmdorim, Alloh sizni aziz qilsin.",note:null},
{num:57,time:"00:04:29,780 --> 00:04:36,060",arabic:"إِنَّ مَحَبَّتِي لِأَبِي عَبْدِ الرَّحْمَٰنِ كَمَحَبَّةِ الِابْنِ لِأَبِيهِ.",segs:[{ar:"إِنَّ مَحَبَّتِي لِأَبِي عَبْدِ الرَّحْمَٰنِ",uz:"Abu Abdurahmonga muhabbatim"},{ar:"كَمَحَبَّةِ الِابْنِ لِأَبِيهِ",uz:"o‘g‘ilning otasiga muhabbatidek"}],full_uz:"Abu Abdurahmonga muhabbatim o‘g‘ilning otasiga muhabbatidek.",note:"كَـ o‘xshatish yuklamasi. مَحَبَّةُ الِابْنِ لِأَبِيهِ da o‘g‘il sevuvchi, ota esa muhabbat qaratilgan kishidir."},
{num:58,time:"00:04:36,060 --> 00:04:41,380",arabic:"فَإِنْ خَرَجَ أَبِي عَنْ طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ...",segs:[{ar:"فَإِنْ خَرَجَ أَبِي",uz:"agar otam chiqsa"},{ar:"عَنْ طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiriga itoatdan"}],full_uz:"Agar otam mo‘minlar amiriga itoatdan chiqsa...",note:"خَرَجَ عَنْ طَاعَتِهِ — «unga itoatdan chiqdi»."},
{num:59,time:"00:04:41,380 --> 00:04:46,260",arabic:"لَمْ يَبْقَ لَهُ فِي قَلْبِي مِثْقَالُ ذَرَّةٍ مِنَ الْمَحَبَّةِ وَالْوَفَاءِ.",segs:[{ar:"لَمْ يَبْقَ لَهُ فِي قَلْبِي",uz:"qalbimda unga qolmaydi"},{ar:"مِثْقَالُ ذَرَّةٍ",uz:"zarra og‘irligicha ham"},{ar:"مِنَ الْمَحَبَّةِ وَالْوَفَاءِ",uz:"muhabbat va vafo"}],full_uz:"Qalbimda unga zarracha ham muhabbat va vafo qolmaydi.",note:"مِثْقَالُ ذَرَّةٍ — «zarra og‘irligicha», juda oz miqdor. لَمْ يَبْقَ oldingi shartga javob sifatida kelgan."},
{num:60,time:"00:04:46,259 --> 00:04:53,000",arabic:"إِنَّ وَلَائِيَ الْمُطْلَقَ لِأَمِيرِ الْمُؤْمِنِينَ فَحَسْبُ.",segs:[{ar:"إِنَّ وَلَائِيَ الْمُطْلَقَ",uz:"mening to‘liq sadoqatim"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ فَحَسْبُ",uz:"faqat mo‘minlar amirigadir"}],full_uz:"Mening to‘liq sadoqatim faqat mo‘minlar amirigadir.",note:"فَحَسْبُ — «faqat, xolos». الْمُطْلَقَ bu yerda cheklanmagan, shartsiz ma’nosida."},
{num:61,time:"00:04:53,000 --> 00:04:56,759",arabic:"وَلَنْ يُزَاحِمَ ذَلِكَ الْوَلَاءَ مَخْلُوقٌ.",segs:[{ar:"وَلَنْ يُزَاحِمَ",uz:"raqobat qila olmaydi"},{ar:"ذَلِكَ الْوَلَاءَ",uz:"bu sadoqat bilan"},{ar:"مَخْلُوقٌ",uz:"hech bir yaratilgan zot"}],full_uz:"Bu sadoqat bilan hech bir yaratilgan zot raqobat qila olmaydi.",note:"زَاحَمَ — «siqib chiqarmoqchi bo‘ldi, raqobat qildi». مَخْلُوقٌ gapning egasi bo‘lib, fe’ldan keyin kelgan."},
{num:62,time:"00:04:56,759 --> 00:05:07,259",arabic:"أَيْنَ تَرَى نَفْسَكَ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"أَيْنَ تَرَى نَفْسَكَ",uz:"o‘zingizni qayerda ko‘rasiz"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"O‘zingizni qayerda ko‘rasiz, Abu Abbos?",note:"Savol bu yerda kishining o‘ziga munosib deb bilgan vazifasi yoki lavozimini so‘ramoqda."},
{num:63,time:"00:05:09,259 --> 00:05:12,899",arabic:"لَا أَرَاهَا إِلَّا حَيْثُ يَرَانِي أَمِيرُ الْمُؤْمِنِينَ.",segs:[{ar:"لَا أَرَاهَا إِلَّا",uz:"o‘zimni faqat ...ko‘raman"},{ar:"حَيْثُ يَرَانِي أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri meni ko‘rgan joyda"}],full_uz:"O‘zimni faqat mo‘minlar amiri meni ko‘rgan joyda ko‘raman.",note:"أَرَاهَا dagi ـهَا oldingi نَفْسَكَ ga qaytadi. حَيْثُ — «...gan joyda»."},
{num:64,time:"00:05:12,899 --> 00:05:16,259",arabic:"أَنَا خَادِمُكَ وَعَبْدُكَ يَا مَوْلَايَ.",segs:[{ar:"أَنَا خَادِمُكَ وَعَبْدُكَ",uz:"men xizmatkoringiz va qulingizman"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Men xizmatkoringiz va qulingizman, hukmdorim.",note:null},
{num:65,time:"00:05:16,259 --> 00:05:28,000",arabic:"إِنْ وَضَعْنَاكَ فِي الْعَسَسِ يَا أَبَا الْعَبَّاسِ...",segs:[{ar:"إِنْ وَضَعْنَاكَ فِي الْعَسَسِ",uz:"agar sizni tungi qo‘riqchilar xizmatiga qo‘ysak"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Agar sizni tungi qo‘riqchilar xizmatiga qo‘ysak, Abu Abbos...",note:"الْعَسَسُ — kechasi aylanib, tartib va xavfsizlikni kuzatuvchi qo‘riqchilar."},
{num:66,time:"00:05:28,000 --> 00:05:30,939",arabic:"مَا كُنْتَ فَاعِلًا؟",segs:null,full_uz:"Nima qilgan bo‘lardingiz?",note:"مَا bu yerda so‘roq olmoshi. كُنْتَ فَاعِلًا — «qilgan bo‘lardingiz»."},
{num:67,time:"00:05:30,939 --> 00:05:36,639",arabic:"خَلَعْتُ عَيْنَيَّ فَلَا أَرَى إِلَّا بِعَيْنَيْكَ يَا مَوْلَايَ.",segs:[{ar:"خَلَعْتُ عَيْنَيَّ",uz:"ko‘zlarimdan voz kechardim"},{ar:"فَلَا أَرَى إِلَّا بِعَيْنَيْكَ",uz:"faqat sizning ko‘zlaringiz bilan ko‘rardim"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Ko‘zlarimdan voz kechib, faqat sizning ko‘zlaringiz bilan ko‘rardim, hukmdorim.",note:"خَلَعْتُ عَيْنَيَّ so‘zma-so‘z «ko‘zlarimni olib tashlardim»; bu yerda mustaqil qarashdan voz kechish haqidagi mubolag‘a."},
{num:68,time:"00:05:36,639 --> 00:05:40,899",arabic:"وَأَصْمَمْتُ أُذُنَيَّ فَلَا أَسْمَعُ إِلَّا مَا يُرِيدُ أَمِيرُ الْمُؤْمِنِينَ.",segs:[{ar:"وَأَصْمَمْتُ أُذُنَيَّ",uz:"quloqlarimni ham kar qilardim"},{ar:"فَلَا أَسْمَعُ إِلَّا",uz:"faqat eshitardim"},{ar:"مَا يُرِيدُ أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri istagan narsani"}],full_uz:"Quloqlarimni ham kar qilib, faqat mo‘minlar amiri istagan narsani eshitardim.",note:"أَصَمَّ — «kar qildi». ـتُ qo‘shilganda qo‘sh undosh ajraladi: أَصْمَمْتُ."},
{num:69,time:"00:05:42,899 --> 00:05:47,339",arabic:"سَنَرَى يَا أَبَا الْعَبَّاسِ حُسْنَ الْعَمَلِ...",segs:[{ar:"سَنَرَى",uz:"ko‘ramiz"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"},{ar:"حُسْنَ الْعَمَلِ",uz:"ishning yaxshiligini"}],full_uz:"Ishning yaxshiligini ham ko‘ramiz, Abu Abbos...",note:"حُسْنُ الْعَمَلِ — «ishni yaxshi bajarish, ishning yaxshiligi»."},
{num:70,time:"00:05:47,339 --> 00:05:53,500",arabic:"بَعْدَ أَنْ رَأَيْنَا حُلْوَ الْكَلَامِ.",segs:[{ar:"بَعْدَ أَنْ رَأَيْنَا",uz:"ko‘rganimizdan keyin"},{ar:"حُلْوَ الْكَلَامِ",uz:"shirin gapni"}],full_uz:"Shirin gapni ko‘rganimizdan keyin.",note:"حُلْوُ الْكَلَامِ — «shirin, yoqimli gap». Oldingi band bilan birga gap va amaliy ish qiyoslanmoqda."},
{num:71,time:"00:05:53,500 --> 00:06:01,239",arabic:"أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"أَلَمْ يَقُلْ رَسُولُ اللَّهِ",uz:"Allohning Rasuli aytmaganlarmi"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Allohning Rasuli — Alloh u zotga salovot va salom yo‘llasin — aytmaganlarmi...",note:"يَقُولُ fe’li لَمْ dan keyin يَقُلْ bo‘ladi."},
{num:72,time:"00:06:01,239 --> 00:06:02,519",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:null,full_uz:"Alloh u zotga salovot va salom yo‘llasin.",note:null},
{num:73,time:"00:06:02,519 --> 00:06:05,839",arabic:"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ.",segs:[{ar:"مَنْ رَأَى مِنْكُمْ مُنْكَرًا",uz:"sizlardan kim bir yomonlikni ko‘rsa"},{ar:"فَلْيُغَيِّرْهُ",uz:"uni o‘zgartirsin"},{ar:"بِيَدِهِ",uz:"qo‘li bilan"}],full_uz:"Sizlardan kim bir yomonlikni ko‘rsa, uni qo‘li bilan o‘zgartirsin.",note:"فَلْيُغَيِّرْهُ dagi لْ buyruq lomi, fe’l esa jazm holatida. مُنْكَرٌ — yomon, noma’qul deb topilgan ish."},
{num:74,time:"00:06:05,839 --> 00:06:08,939",arabic:"فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ.",segs:[{ar:"فَإِنْ لَمْ يَسْتَطِعْ",uz:"agar bunga qodir bo‘lmasa"},{ar:"فَبِلِسَانِهِ",uz:"tili bilan"}],full_uz:"Agar bunga qodir bo‘lmasa, tili bilan.",note:"يَسْتَطِيعُ fe’li لَمْ dan keyin يَسْتَطِعْ bo‘ladi. Ikkinchi qismda «o‘zgartirsin» mazmuni tushuniladi."},
{num:75,time:"00:06:08,939 --> 00:06:14,899",arabic:"فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ.",segs:[{ar:"فَإِنْ لَمْ يَسْتَطِعْ",uz:"agar bunga ham qodir bo‘lmasa"},{ar:"فَبِقَلْبِهِ",uz:"qalbi bilan"},{ar:"وَذَلِكَ أَضْعَفُ الْإِيمَانِ",uz:"bu esa imonning eng zaif darajasidir"}],full_uz:"Agar bunga ham qodir bo‘lmasa, qalbi bilan. Bu esa imonning eng zaif darajasidir.",note:"أَضْعَفُ — «eng zaif». بِقَلْبِهِ bu yerda yomonlikni qalban inkor qilishni bildiradi."},
{num:76,time:"00:06:14,899 --> 00:06:19,500",arabic:"فَفِيمَ الصَّمْتُ إِذَنْ عَلَى مُنْكَرِ هَذِهِ الشِّرْذِمَةِ؟",segs:[{ar:"فَفِيمَ الصَّمْتُ إِذَنْ",uz:"unday bo‘lsa, nega sukut saqlaymiz"},{ar:"عَلَى مُنْكَرِ هَذِهِ الشِّرْذِمَةِ",uz:"bu to‘daning yomonligi oldida"}],full_uz:"Unday bo‘lsa, nega bu to‘daning yomonligi oldida sukut saqlaymiz?",note:"فِيمَ — فِي va so‘roq مَا birikmasi. شِرْذِمَةٌ — kichik guruh; bu yerda kamsituvchi ohangdagi «to‘da»."},
{num:77,time:"00:06:19,500 --> 00:06:22,000",arabic:"خَشْيَةَ الْفِتْنَةِ يَا أَبَا نَصْرٍ.",segs:[{ar:"خَشْيَةَ الْفِتْنَةِ",uz:"fitnadan qo‘rqib"},{ar:"يَا أَبَا نَصْرٍ",uz:"ey Abu Nasr"}],full_uz:"Fitnadan qo‘rqib, Abu Nasr.",note:"خَشْيَةَ sababni bildiruvchi mansub masdar: «qo‘rqqanimiz uchun»."},
{num:78,time:"00:06:22,000 --> 00:06:25,680",arabic:"لَا نُرِيدُ أَنْ نُثِيرَ النَّاسَ عَلَى الْخَلِيفَةِ.",segs:[{ar:"لَا نُرِيدُ",uz:"istamaymiz"},{ar:"أَنْ نُثِيرَ النَّاسَ",uz:"odamlarni qo‘zg‘atishni"},{ar:"عَلَى الْخَلِيفَةِ",uz:"xalifaga qarshi"}],full_uz:"Odamlarni xalifaga qarshi qo‘zg‘atishni istamaymiz.",note:"أَثَارَ النَّاسَ عَلَى — «odamlarni ...ga qarshi qo‘zg‘atdi»."},
{num:79,time:"00:06:25,680 --> 00:06:28,939",arabic:"فَرُبَّمَا حَدَثَ فَسَادٌ أَكْبَرُ مِمَّا هُوَ وَاقِعٌ الْآنَ.",segs:[{ar:"فَرُبَّمَا حَدَثَ",uz:"chunki yuz berishi mumkin"},{ar:"فَسَادٌ أَكْبَرُ",uz:"kattaroq buzilish"},{ar:"مِمَّا هُوَ وَاقِعٌ الْآنَ",uz:"hozir yuz berayotganidan"}],full_uz:"Chunki hozir yuz berayotganidan kattaroq buzilish yuz berishi mumkin.",note:"رُبَّمَا — «ehtimol, mumkin». وَاقِعٌ — yuz berayotgan, mavjud."},
{num:80,time:"00:06:28,939 --> 00:06:33,680",arabic:"وَهَلْ هُنَاكَ فَسَادٌ وَظُلْمٌ أَشَدُّ مِمَّا يَقَعُ؟",segs:[{ar:"وَهَلْ هُنَاكَ فَسَادٌ وَظُلْمٌ",uz:"buzilish va zulm bormi"},{ar:"أَشَدُّ مِمَّا يَقَعُ",uz:"yuz berayotganidan og‘irroq"}],full_uz:"Hozir yuz berayotganidan og‘irroq buzilish va zulm bormi?",note:"أَشَدُّ — «kuchliroq, og‘irroq». So‘roq bu yerda inkor va e’tirozni bildiradi."},
{num:81,time:"00:06:33,680 --> 00:06:40,780",arabic:"أَنُثِيرُ النَّاسَ عَلَى السُّلْطَانِ حِينَ نَنْتَصِرُ لِدِينِنَا ضِدَّ الْمُبْتَدِعَةِ؟",segs:[{ar:"أَنُثِيرُ النَّاسَ عَلَى السُّلْطَانِ",uz:"odamlarni sultonga qarshi qo‘zg‘atgan bo‘lamizmi"},{ar:"حِينَ نَنْتَصِرُ لِدِينِنَا",uz:"dinimizni himoya qilganimizda"},{ar:"ضِدَّ الْمُبْتَدِعَةِ",uz:"bid’atchilarga qarshi"}],full_uz:"Bid’atchilarga qarshi dinimizni himoya qilganimizda odamlarni sultonga qarshi qo‘zg‘atgan bo‘lamizmi?",note:"اِنْتَصَرَ لِـ — «...ni qo‘llab, himoya qilib chiqdi». أَنُثِيرُ boshidagi أَ so‘roq hamzasidir."},
{num:82,time:"00:06:40,780 --> 00:06:44,319",arabic:"الَّذِينَ أَطْلَقَ لَهُمُ الْحَبْلَ عَلَى غَارِبِهِ.",segs:[{ar:"الَّذِينَ أَطْلَقَ لَهُمُ",uz:"ularga qo‘yib bergan"},{ar:"الْحَبْلَ عَلَى غَارِبِهِ",uz:"jilovni butunlay"}],full_uz:"U jilovini butunlay qo‘yib yuborgan o‘sha kishilarga qarshi.",note:"أَطْلَقَ الْحَبْلَ عَلَى غَارِبِهِ — «to‘liq erkinlik berdi, nazoratsiz qo‘yib yubordi» ma’nosidagi ibora."},
{num:83,time:"00:06:44,319 --> 00:06:49,740",arabic:"أَنُثِيرُ النَّاسَ عَلَى السُّلْطَانِ حِينَ نُنْكِرُ عَلَيْهِ وَعَلَيْهِمْ...",segs:[{ar:"أَنُثِيرُ النَّاسَ عَلَى السُّلْطَانِ",uz:"odamlarni sultonga qarshi qo‘zg‘atgan bo‘lamizmi"},{ar:"حِينَ نُنْكِرُ عَلَيْهِ وَعَلَيْهِمْ",uz:"uning va ularning ishini qoralaganimizda"}],full_uz:"Uning va ularning ishini qoralaganimizda odamlarni sultonga qarshi qo‘zg‘atgan bo‘lamizmi...",note:"أَنْكَرَ عَلَيْهِ فِعْلَهُ — «uning ishini qoraladi, unga e’tiroz bildirdi»."},
{num:84,time:"00:06:49,740 --> 00:06:53,579",arabic:"مَا مَلَؤُوا بِهِ آذَانَ الْعَامَّةِ مِنَ الْكُفْرِ وَالضَّلَالِ؟",segs:[{ar:"مَا مَلَؤُوا بِهِ آذَانَ الْعَامَّةِ",uz:"ular xalqning quloqlarini to‘ldirgan narsani"},{ar:"مِنَ الْكُفْرِ وَالضَّلَالِ",uz:"kufr va adashishdan iborat"}],full_uz:"Ular xalqning quloqlarini to‘ldirgan kufr va adashishni qoralaganimizda?",note:"آذَانٌ — أُذُنٌ («quloq»)ning ko‘pligi. الْعَامَّةُ — oddiy xalq, keng omma."},
{num:85,time:"00:06:53,579 --> 00:06:59,579",arabic:"إِذَا كَانَ الْأَمْرُ كَمَا تَقُولُونَ فَأَهْلًا بِهَا وَنِعْمَتْ.",segs:[{ar:"إِذَا كَانَ الْأَمْرُ",uz:"agar vaziyat bo‘lsa"},{ar:"كَمَا تَقُولُونَ",uz:"siz aytayotgandek"},{ar:"فَأَهْلًا بِهَا وَنِعْمَتْ",uz:"uni mamnuniyat bilan qabul qilaman, u yaxshi ham"}],full_uz:"Agar vaziyat siz aytayotgandek bo‘lsa, uni mamnuniyat bilan qabul qilaman, u yaxshi ham.",note:"فَأَهْلًا بِهَا وَنِعْمَتْ bir holatni ma’qullab qabul qilishni bildiradi. ـهَا oldingi suhbatdagi fitna tushunchasiga ishora qilmoqda."},
{num:86,time:"00:06:59,579 --> 00:07:03,340",arabic:"يَبْدُو أَنَّ الْخُزَاعِيَّ يُغَرِّدُ خَارِجَ السِّرْبِ.",segs:[{ar:"يَبْدُو أَنَّ الْخُزَاعِيَّ",uz:"aftidan, Xuzo’iy"},{ar:"يُغَرِّدُ خَارِجَ السِّرْبِ",uz:"to‘dadan tashqarida sayramoqda"}],full_uz:"Aftidan, Xuzo’iy boshqalardan o‘zgacha yo‘l tutmoqda.",note:"يُغَرِّدُ خَارِجَ السِّرْبِ so‘zma-so‘z «qushlar to‘dasidan tashqarida sayraydi»; boshqalardan farqli yo‘l tutishni bildiradi."},
{num:87,time:"00:07:03,339 --> 00:07:08,500",arabic:"فَعُلَمَاءُ بَغْدَادَ مِنْ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ يَتَحَاشَوْنَ الِاصْطِدَامَ بِإِخْوَتِنَا.",segs:[{ar:"فَعُلَمَاءُ بَغْدَادَ",uz:"chunki Bag‘dod olimlari"},{ar:"مِنْ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ",uz:"Ahli sunna val jamoaga mansub"},{ar:"يَتَحَاشَوْنَ الِاصْطِدَامَ",uz:"to‘qnashishdan chetlanadilar"},{ar:"بِإِخْوَتِنَا",uz:"birodarlarimiz bilan"}],full_uz:"Chunki Ahli sunna val jamoaga mansub Bag‘dod olimlari birodarlarimiz bilan to‘qnashishdan chetlanadilar.",note:"تَحَاشَى — «o‘zini chetga oldi». اِصْطِدَامٌ — to‘qnashuv; bu yerda ochiq qarama-qarshilik."},
{num:88,time:"00:07:08,500 --> 00:07:15,279",arabic:"لَكِنَّ الْخُزَاعِيَّ لَهُ طَبْعٌ يَخْتَلِفُ وَجَدٌّ يُدِلُّ بِهِ عَلَى الْعَبَّاسِيِّينَ.",segs:[{ar:"لَكِنَّ الْخُزَاعِيَّ",uz:"lekin Xuzo’iyning"},{ar:"لَهُ طَبْعٌ يَخْتَلِفُ",uz:"tabiati boshqacha"},{ar:"وَجَدٌّ يُدِلُّ بِهِ",uz:"va faxr bilan tayanadigan bobosi bor"},{ar:"عَلَى الْعَبَّاسِيِّينَ",uz:"abbosiylar oldida"}],full_uz:"Lekin Xuzo’iyning tabiati boshqacha, abbosiylar oldida faxr bilan tayanadigan bobosi ham bor.",note:"أَدَلَّ بِهِ عَلَى فُلَانٍ — biror xizmat yoki yaqinlikka tayanib, falonchi oldida o‘zini dadil tutdi."},
{num:89,time:"00:07:15,279 --> 00:07:16,339",arabic:"كَيْفَ؟",segs:null,full_uz:"Qanday qilib?",note:null},
{num:90,time:"00:07:17,560 --> 00:07:22,199",arabic:"كَانَ جَدُّهُ، وَاسْمُهُ مَالِكُ بْنُ الْهَيْثَمِ، مِنْ أَكْبَرِ الدُّعَاةِ إِلَى دَوْلَةِ بَنِي الْعَبَّاسِ.",segs:[{ar:"كَانَ جَدُّهُ",uz:"uning bobosi edi"},{ar:"وَاسْمُهُ مَالِكُ بْنُ الْهَيْثَمِ",uz:"ismi Molik ibn Haysam bo‘lgan"},{ar:"مِنْ أَكْبَرِ الدُّعَاةِ",uz:"eng yirik da’vatchilardan biri"},{ar:"إِلَى دَوْلَةِ بَنِي الْعَبَّاسِ",uz:"Abbos avlodining davlatiga"}],full_uz:"Uning Molik ibn Haysam ismli bobosi Abbos avlodining davlatini qo‘llashga chaqirgan eng yirik da’vatchilardan biri edi.",note:"دُعَاةٌ — دَاعٍ ning ko‘pligi. Bu yerda siyosiy harakatga chaqirgan targ‘ibotchilar nazarda tutilgan."},
{num:91,time:"00:07:22,199 --> 00:07:25,319",arabic:"وَكَانَ أَبُوهُ يَغْشَاهُ أَهْلُ الْحَدِيثِ.",segs:[{ar:"وَكَانَ أَبُوهُ",uz:"otasining esa"},{ar:"يَغْشَاهُ أَهْلُ الْحَدِيثِ",uz:"huzuriga hadis ahli kelib turardi"}],full_uz:"Otasining huzuriga esa hadis ahli kelib turardi.",note:"غَشِيَهُ bu yerda «uning huzuriga keldi, ziyorat qildi» ma’nosida."},
{num:92,time:"00:07:25,319 --> 00:07:32,060",arabic:"وَقَدْ بَايَعُوهُ فِي سَنَةِ إِحْدَى وَمِئَتَيْنِ لِلْهِجْرَةِ عَلَى الْقِيَامِ بِالْأَمْرِ بِالْمَعْرُوفِ...",segs:[{ar:"وَقَدْ بَايَعُوهُ",uz:"ular unga bay’at qilganlar"},{ar:"فِي سَنَةِ إِحْدَى وَمِئَتَيْنِ لِلْهِجْرَةِ",uz:"hijriy ikki yuz birinchi yilda"},{ar:"عَلَى الْقِيَامِ",uz:"amalga oshirish uchun"},{ar:"بِالْأَمْرِ بِالْمَعْرُوفِ",uz:"yaxshilikka buyurishni"}],full_uz:"Hijriy 201-yilda yaxshilikka buyurishni amalga oshirish uchun unga bay’at qilganlar...",note:"بَايَعَهُ عَلَى — «unga bir ishni bajarish borasida bay’at berdi». Bay’at — sadoqat yoki itoat ahdi."},
{num:93,time:"00:07:32,060 --> 00:07:37,639",arabic:"وَالنَّهْيِ عَنِ الْمُنْكَرِ حِينَ كَثُرَ الشُّطَّارُ وَالدُّعَّارُ فِي غَيْبَةِ الْمَأْمُونِ عَنْ بَغْدَادَ.",segs:[{ar:"وَالنَّهْيِ عَنِ الْمُنْكَرِ",uz:"va yomonlikdan qaytarishni"},{ar:"حِينَ كَثُرَ الشُّطَّارُ وَالدُّعَّارُ",uz:"bezorilar va buzg‘unchilar ko‘payganida"},{ar:"فِي غَيْبَةِ الْمَأْمُونِ",uz:"Ma’mun yo‘qligida"},{ar:"عَنْ بَغْدَادَ",uz:"Bag‘dodda"}],full_uz:"Va yomonlikdan qaytarishni — Ma’mun Bag‘dodda yo‘qligida bezorilar va buzg‘unchilar ko‘paygan paytda.",note:"الشُّطَّارُ bu tarixiy kontekstda bezori yoki talonchilarni bildiradi. الدُّعَّارُ — buzg‘unchi, yomonlik qiluvchi kishilar."},
{num:94,time:"00:07:37,639 --> 00:07:43,560",arabic:"إِذَنْ فَهُوَ سَلِيلُ أُسْرَةٍ عَرِيقَةٍ فِي النِّزَاعَاتِ وَلَهُ سِجِلٌّ حَافِلٌ فِي الْمُطَارَحَاتِ.",segs:[{ar:"إِذَنْ فَهُوَ سَلِيلُ أُسْرَةٍ",uz:"demak, u bir oilaning avlodi"},{ar:"عَرِيقَةٍ فِي النِّزَاعَاتِ",uz:"nizolarda uzoq tarixga ega"},{ar:"وَلَهُ سِجِلٌّ حَافِلٌ",uz:"uning boy tarixi ham bor"},{ar:"فِي الْمُطَارَحَاتِ",uz:"bahs-munozaralarda"}],full_uz:"Demak, u nizolarda uzoq tarixga ega oilaning avlodi, bahs-munozaralarda ham boy tarixi bor.",note:"سَلِيلٌ — avlod, zurriyot. سِجِلٌّ حَافِلٌ — ko‘p voqea yoki faoliyatni o‘z ichiga olgan tarix."},
{num:95,time:"00:07:43,560 --> 00:07:45,079",arabic:"أَجَلْ يَا بَدْرُ.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"يَا بَدْرُ",uz:"ey Badr"}],full_uz:"Ha, Badr.",note:null},
{num:96,time:"00:07:45,079 --> 00:07:52,439",arabic:"وَلَكِنْ جَيِّدٌ أَنَّكَ اسْتَطَعْتَ إِخْرَاجَ أَحَدِهِمْ عَنْ صَمْتِهِ.",segs:[{ar:"وَلَكِنْ جَيِّدٌ أَنَّكَ اسْتَطَعْتَ",uz:"lekin siz uddalaganingiz yaxshi bo‘ldi"},{ar:"إِخْرَاجَ أَحَدِهِمْ عَنْ صَمْتِهِ",uz:"ulardan birini sukutdan chiqarishni"}],full_uz:"Lekin ulardan birini sukutdan chiqarishga muvaffaq bo‘lganingiz yaxshi bo‘ldi.",note:"أَخْرَجَهُ عَنْ صَمْتِهِ — «uni sukutini buzishga undadi, gapirtirdi»."},
{num:97,time:"00:07:52,439 --> 00:07:56,399",arabic:"حَتَّى وَلَوْ كَانَ أَحْمَدَ بْنَ نَصْرٍ الْخُزَاعِيَّ.",segs:[{ar:"حَتَّى وَلَوْ كَانَ",uz:"hatto u ...bo‘lsa ham"},{ar:"أَحْمَدَ بْنَ نَصْرٍ الْخُزَاعِيَّ",uz:"Ahmad ibn Nasr Xuzo’iy"}],full_uz:"Hatto u Ahmad ibn Nasr Xuzo’iy bo‘lsa ham.",note:"حَتَّى وَلَوْ — «hatto ...bo‘lsa ham»."},
{num:98,time:"00:07:56,399 --> 00:07:59,819",arabic:"وَهَذَا مَا كُنَّا نَنْتَظِرُهُ مُنْذُ زَمَنٍ.",segs:[{ar:"وَهَذَا مَا كُنَّا نَنْتَظِرُهُ",uz:"biz kutayotgan narsa shu edi"},{ar:"مُنْذُ زَمَنٍ",uz:"anchadan beri"}],full_uz:"Biz anchadan beri kutayotgan narsa shu edi.",note:null},
{num:99,time:"00:07:59,819 --> 00:08:08,160",arabic:"وَمَنْ تَرَكَ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ نَاسِيًا حَتَّى صَلَّى...",segs:[{ar:"وَمَنْ تَرَكَ",uz:"kim tark etsa"},{ar:"الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ",uz:"og‘iz chayish va burunga suv olishni"},{ar:"نَاسِيًا",uz:"unutgan holda"},{ar:"حَتَّى صَلَّى",uz:"hatto namoz o‘qib qo‘ysa"}],full_uz:"Kim og‘iz chayish va burunga suv olishni unutib, namoz o‘qib qo‘ysa...",note:"الْمَضْمَضَةُ — og‘izni suv bilan chayish. الِاسْتِنْشَاقُ — burunga suv tortish. نَاسِيًا hol: «unutgan holda»."},
{num:100,time:"00:08:08,160 --> 00:08:11,819",arabic:"ثُمَّ تَذَكَّرَ بَعْدَ أَنْ فَرَغَ مِنْ صَلَاتِهِ...",segs:[{ar:"ثُمَّ تَذَكَّرَ",uz:"keyin eslasa"},{ar:"بَعْدَ أَنْ فَرَغَ مِنْ صَلَاتِهِ",uz:"namozini tugatganidan so‘ng"}],full_uz:"Keyin namozini tugatganidan so‘ng eslasa...",note:"فَرَغَ مِنْ — «...ni tugatdi, ...dan bo‘shadi»."},
{num:101,time:"00:08:11,819 --> 00:08:16,439",arabic:"عَلَيْهِ أَنْ يَتَوَضَّأَ وَيَتَمَضْمَضَ وَيَسْتَنْشِقَ وَيُعِيدَ الصَّلَاةَ.",segs:[{ar:"عَلَيْهِ أَنْ يَتَوَضَّأَ",uz:"u tahorat olishi kerak"},{ar:"وَيَتَمَضْمَضَ وَيَسْتَنْشِقَ",uz:"og‘zini chayib, burniga suv olishi"},{ar:"وَيُعِيدَ الصَّلَاةَ",uz:"va namozni qayta o‘qishi"}],full_uz:"U tahorat olib, og‘zini chayishi, burniga suv olishi va namozni qayta o‘qishi kerak.",note:"عَلَيْهِ أَنْ — «u ...ishi kerak». أَعَادَ الصَّلَاةَ — «namozni qayta o‘qidi»."},
{num:102,time:"00:08:17,360 --> 00:08:20,519",arabic:"وَمَنْ تَذَكَّرَ وَهُوَ فِي الصَّلَاةِ...",segs:[{ar:"وَمَنْ تَذَكَّرَ",uz:"kim eslasa"},{ar:"وَهُوَ فِي الصَّلَاةِ",uz:"namoz o‘qiyotgan paytida"}],full_uz:"Kim namoz o‘qiyotgan paytida eslasa...",note:"وَهُوَ فِي الصَّلَاةِ — hol gapi; eslash qaysi vaziyatda yuz berganini bildiradi."},
{num:103,time:"00:08:20,519 --> 00:08:25,159",arabic:"انْصَرَفَ عَنْهَا وَتَوَضَّأَ وَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ صَلَّى.",segs:[{ar:"انْصَرَفَ عَنْهَا",uz:"namozdan chiqadi"},{ar:"وَتَوَضَّأَ",uz:"va tahorat oladi"},{ar:"وَتَمَضْمَضَ وَاسْتَنْشَقَ",uz:"og‘zini chayib, burniga suv oladi"},{ar:"ثُمَّ صَلَّى",uz:"keyin namoz o‘qiydi"}],full_uz:"Namozdan chiqib, tahorat oladi, og‘zini chayadi, burniga suv oladi, keyin namoz o‘qiydi.",note:"Fe’llar o‘tgan zamon shaklida bo‘lsa-da, oldingi shartning natijasini bildirib, umumiy qoida ma’nosida kelgan."},
{num:104,time:"00:08:25,159 --> 00:08:28,859",arabic:"هَيْ، أَنْتَ، مَاذَا تَفْعَلُ؟",segs:[{ar:"هَيْ، أَنْتَ",uz:"hoy, siz"},{ar:"مَاذَا تَفْعَلُ",uz:"nima qilyapsiz"}],full_uz:"Hoy, siz, nima qilyapsiz?",note:null},
{num:105,time:"00:08:28,859 --> 00:08:29,539",arabic:"أَنَا يَا شَيْخُ؟",segs:[{ar:"أَنَا",uz:"menmi"},{ar:"يَا شَيْخُ",uz:"ey ustoz"}],full_uz:"Menmi, ustoz?",note:null},
{num:106,time:"00:08:29,539 --> 00:08:30,419",arabic:"أَجَلْ، أَنْتَ.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"أَنْتَ",uz:"siz"}],full_uz:"Ha, siz.",note:null},
{num:107,time:"00:08:30,419 --> 00:08:32,340",arabic:"أَكْتُبُ مَا قُلْتَ يَا شَيْخُ.",segs:[{ar:"أَكْتُبُ مَا قُلْتَ",uz:"aytganlaringizni yozyapman"},{ar:"يَا شَيْخُ",uz:"ey ustoz"}],full_uz:"Aytganlaringizni yozyapman, ustoz.",note:"أَكْتُبُ — «men yozyapman»; اُكْتُبْ esa «yozing» degan buyruq shakli."},
{num:108,time:"00:08:32,340 --> 00:08:34,399",arabic:"اُمْحُ مَا كَتَبْتَ عَنِّي، رَحِمَكَ اللَّهُ.",segs:[{ar:"اُمْحُ مَا كَتَبْتَ عَنِّي",uz:"mendan yozib olgan narsangizni o‘chiring"},{ar:"رَحِمَكَ اللَّهُ",uz:"Alloh sizni rahmatiga olsin"}],full_uz:"Mendan yozib olgan narsangizni o‘chiring, Alloh sizni rahmatiga olsin.",note:"مَحَا — يَمْحُو — «o‘chirdi». Buyruq shaklida oxirgi و tushadi: اُمْحُ."},
{num:109,time:"00:08:34,399 --> 00:08:36,360",arabic:"كَمَا تَشَاءُ يَا إِمَامُ، سَأَفْعَلُ.",segs:[{ar:"كَمَا تَشَاءُ",uz:"xohlaganingizdek"},{ar:"يَا إِمَامُ",uz:"ey imom"},{ar:"سَأَفْعَلُ",uz:"shunday qilaman"}],full_uz:"Xohlaganingizdek, imom. Shunday qilaman.",note:null},
{num:110,time:"00:08:41,659 --> 00:08:45,779",arabic:"قُلْتُهَا لَكُمْ سَابِقًا وَسَأَقُولُهَا الْآنَ.",segs:[{ar:"قُلْتُهَا لَكُمْ سَابِقًا",uz:"buni sizlarga ilgari aytganman"},{ar:"وَسَأَقُولُهَا الْآنَ",uz:"hozir ham aytaman"}],full_uz:"Buni sizlarga ilgari aytganman, hozir ham aytaman.",note:null},
{num:111,time:"00:08:45,779 --> 00:08:47,980",arabic:"لَا تُقَلِّدُونِي.",segs:null,full_uz:"Menga taqlid qilmanglar.",note:"قَلَّدَ bu yerda birovning fikrini dalilini o‘rganmasdan qabul qilishni bildiradi. Taqiqdagi fe’lning ko‘plik nuni tushgan, ـنِي dagi ن esa olmoshdan oldingi nun."},
{num:112,time:"00:08:47,980 --> 00:08:52,560",arabic:"وَلَا تُقَلِّدُوا مَالِكًا وَلَا الشَّافِعِيَّ وَلَا الْأَوْزَاعِيَّ وَلَا الثَّوْرِيَّ.",segs:[{ar:"وَلَا تُقَلِّدُوا مَالِكًا",uz:"Molikka ham taqlid qilmanglar"},{ar:"وَلَا الشَّافِعِيَّ",uz:"Shofi’iyga ham"},{ar:"وَلَا الْأَوْزَاعِيَّ",uz:"Avzo’iyga ham"},{ar:"وَلَا الثَّوْرِيَّ",uz:"Savriyga ham"}],full_uz:"Molikka ham, Shofi’iyga ham, Avzo’iyga ham, Savriyga ham taqlid qilmanglar.",note:"لَا ning takrorlanishi taqiqning sanalgan har bir kishiga tegishli ekanini ta’kidlaydi."},
{num:113,time:"00:08:52,560 --> 00:08:56,240",arabic:"بَلْ خُذُوا مِنْ حَيْثُ أَخَذُوا.",segs:[{ar:"بَلْ خُذُوا",uz:"balki olinglar"},{ar:"مِنْ حَيْثُ أَخَذُوا",uz:"ular olgan manbadan"}],full_uz:"Balki ular olgan manbadan olinglar.",note:"خُذُوا — أَخَذَ fe’lining ko‘plik buyruq shakli. مِنْ حَيْثُ — «...gan joydan, manbadan»."},
{num:114,time:"00:08:56,240 --> 00:09:00,300",arabic:"حَسَنًا أَيُّهَا الْإِخْوَةُ.",segs:[{ar:"حَسَنًا",uz:"xo‘sh"},{ar:"أَيُّهَا الْإِخْوَةُ",uz:"ey birodarlar"}],full_uz:"Xo‘sh, birodarlar.",note:null},
{num:115,time:"00:09:00,300 --> 00:09:03,899",arabic:"سَنُعِيدُ مَا بَدَأْنَا بِهِ فِي بِدَايَةِ الدَّرْسِ.",segs:[{ar:"سَنُعِيدُ",uz:"takrorlaymiz"},{ar:"مَا بَدَأْنَا بِهِ",uz:"boshlagan narsamizni"},{ar:"فِي بِدَايَةِ الدَّرْسِ",uz:"darsning boshida"}],full_uz:"Dars boshida boshlagan mavzumizni takrorlaymiz.",note:"أَعَادَ — يُعِيدُ — «takrorladi, qayta qildi». بَدَأَ بِـ — «...bilan boshladi»."},
{num:116,time:"00:09:03,899 --> 00:09:07,000",arabic:"اِفْتَحُوا قَرَاطِيسَكُمْ.",segs:null,full_uz:"Varaqlaringizni ochinglar.",note:"قَرَاطِيسُ — قِرْطَاسٌ («yozuv varag‘i»)ning ko‘pligi."},
{num:117,time:"00:09:17,980 --> 00:09:34,800",arabic:"كُلُّ ذَلِكَ بِسَبَبِ جَمَاعَتِكَ الْمُعْتَزِلَةِ.",segs:[{ar:"كُلُّ ذَلِكَ",uz:"bularning barchasi"},{ar:"بِسَبَبِ جَمَاعَتِكَ الْمُعْتَزِلَةِ",uz:"sizning mu’taziliylar guruhingiz sababli"}],full_uz:"Bularning barchasi sizning mu’taziliylar guruhingiz sababli.",note:null},
{num:118,time:"00:09:34,800 --> 00:09:38,279",arabic:"أَنْتَ تَتَحَامَلُ عَلَى إِخْوَتِي يَا أَبَا لَيْثٍ.",segs:[{ar:"أَنْتَ تَتَحَامَلُ عَلَى إِخْوَتِي",uz:"siz birodarlarimga nohaq hujum qilyapsiz"},{ar:"يَا أَبَا لَيْثٍ",uz:"ey Abu Lays"}],full_uz:"Siz birodarlarimga nohaq hujum qilyapsiz, Abu Lays.",note:"تَحَامَلَ عَلَى — «bir kishiga xolis bo‘lmay, qattiq yoki nohaq munosabatda bo‘ldi»."},
{num:119,time:"00:09:38,279 --> 00:09:40,639",arabic:"أَتَحَامَلُ عَلَيْهِمْ؟",segs:null,full_uz:"Men ularga nohaq hujum qilyapmanmi?",note:"أَتَحَامَلُ — birinchi shaxs muzori’ shakli: «men nohaq munosabatda bo‘lyapman». So‘roq ohangi bilan e’tiroz bildirilmoqda."},
{num:120,time:"00:09:40,639 --> 00:09:45,920",arabic:"لَوْلَا تَسَلُّطُهُمْ عَلَى الْحُكْمِ وَطَرْدُهُمْ لِكُلِّ مَنْ لَا يَدِينُ بِأَفْكَارِهِمْ...",segs:[{ar:"لَوْلَا تَسَلُّطُهُمْ عَلَى الْحُكْمِ",uz:"agar ular hokimiyatni egallab olmaganida"},{ar:"وَطَرْدُهُمْ لِكُلِّ مَنْ",uz:"va har bir kishini haydamaganida"},{ar:"لَا يَدِينُ بِأَفْكَارِهِمْ",uz:"ularning fikrlariga e’tiqod qilmaydigan"}],full_uz:"Agar ular hokimiyatni egallab, fikrlariga e’tiqod qilmaydigan har bir kishini haydamaganida...",note:"تَسَلُّطٌ — hukmronlikni o‘rnatish, zo‘ravonlik bilan boshqarish. دَانَ بِـ — «...ga e’tiqod qildi»."},
{num:121,time:"00:09:45,919 --> 00:09:48,199",arabic:"لَكُنْتُ الْآنَ عَلَى رَأْسِ عَمَلِي.",segs:[{ar:"لَكُنْتُ الْآنَ",uz:"hozir bo‘lardim"},{ar:"عَلَى رَأْسِ عَمَلِي",uz:"o‘z ishimda"}],full_uz:"Hozir o‘z ishimda bo‘lardim.",note:"عَلَى رَأْسِ عَمَلِهِ — «o‘z ishida, xizmat vazifasini bajarib turgan holatda»."},
{num:122,time:"00:09:48,199 --> 00:09:52,740",arabic:"وَلَمْ أَحْتَجْ إِلَى تَدْرِيسِ بِضْعَةِ رِجَالٍ لَا يَفْقَهُونَ إِلَّا قَلِيلًا.",segs:[{ar:"وَلَمْ أَحْتَجْ",uz:"muhtoj bo‘lmasdim"},{ar:"إِلَى تَدْرِيسِ بِضْعَةِ رِجَالٍ",uz:"bir necha kishiga dars berishga"},{ar:"لَا يَفْقَهُونَ إِلَّا قَلِيلًا",uz:"juda oz tushunadigan"}],full_uz:"Juda oz tushunadigan bir necha kishiga dars berishga muhtoj bo‘lmasdim.",note:"أَحْتَاجُ fe’li لَمْ dan keyin أَحْتَجْ bo‘ladi. بِضْعَةُ odatda uchdan to‘qqizgacha bo‘lgan noaniq miqdorni bildiradi."},
{num:123,time:"00:09:52,740 --> 00:09:56,539",arabic:"الْمُعْتَزِلَةُ لَمْ يَتَسَلَّطُوا عَلَى الْحُكْمِ.",segs:[{ar:"الْمُعْتَزِلَةُ لَمْ يَتَسَلَّطُوا",uz:"mu’taziliylar egallab olmagan"},{ar:"عَلَى الْحُكْمِ",uz:"hokimiyatni"}],full_uz:"Mu’taziliylar hokimiyatni egallab olmagan.",note:"يَتَسَلَّطُونَ fe’li لَمْ dan keyin nunini yo‘qotadi: يَتَسَلَّطُوا."},
{num:124,time:"00:09:56,539 --> 00:09:59,599",arabic:"بَلْ إِنَّ أَمِيرَ الْمُؤْمِنِينَ، حَفِظَهُ اللَّهُ...",segs:[{ar:"بَلْ إِنَّ أَمِيرَ الْمُؤْمِنِينَ",uz:"balki mo‘minlar amiri"},{ar:"حَفِظَهُ اللَّهُ",uz:"Alloh uni asrasin"}],full_uz:"Balki mo‘minlar amiri — Alloh uni asrasin...",note:null},
{num:125,time:"00:09:59,599 --> 00:10:04,360",arabic:"هُوَ الَّذِي قَرَّبَهُمْ إِلَيْهِ بَعْدَ أَنْ أَنَارَ اللَّهُ بَصِيرَتَهُ وَهَدَاهُ إِلَى الْحَقِّ.",segs:[{ar:"هُوَ الَّذِي قَرَّبَهُمْ إِلَيْهِ",uz:"ularni o‘ziga yaqinlashtirgan aynan uning o‘zi"},{ar:"بَعْدَ أَنْ أَنَارَ اللَّهُ بَصِيرَتَهُ",uz:"Alloh uning qalb ko‘zini yoritganidan keyin"},{ar:"وَهَدَاهُ إِلَى الْحَقِّ",uz:"va uni haq yo‘lga boshlaganidan keyin"}],full_uz:"Alloh uning qalb ko‘zini yoritib, haq yo‘lga boshlaganidan keyin ularni o‘ziga yaqinlashtirgan aynan uning o‘zi.",note:"بَصِيرَةٌ — ichki idrok, qalb ko‘zi. أَنَارَ — «yoritdi»."},
{num:126,time:"00:10:04,360 --> 00:10:06,799",arabic:"وَرَأَى فِيهِمْ إِخْلَاصًا لَيْسَ لِغَيْرِهِمْ.",segs:[{ar:"وَرَأَى فِيهِمْ إِخْلَاصًا",uz:"ularda sadoqatni ko‘rdi"},{ar:"لَيْسَ لِغَيْرِهِمْ",uz:"boshqalarda bo‘lmagan"}],full_uz:"Ularda boshqalarda bo‘lmagan sadoqatni ko‘rdi.",note:"إِخْلَاصٌ bu yerda sadoqat va sidqidildan xizmat qilishni anglatadi."},
{num:127,time:"00:10:06,799 --> 00:10:11,639",arabic:"ثُمَّ أَلَا تَرَى الْفَرْقَ بَيْنَ أَنْ يَكُونَ الْمُعْتَزِلَةُ فِي الْحُكْمِ...",segs:[{ar:"ثُمَّ أَلَا تَرَى الْفَرْقَ",uz:"qolaversa, farqni ko‘rmayapsizmi"},{ar:"بَيْنَ أَنْ يَكُونَ الْمُعْتَزِلَةُ فِي الْحُكْمِ",uz:"mu’taziliylar hokimiyatda bo‘lishi orasidagi"}],full_uz:"Qolaversa, mu’taziliylar hokimiyatda bo‘lishi bilan ...orasidagi farqni ko‘rmayapsizmi?",note:"بَيْنَ ... وَبَيْنَ tuzilishi ikki holatni qiyoslaydi. Ikkinchi holat keyingi bandda keladi."},
{num:128,time:"00:10:11,639 --> 00:10:13,539",arabic:"وَبَيْنَ أَنْ يَكُونَ غَيْرُهُمْ؟",segs:null,full_uz:"Boshqalar hokimiyatda bo‘lishi orasidagi?",note:"فِي الْحُكْمِ oldingi banddan tushunilgani uchun bu yerda takrorlanmagan."},
{num:129,time:"00:10:13,539 --> 00:10:15,459",arabic:"نَعَمْ، رَأَيْتُ الْفَرْقَ.",segs:[{ar:"نَعَمْ",uz:"ha"},{ar:"رَأَيْتُ الْفَرْقَ",uz:"farqni ko‘rdim"}],full_uz:"Ha, farqni ko‘rdim.",note:null},
{num:130,time:"00:10:15,460 --> 00:10:17,160",arabic:"طَرَدُونَا مِنْ أَعْمَالِنَا.",segs:[{ar:"طَرَدُونَا",uz:"bizni haydadilar"},{ar:"مِنْ أَعْمَالِنَا",uz:"ishlarimizdan"}],full_uz:"Bizni ishlarimizdan haydadilar.",note:null},
{num:131,time:"00:10:17,160 --> 00:10:21,500",arabic:"وَجَزَاكُمُ اللَّهُ خَيْرًا أَنْ مَنَحْتُمُونَا حَقَّ الْحَيَاةِ وَحَقَّ الْكَلَامِ.",segs:[{ar:"وَجَزَاكُمُ اللَّهُ خَيْرًا",uz:"Alloh sizlarni yaxshilik bilan mukofotlasin"},{ar:"أَنْ مَنَحْتُمُونَا",uz:"bizga berganingiz uchun"},{ar:"حَقَّ الْحَيَاةِ وَحَقَّ الْكَلَامِ",uz:"yashash va gapirish huquqini"}],full_uz:"Bizga yashash va gapirish huquqini berganingiz uchun Alloh sizlarni yaxshilik bilan mukofotlasin.",note:"Bu suhbatda duo shaklidagi gap kinoya bilan aytilmoqda. مَنَحَ — «berdi, ato etdi»."},
{num:132,time:"00:10:21,500 --> 00:10:28,120",arabic:"ثُمَّ مَنْ قَالَ إِنَّ أَهْلَ الْحَدِيثِ قَدْ طَارَدُوكُمْ؟",segs:[{ar:"ثُمَّ مَنْ قَالَ",uz:"qolaversa, kim aytdi"},{ar:"إِنَّ أَهْلَ الْحَدِيثِ قَدْ طَارَدُوكُمْ",uz:"hadis ahli sizlarni ta’qib qilgan deb"}],full_uz:"Qolaversa, hadis ahli sizlarni ta’qib qilgan deb kim aytdi?",note:"طَارَدَ — «ta’qib qildi, ortidan quvdi». طَرَدَ esa «haydab yubordi»."},
{num:133,time:"00:10:28,120 --> 00:10:31,820",arabic:"وَأَلَّبُوا السُّلْطَانَ عَلَيْكُمْ وَقَلَبُوا لَكُمْ ظَهْرَ الْمِجَنِّ؟",segs:[{ar:"وَأَلَّبُوا السُّلْطَانَ عَلَيْكُمْ",uz:"va sultonni sizlarga qarshi qayradilar deb"},{ar:"وَقَلَبُوا لَكُمْ ظَهْرَ الْمِجَنِّ",uz:"va sizlarga dushmanlik qila boshladilar deb"}],full_uz:"Va sultonni sizlarga qarshi qayrab, sizlarga dushmanlik qila boshladilar deb?",note:"أَلَّبَ عَلَيْهِ — «unga qarshi qayradi». قَلَبَ لَهُ ظَهْرَ الْمِجَنِّ — do‘stlikdan dushmanlikka o‘tish; الْمِجَنُّ — qalqon."},
{num:134,time:"00:10:31,820 --> 00:10:37,440",arabic:"إِنَّ أَهْلَ الْحَدِيثِ أَوْعَى مِنْ حَمَاقَتِكُمْ وَأَعْقَلُ مِنْ جَهَالَتِكُمْ.",segs:[{ar:"إِنَّ أَهْلَ الْحَدِيثِ",uz:"hadis ahli"},{ar:"أَوْعَى مِنْ حَمَاقَتِكُمْ",uz:"sizning ahmoqligingizdan ko‘ra hushyorroq"},{ar:"وَأَعْقَلُ مِنْ جَهَالَتِكُمْ",uz:"va johilligingizdan ko‘ra oqilroq"}],full_uz:"Hadis ahli sizning ahmoqligingizdan ko‘ra hushyorroq, johilligingizdan ko‘ra oqilroq.",note:"أَوْعَى — «hushyorroq, yaxshiroq anglaydigan»; أَعْقَلُ — «oqilroq»."},
{num:135,time:"00:10:37,440 --> 00:10:43,900",arabic:"إِنَّ الْإِمَامَ الشَّافِعِيَّ عَلَى الرَّغْمِ مِنْ قَرَابَتِهِ لِهَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ...",segs:[{ar:"إِنَّ الْإِمَامَ الشَّافِعِيَّ",uz:"imom Shofi’iy"},{ar:"عَلَى الرَّغْمِ مِنْ قَرَابَتِهِ لِهَارُونَ الرَّشِيدِ",uz:"Horun Rashidga qarindoshligiga qaramay"},{ar:"رَحِمَهُ اللَّهُ",uz:"Alloh uni rahmatiga olsin"}],full_uz:"Imom Shofi’iy Horun Rashidga qarindoshligiga qaramay — Alloh uni rahmatiga olsin...",note:"عَلَى الرَّغْمِ مِنْ — «...ga qaramay». قَرَابَةٌ — qarindoshlik."},
{num:136,time:"00:10:43,899 --> 00:10:47,279",arabic:"إِلَّا أَنَّهُ لَمْ يُحَرِّضْهُ يَوْمًا عَلَيْكُمْ.",segs:[{ar:"إِلَّا أَنَّهُ لَمْ يُحَرِّضْهُ",uz:"biroq uni qayramagan"},{ar:"يَوْمًا عَلَيْكُمْ",uz:"biror kun ham sizlarga qarshi"}],full_uz:"Biroq biror kun ham uni sizlarga qarshi qayramagan.",note:"حَرَّضَهُ عَلَى — «uni ...ga qarshi undadi, qayradi». يَوْمًا inkor bilan «hech qachon» ma’nosini kuchaytiradi."},
{num:137,time:"00:10:47,279 --> 00:10:54,799",arabic:"إِذَنْ مَنِ الَّذِي أَغْرَى الرَّشِيدَ وَابْنَهُ الْأَمِينَ بِالتَّضْيِيقِ عَلَيْنَا؟",segs:[{ar:"إِذَنْ مَنِ الَّذِي أَغْرَى",uz:"unday bo‘lsa, kim undadi"},{ar:"الرَّشِيدَ وَابْنَهُ الْأَمِينَ",uz:"Rashid va uning o‘g‘li Aminni"},{ar:"بِالتَّضْيِيقِ عَلَيْنَا",uz:"bizni siquvga olishga"}],full_uz:"Unday bo‘lsa, Rashid va uning o‘g‘li Aminni bizni siquvga olishga kim undadi?",note:"أَغْرَاهُ بِـ — «uni ...ga undadi, qiziqtirdi». ضَيَّقَ عَلَيْهِ — «uni siquvga oldi»."},
{num:138,time:"00:10:54,799 --> 00:11:01,199",arabic:"رُبَّمَا رَأَوْا أَنَّ فِي انْتِشَارِ أَفْكَارِكُمُ الضَّالَّةِ تَفْرِيقًا لِكَلِمَةِ الْمُسْلِمِينَ وَإِفْسَادًا لِدِينِهِمْ.",segs:[{ar:"رُبَّمَا رَأَوْا أَنَّ",uz:"ehtimol, ular deb bilgandir"},{ar:"فِي انْتِشَارِ أَفْكَارِكُمُ الضَّالَّةِ",uz:"adashgan fikrlaringiz tarqalishida bor"},{ar:"تَفْرِيقًا لِكَلِمَةِ الْمُسْلِمِينَ",uz:"musulmonlar birligini buzish"},{ar:"وَإِفْسَادًا لِدِينِهِمْ",uz:"va ularning dinini buzish"}],full_uz:"Ehtimol, ular adashgan fikrlaringiz tarqalishi musulmonlar birligi va dinini buzadi deb bilgandir.",note:"كَلِمَةُ الْمُسْلِمِينَ bu yerda musulmonlarning birligi, yakdilligini bildiradi."},
{num:139,time:"00:11:01,199 --> 00:11:03,659",arabic:"وَإِشْغَالَهُمْ بِمَا لَا يَنْفَعُ.",segs:[{ar:"وَإِشْغَالَهُمْ",uz:"va ularni band qilish"},{ar:"بِمَا لَا يَنْفَعُ",uz:"foydasiz narsalar bilan"}],full_uz:"Va ularni foydasiz narsalar bilan band qiladi deb.",note:"إِشْغَالٌ — أَشْغَلَ («band qildi») fe’lining masdari."},
{num:140,time:"00:11:03,659 --> 00:11:09,199",arabic:"قُلْ لِي بِرَبِّكَ، مَا خَوْضُكُمْ فِي عَالَمِ الْغَيْبِ وَأَنْتُمْ لَا تُدْرِكُونَ عِلْمَ الشَّهَادَةِ؟",segs:[{ar:"قُلْ لِي بِرَبِّكَ",uz:"Rabbingiz haqqi, menga ayting"},{ar:"مَا خَوْضُكُمْ فِي عَالَمِ الْغَيْبِ",uz:"g‘ayb olamiga bahs bilan kirishishingiz nimasi"},{ar:"وَأَنْتُمْ لَا تُدْرِكُونَ",uz:"holbuki, siz anglamaysiz"},{ar:"عِلْمَ الشَّهَادَةِ",uz:"ko‘rinadigan olam haqidagi ilmni"}],full_uz:"Rabbingiz haqqi, ayting: ko‘rinadigan olam haqidagi ilmni anglamay turib, g‘ayb olami haqida bahslashishingiz nimasi?",note:"الْغَيْبُ — sezgilardan yashirin narsa. الشَّهَادَةُ bu qarama-qarshilikda ko‘rinadigan, kuzatiladigan olamni bildiradi."},
{num:141,time:"00:11:09,199 --> 00:11:12,500",arabic:"كَفَاكُمْ سَفَهًا وَضَلَالًا يَا رَجُلُ.",segs:[{ar:"كَفَاكُمْ سَفَهًا وَضَلَالًا",uz:"ahmoqlik va adashishingiz yetar"},{ar:"يَا رَجُلُ",uz:"ey odam"}],full_uz:"Ahmoqlik va adashishingiz yetar, ey odam.",note:"كَفَاكَ — «sizga yetar». سَفَهًا وَضَلَالًا nimaning yetarli bo‘lganini aniqlaydi."},
{num:142,time:"00:11:12,500 --> 00:11:26,860",arabic:"مَا لِي أَرَى لِسَانَكَ قَدْ عَجَزَ عَنِ الْكَلَامِ؟",segs:[{ar:"مَا لِي أَرَى",uz:"nega ko‘ryapman"},{ar:"لِسَانَكَ قَدْ عَجَزَ",uz:"tilingiz ojiz qolganini"},{ar:"عَنِ الْكَلَامِ",uz:"gapirishdan"}],full_uz:"Nega tilingiz gapirishga ojiz qolganini ko‘ryapman?",note:"مَا لِي أَرَى — ajablanish bilan holat sababini so‘rash usuli. عَجَزَ عَنْ — «...ga ojiz bo‘ldi»."},
{num:143,time:"00:11:26,860 --> 00:11:30,139",arabic:"لَا، لَمْ يَعْجَزْ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"لَمْ يَعْجَزْ",uz:"ojiz qolgani yo‘q"}],full_uz:"Yo‘q, ojiz qolgani yo‘q.",note:null},
{num:144,time:"00:11:30,139 --> 00:11:34,659",arabic:"وَلَكِنَّ الْجِدَالَ مَعَ أَخِي الْجَهَالَةِ لَا يَنْفَعُ.",segs:[{ar:"وَلَكِنَّ الْجِدَالَ",uz:"lekin bahslashish"},{ar:"مَعَ أَخِي الْجَهَالَةِ",uz:"johillik sohibi bilan"},{ar:"لَا يَنْفَعُ",uz:"foyda bermaydi"}],full_uz:"Lekin johillik sohibi bilan bahslashish foyda bermaydi.",note:"أَخُو الْجَهَالَةِ so‘zma-so‘z «johillikning birodari»; bu yerda johillik unga xos bo‘lgan kishi nazarda tutilgan."},
{num:145,time:"00:11:37,059 --> 00:11:40,639",arabic:"تُذَكِّرُنِي بِأَبْيَاتٍ لِلشَّافِعِيِّ يَقُولُ فِيهَا...",segs:[{ar:"تُذَكِّرُنِي بِأَبْيَاتٍ لِلشَّافِعِيِّ",uz:"menga Shofi’iyning baytlarini eslatyapsiz"},{ar:"يَقُولُ فِيهَا",uz:"ularda u aytadi"}],full_uz:"Menga Shofi’iyning baytlarini eslatyapsiz. Ularda u aytadi...",note:"أَبْيَاتٌ — بَيْتٌ ning she’r misralari haqidagi ko‘pligi. ذَكَّرَهُ بِـ — «unga ...ni eslatdi»."},
{num:146,time:"00:11:40,639 --> 00:11:43,559",arabic:"يُخَاطِبُنِي السَّفِيهُ بِكُلِّ قُبْحٍ.",segs:[{ar:"يُخَاطِبُنِي السَّفِيهُ",uz:"nodon menga murojaat qiladi"},{ar:"بِكُلِّ قُبْحٍ",uz:"har xil xunuk so‘z bilan"}],full_uz:"Nodon menga har xil xunuk so‘z bilan murojaat qiladi.",note:"خَاطَبَ — «murojaat qildi, so‘zladi». قُبْحٌ — xunuklik, yomonlik."},
{num:147,time:"00:11:43,559 --> 00:11:46,059",arabic:"فَأَكْرَهُ أَنْ أَكُونَ لَهُ مُجِيبًا.",segs:[{ar:"فَأَكْرَهُ",uz:"men esa istamayman"},{ar:"أَنْ أَكُونَ لَهُ مُجِيبًا",uz:"unga javob beruvchi bo‘lishni"}],full_uz:"Men esa unga javob berishni istamayman.",note:"مُجِيبٌ — أَجَابَ («javob berdi») fe’lining ismi foili."},
{num:148,time:"00:11:46,059 --> 00:11:49,819",arabic:"يَزِيدُ سَفَاهَةً فَأَزِيدُ حِلْمًا.",segs:[{ar:"يَزِيدُ سَفَاهَةً",uz:"u nodonligini oshiradi"},{ar:"فَأَزِيدُ حِلْمًا",uz:"men esa bosiqligimni oshiraman"}],full_uz:"U nodonligini oshiradi, men esa bosiqligimni oshiraman.",note:"حِلْمٌ — bosiqlik, g‘azabni tiyish. حُلْمٌ esa «tush» ma’nosida kelishi mumkin."},
{num:149,time:"00:11:49,819 --> 00:11:52,779",arabic:"كَعُودٍ زَادَهُ الْإِحْرَاقُ طِيبًا.",segs:[{ar:"كَعُودٍ",uz:"ud yog‘ochidek"},{ar:"زَادَهُ الْإِحْرَاقُ طِيبًا",uz:"yonish uning xushbo‘yligini oshirgan"}],full_uz:"Yonish xushbo‘yligini oshiradigan ud yog‘ochidek.",note:"عُودٌ bu yerda yoqilganda xushbo‘y hid taratadigan yog‘och. طِيبًا — xushbo‘ylik jihatidan ortishni bildiruvchi tamyiz."},
{num:150,time:"00:11:52,779 --> 00:12:04,039",arabic:"لَا بَأْسَ عَلَيْكَ يَا أَبَا مَعْنٍ.",segs:[{ar:"لَا بَأْسَ عَلَيْكَ",uz:"sizga zarar yetmasin"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"}],full_uz:"Dardingiz yengil bo‘lsin, Abu Ma’n.",note:"لَا بَأْسَ عَلَيْكَ — bemorga taskin va yaxshi tilak bildirish iborasi."},
{num:151,time:"00:12:04,039 --> 00:12:08,139",arabic:"لَوْلَا أَنَّ بَدْرًا الْكَلَاعِيَّ أَخْبَرَنِي أَنَّكَ مُتَوَعِّكٌ...",segs:[{ar:"لَوْلَا أَنَّ بَدْرًا الْكَلَاعِيَّ أَخْبَرَنِي",uz:"agar Badr Kalo’iy menga aytmaganida"},{ar:"أَنَّكَ مُتَوَعِّكٌ",uz:"betob ekaningizni"}],full_uz:"Agar Badr Kalo’iy menga betob ekaningizni aytmaganida...",note:"مُتَوَعِّكٌ — betob, mazasi qochgan. تَوَعَّكَ — betob bo‘ldi."},
{num:152,time:"00:12:08,139 --> 00:12:09,379",arabic:"لَمَا عَلِمْتُ بِذَلِكَ.",segs:null,full_uz:"Bundan xabar topmagan bo‘lardim.",note:"لَمَا oldingi لَوْلَا shartining inkorli javobini bildiradi."},
{num:153,time:"00:12:09,379 --> 00:12:12,120",arabic:"الْحَمْدُ لِلَّهِ عَلَى أَيِّ حَالٍ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"عَلَى أَيِّ حَالٍ",uz:"har qanday holatda"}],full_uz:"Har qanday holatda Allohga hamd bo‘lsin.",note:null},
{num:154,time:"00:12:12,120 --> 00:12:13,840",arabic:"الْحَمْدُ لِلَّهِ.",segs:null,full_uz:"Allohga hamd bo‘lsin.",note:null},
{num:155,time:"00:12:13,840 --> 00:12:16,639",arabic:"وَكَيْفَ أَنْتَ الْآنَ بَعْدَ أَنْ رَآكَ الطَّبِيبُ؟",segs:[{ar:"وَكَيْفَ أَنْتَ الْآنَ",uz:"hozir ahvolingiz qanday"},{ar:"بَعْدَ أَنْ رَآكَ الطَّبِيبُ",uz:"tabib sizni ko‘rganidan keyin"}],full_uz:"Tabib sizni ko‘rganidan keyin hozir ahvolingiz qanday?",note:null},
{num:156,time:"00:12:18,639 --> 00:12:23,820",arabic:"الْحَقَّ أَقُولُ لَكَ يَا صَاحِبِي: إِنَّنِي أَجِدُ نَفْسِي إِلَى نُقْصَانٍ.",segs:[{ar:"الْحَقَّ أَقُولُ لَكَ",uz:"sizga rostini aytaman"},{ar:"يَا صَاحِبِي",uz:"ey do‘stim"},{ar:"إِنَّنِي أَجِدُ نَفْسِي",uz:"o‘zimni his qilyapman"},{ar:"إِلَى نُقْصَانٍ",uz:"tobora zaiflashib borayotgan"}],full_uz:"Sizga rostini aytaman, do‘stim: o‘zimni tobora zaiflashib borayotgandek his qilyapman.",note:"الْحَقَّ — أَقُولُ fe’lining oldinga chiqarilgan to‘ldiruvchisi. نُقْصَانٌ — kamayish, bu yerda quvvatning pasayishi."},
{num:157,time:"00:12:23,820 --> 00:12:26,639",arabic:"الطَّبِيبُ هُوَ اللَّهُ سُبْحَانَهُ.",segs:[{ar:"الطَّبِيبُ هُوَ اللَّهُ",uz:"shifo beruvchi Allohning O‘zidir"},{ar:"سُبْحَانَهُ",uz:"U pokdir"}],full_uz:"Shifo beruvchi Allohning O‘zidir, U pokdir.",note:"الطَّبِيبُ lug‘aviy ma’noda «tabib»; bu gapda shifo beruvchi ma’nosi nazarda tutilmoqda."},
{num:158,time:"00:12:27,240 --> 00:12:29,639",arabic:"وَنَسْأَلُ اللَّهَ حُسْنَ الْخِتَامِ.",segs:[{ar:"وَنَسْأَلُ اللَّهَ",uz:"Allohdan so‘raymiz"},{ar:"حُسْنَ الْخِتَامِ",uz:"yaxshi xotimani"}],full_uz:"Allohdan yaxshi xotima so‘raymiz.",note:"حُسْنُ الْخِتَامِ — hayotning yaxshi yakun topishi."},
{num:159,time:"00:12:30,179 --> 00:12:34,639",arabic:"لَا تَقُلْ مِثْلَ هَذَا الْكَلَامِ يَا أَبَا مَعْنٍ، أَمْتَعَ اللَّهُ بِكَ.",segs:[{ar:"لَا تَقُلْ مِثْلَ هَذَا الْكَلَامِ",uz:"bunday gaplarni aytmang"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"},{ar:"أَمْتَعَ اللَّهُ بِكَ",uz:"Alloh sizdan bahramand bo‘lishni davomli qilsin"}],full_uz:"Bunday gaplarni aytmang, Abu Ma’n. Alloh bizni sizdan uzoq bahramand qilsin.",note:"أَمْتَعَ اللَّهُ بِكَ — kishining umri va foydasi davom etishini tilab aytiladigan duo."},
{num:160,time:"00:12:34,639 --> 00:12:44,080",arabic:"إِنَّمَا عَزَائِي أَنَّنِي رَأَيْتُ كَيْفَ أَعَزَّ اللَّهُ مَذْهَبَنَا.",segs:[{ar:"إِنَّمَا عَزَائِي",uz:"mening taskinim shuki"},{ar:"أَنَّنِي رَأَيْتُ",uz:"men ko‘rdim"},{ar:"كَيْفَ أَعَزَّ اللَّهُ مَذْهَبَنَا",uz:"Alloh mazhabimizni qanday yuksaltirganini"}],full_uz:"Mening taskinim — Alloh mazhabimizni qanday yuksaltirganini ko‘rganimdir.",note:"عَزَاءٌ — taskin, tasalli. أَعَزَّ — «aziz, qudratli qildi»."},
{num:161,time:"00:12:44,080 --> 00:12:49,939",arabic:"وَنَصَرَنَا عَلَى أَهْلِ الْكُفْرِ وَالضَّلَالَةِ وَأَنَا حَيٌّ.",segs:[{ar:"وَنَصَرَنَا",uz:"va bizni g‘olib qilganini"},{ar:"عَلَى أَهْلِ الْكُفْرِ وَالضَّلَالَةِ",uz:"kufr va adashish ahli ustidan"},{ar:"وَأَنَا حَيٌّ",uz:"men tirikligimda"}],full_uz:"Va men tirikligimda bizni kufr va adashish ahli ustidan g‘olib qilganini.",note:"نَصَرَهُ عَلَى — «uni ...ustidan g‘olib qildi». وَأَنَا حَيٌّ hol gapidir."},
{num:162,time:"00:12:49,939 --> 00:12:52,919",arabic:"كُلُّ ذَلِكَ لَمْ يَكُنْ لَوْلَا فَضْلُ اللَّهِ.",segs:[{ar:"كُلُّ ذَلِكَ لَمْ يَكُنْ",uz:"bularning barchasi bo‘lmagan bo‘lardi"},{ar:"لَوْلَا فَضْلُ اللَّهِ",uz:"Allohning fazli bo‘lmaganida"}],full_uz:"Allohning fazli bo‘lmaganida, bularning barchasi bo‘lmagan bo‘lardi.",note:"لَوْلَا — bir narsa mavjud bo‘lgani uchun boshqa natija yuz bermaganini ifodalaydi."},
{num:163,time:"00:12:52,919 --> 00:12:57,460",arabic:"ثُمَّ مَا بَذَلْتَهُ مِنْ نُصْحٍ وَإِرْشَادٍ يَا ابْنَ الْأَشْرَسِ.",segs:[{ar:"ثُمَّ مَا بَذَلْتَهُ",uz:"so‘ng siz qilgan sa’y-harakat"},{ar:"مِنْ نُصْحٍ وَإِرْشَادٍ",uz:"nasihat va yo‘l-yo‘riq berishdagi"},{ar:"يَا ابْنَ الْأَشْرَسِ",uz:"ey Ibn Ashras"}],full_uz:"So‘ng sizning nasihat va yo‘l-yo‘riq berishdagi sa’y-harakatingiz bo‘lmaganida, Ibn Ashras.",note:"بَذَلَ — «sarfladi, borini berdi». Bu yerda vaqt va kuch sarflab nasihat qilish nazarda tutilgan."},
{num:164,time:"00:12:57,460 --> 00:13:01,319",arabic:"كُلُّكُمْ مُحْسِنٌ يَا أَبَا عَبْدِ الرَّحْمَٰنِ.",segs:[{ar:"كُلُّكُمْ مُحْسِنٌ",uz:"har biringiz yaxshilik qilgansiz"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَٰنِ",uz:"ey Abu Abdurahmon"}],full_uz:"Har biringiz yaxshilik qilgansiz, Abu Abdurahmon.",note:"كُلُّكُمْ har bir kishini alohida qamrab olgani uchun xabar birlikdagi مُحْسِنٌ shaklida kelishi mumkin."},
{num:165,time:"00:13:01,320 --> 00:13:06,480",arabic:"وَأَرْجُو أَلَّا يُخَيِّبَ اللَّهُ مَسْعَاكُمْ.",segs:[{ar:"وَأَرْجُو",uz:"umid qilaman"},{ar:"أَلَّا يُخَيِّبَ اللَّهُ مَسْعَاكُمْ",uz:"Alloh sa’y-harakatingizni zoye ketkazmasligini"}],full_uz:"Alloh sa’y-harakatingizni zoye ketkazmasligini umid qilaman.",note:"مَسْعًى — intilish, sa’y-harakat. خَيَّبَ — umidni puchga chiqardi, muvaffaqiyatsiz qoldirdi."},
{num:166,time:"00:13:06,480 --> 00:13:10,420",arabic:"وَلَا يُغِرَّ صَدْرَ أَمِيرِ الْمُؤْمِنِينَ عَلَيْكُمْ.",segs:[{ar:"وَلَا يُغِرَّ صَدْرَ أَمِيرِ الْمُؤْمِنِينَ",uz:"va mo‘minlar amirining ko‘nglini gina bilan to‘ldirmasligini"},{ar:"عَلَيْكُمْ",uz:"sizlarga qarshi"}],full_uz:"Va mo‘minlar amirining ko‘nglini sizlarga qarshi gina bilan to‘ldirmasligini.",note:"أَوْغَرَ صَدْرَهُ عَلَيْهِ — «uning ko‘nglida unga qarshi gina yoki adovat uyg‘otdi». Muzori’si يُوغِرُ; jazm yoki nasbga emas, aynan أَرْجُو أَلَّا tuzilishiga bog‘langanda يُوغِرَ bo‘ladi."},
{num:167,time:"00:13:10,420 --> 00:13:16,400",arabic:"فَفَوَاتُ جَنَابِ السُّلْطَانِ ضَيَاعٌ وَخِذْلَانٌ.",segs:[{ar:"فَفَوَاتُ جَنَابِ السُّلْطَانِ",uz:"chunki sulton homiyligidan mahrum bo‘lish"},{ar:"ضَيَاعٌ وَخِذْلَانٌ",uz:"yo‘qotish va yordamsiz qolishdir"}],full_uz:"Chunki sulton homiyligidan mahrum bo‘lish — yo‘qotish va yordamsiz qolishdir.",note:"جَنَابُ السُّلْطَانِ bu yerda hukmdorning yaqini va himoyasini anglatadi. خِذْلَانٌ — yordamga muhtoj paytda tashlab qo‘yish."},
{num:168,time:"00:13:16,400 --> 00:13:19,860",arabic:"لَا تَخَفْ، أَنَا حَرِيصٌ مِنْ هَذِهِ النَّاحِيَةِ.",segs:[{ar:"لَا تَخَفْ",uz:"qo‘rqmang"},{ar:"أَنَا حَرِيصٌ",uz:"men ehtiyotkorman"},{ar:"مِنْ هَذِهِ النَّاحِيَةِ",uz:"bu jihatdan"}],full_uz:"Qo‘rqmang, bu jihatdan ehtiyotkorman.",note:"تَخَافُ fe’li taqiq لَا sidan keyin تَخَفْ bo‘ladi."},
{num:169,time:"00:13:19,860 --> 00:13:23,040",arabic:"أَعْرِفُ يَا أَبَا عَبْدِ الرَّحْمَٰنِ، أَعْرِفُ.",segs:[{ar:"أَعْرِفُ",uz:"bilaman"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَٰنِ",uz:"ey Abu Abdurahmon"},{ar:"أَعْرِفُ",uz:"bilaman"}],full_uz:"Bilaman, Abu Abdurahmon, bilaman.",note:null},
{num:170,time:"00:13:23,040 --> 00:13:28,400",arabic:"وَلَكِنْ فِي نَفْسِي أَمْرٌ لَا أُرِيدُ أَنْ أَكْتُمَهُ عَنْكَ.",segs:[{ar:"وَلَكِنْ فِي نَفْسِي أَمْرٌ",uz:"lekin ko‘nglimda bir gap bor"},{ar:"لَا أُرِيدُ",uz:"istamayman"},{ar:"أَنْ أَكْتُمَهُ عَنْكَ",uz:"uni sizdan yashirishni"}],full_uz:"Lekin ko‘nglimda sizdan yashirishni istamaydigan bir gap bor.",note:"كَتَمَ عَنْهُ — «undan yashirdi, aytmay saqladi»."},
{num:171,time:"00:13:29,000 --> 00:13:30,300",arabic:"قُلْ، فَدَتْكَ نَفْسِي.",segs:[{ar:"قُلْ",uz:"ayting"},{ar:"فَدَتْكَ نَفْسِي",uz:"jonim sizga fido bo‘lsin"}],full_uz:"Ayting, jonim sizga fido bo‘lsin.",note:"فَدَتْكَ نَفْسِي — mehr, sadoqat va hurmatni kuchli ifodalovchi ibora."},
{num:172,time:"00:13:30,299 --> 00:13:45,500",arabic:"اِسْمَعْ يَا أَبَا لَيْثٍ.",segs:[{ar:"اِسْمَعْ",uz:"eshiting"},{ar:"يَا أَبَا لَيْثٍ",uz:"ey Abu Lays"}],full_uz:"Eshiting, Abu Lays.",note:null},
{num:173,time:"00:13:45,500 --> 00:13:49,359",arabic:"أَنْتَ صَدِيقِي وَتَعْرِفُ مَكَانَتَكَ فِي قَلْبِي.",segs:[{ar:"أَنْتَ صَدِيقِي",uz:"siz do‘stimsiz"},{ar:"وَتَعْرِفُ مَكَانَتَكَ",uz:"va o‘rningizni bilasiz"},{ar:"فِي قَلْبِي",uz:"qalbimdagi"}],full_uz:"Siz do‘stimsiz va qalbimdagi o‘rningizni bilasiz.",note:"مَكَانَةٌ — mavqe, qadr, bir kishining nazaridagi o‘rin."},
{num:174,time:"00:13:49,359 --> 00:13:53,579",arabic:"وَأَعِدُكَ بِأَنَّنِي سَأُكَلِّمُ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"وَأَعِدُكَ بِأَنَّنِي",uz:"sizga va’da beramanki, men"},{ar:"سَأُكَلِّمُ الْوَزِيرَ",uz:"vazir bilan gaplashaman"},{ar:"ابْنَ أَبِي دُؤَادٍ",uz:"Ibn Abu Duod"}],full_uz:"Vazir Ibn Abu Duod bilan gaplashishga sizga va’da beraman.",note:"وَعَدَ — يَعِدُ — «va’da berdi, beradi». أَعِدُكَ — «sizga va’da beraman»."},
{num:175,time:"00:13:53,579 --> 00:13:55,120",arabic:"كَيْ يُعِيدَكَ إِلَى عَمَلِكَ.",segs:[{ar:"كَيْ يُعِيدَكَ",uz:"sizni qaytarishi uchun"},{ar:"إِلَى عَمَلِكَ",uz:"ishingizga"}],full_uz:"Sizni ishingizga qaytarishi uchun.",note:"كَيْ maqsadni bildiradi va undan keyingi muzori’ fe’lni nasb qiladi."},
{num:176,time:"00:13:55,120 --> 00:14:02,039",arabic:"جِدْ لِنَفْسِكَ عِنْدَ ابْنِ أَبِي دُؤَادٍ عَمَلًا أَوَّلًا قَبْلَ أَنْ تَتَحَنَّنَ عَلَيَّ.",segs:[{ar:"جِدْ لِنَفْسِكَ",uz:"o‘zingizga toping"},{ar:"عِنْدَ ابْنِ أَبِي دُؤَادٍ",uz:"Ibn Abu Duodning huzurida"},{ar:"عَمَلًا أَوَّلًا",uz:"avval biror ish"},{ar:"قَبْلَ أَنْ تَتَحَنَّنَ عَلَيَّ",uz:"menga rahm-shafqat ko‘rsatishdan oldin"}],full_uz:"Menga rahm-shafqat ko‘rsatishdan oldin, avval Ibn Abu Duodning huzurida o‘zingizga biror ish toping.",note:"جِدْ — وَجَدَ fe’lining buyruq shakli: «toping». تَحَنَّنَ عَلَى — «...ga mehr, rahm-shafqat ko‘rsatdi»."},
{num:177,time:"00:14:02,039 --> 00:14:06,220",arabic:"مَا أَسْمَجَكَ أَيُّهَا الشَّيْخُ!",segs:[{ar:"مَا أَسْمَجَكَ",uz:"naqadar qo‘polsiz"},{ar:"أَيُّهَا الشَّيْخُ",uz:"ey shayx"}],full_uz:"Naqadar qo‘polsiz, ey shayx!",note:"مَا أَفْعَلَ — taajjub shakli. سَمَاجَةٌ — gap yoki muomaladagi yoqimsizlik, qo‘pollik."},
{num:178,time:"00:14:06,220 --> 00:14:13,820",arabic:"أَلَا فَلْتَعْلَمْ أَنَّ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ أَلْحَقَنِي بِعَمَلٍ سَأَكُونُ خِلَالَ أَيَّامٍ عَلَى رَأْسِهِ.",segs:[{ar:"أَلَا فَلْتَعْلَمْ",uz:"bilib qo‘ying"},{ar:"أَنَّ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ",uz:"vazir Ibn Abu Duod"},{ar:"أَلْحَقَنِي بِعَمَلٍ",uz:"meni bir ishga tayinladi"},{ar:"سَأَكُونُ خِلَالَ أَيَّامٍ",uz:"bir necha kun ichida bo‘laman"},{ar:"عَلَى رَأْسِهِ",uz:"o‘sha ishning boshida"}],full_uz:"Bilib qo‘ying, vazir Ibn Abu Duod meni bir ishga tayinladi. Bir necha kun ichida o‘sha ishga kirishaman.",note:"أَلْحَقَهُ بِعَمَلٍ — «uni ishga joylashtirdi». عَلَى رَأْسِ الْعَمَلِ — ishni bajarib turgan holatda."},
{num:179,time:"00:14:13,820 --> 00:14:15,659",arabic:"عَلَى رَأْسِ أَبِي دُؤَادٍ؟",segs:null,full_uz:"Abu Duodning boshidami?",note:"Oldingi عَلَى رَأْسِهِ («ishning boshida») iborasi ataylab kishining boshi ma’nosida talqin qilinib, hazil yaratilgan."},
{num:180,time:"00:14:15,659 --> 00:14:19,600",arabic:"وَمَا هُوَ هَذَا الْعَمَلُ؟",segs:null,full_uz:"Bu qanday ish ekan?",note:null},
{num:181,time:"00:14:19,600 --> 00:14:21,820",arabic:"أَسْنَدَ إِلَيَّ دِيوَانَ الْحِسْبَةِ.",segs:[{ar:"أَسْنَدَ إِلَيَّ",uz:"menga topshirdi"},{ar:"دِيوَانَ الْحِسْبَةِ",uz:"hisba devonini"}],full_uz:"Menga hisba devonini topshirdi.",note:"أَسْنَدَ إِلَيْهِ — «unga vazifani topshirdi». دِيوَانُ الْحِسْبَةِ — bozor va jamoat tartibini nazorat qilish bilan shug‘ullanuvchi idora."},
{num:182,time:"00:14:21,820 --> 00:14:24,820",arabic:"أَحَقٌّ مَا تَقُولُ؟",segs:[{ar:"أَحَقٌّ",uz:"rostmi"},{ar:"مَا تَقُولُ",uz:"aytayotganingiz"}],full_uz:"Aytayotganingiz rostmi?",note:"حَقٌّ bu yerda «rost, haqiqat». مَا تَقُولُ — «siz aytayotgan narsa»."},
{num:183,time:"00:14:25,120 --> 00:14:30,659",arabic:"أَجَلْ، كُنْتُ أُرِيدُ إِخْبَارَكَ وَلَكِنَّكَ أَحْسَنْتَ اسْتِقْبَالِي مُتَذَمِّرًا شَاكِيًا.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"كُنْتُ أُرِيدُ إِخْبَارَكَ",uz:"sizga aytmoqchi edim"},{ar:"وَلَكِنَّكَ أَحْسَنْتَ اسْتِقْبَالِي",uz:"lekin meni juda yaxshi kutib oldingiz"},{ar:"مُتَذَمِّرًا شَاكِيًا",uz:"nolib, shikoyat qilib"}],full_uz:"Ha, sizga aytmoqchi edim, lekin meni nolib, shikoyat qilib juda yaxshi kutib oldingiz.",note:"أَحْسَنْتَ اسْتِقْبَالِي bu yerda kinoya. مُتَذَمِّرًا va شَاكِيًا suhbatdoshning kutib olish paytidagi holatini bildiradi."},
{num:184,time:"00:14:30,659 --> 00:14:34,120",arabic:"مَا رَأْيُكَ؟",segs:null,full_uz:"Fikringiz qanday?",note:null},
{num:185,time:"00:14:34,120 --> 00:14:37,320",arabic:"هَلْ أُكَلِّمُ الْوَزِيرَ بِشَأْنِكَ؟",segs:[{ar:"هَلْ أُكَلِّمُ الْوَزِيرَ",uz:"vazir bilan gaplashaymi"},{ar:"بِشَأْنِكَ",uz:"sizning masalangizda"}],full_uz:"Sizning masalangizda vazir bilan gaplashaymi?",note:"بِشَأْنِكَ — «siz haqingizda, sizga tegishli masalada»."},
{num:186,time:"00:14:37,320 --> 00:14:42,779",arabic:"وَلَكِنِّي لَسْتُ مِنْهُمْ وَلَسْتُ مِمَّنْ يَسْتَسِيغُ أَفْكَارَهُمْ.",segs:[{ar:"وَلَكِنِّي لَسْتُ مِنْهُمْ",uz:"lekin men ulardan emasman"},{ar:"وَلَسْتُ مِمَّنْ يَسْتَسِيغُ",uz:"qabul qila oladiganlardan ham emasman"},{ar:"أَفْكَارَهُمْ",uz:"ularning fikrlarini"}],full_uz:"Lekin men ulardan emasman, ularning fikrlarini qabul qila oladiganlardan ham emasman.",note:"اِسْتَسَاغَ aslida ta’mni yoqimli topishni bildiradi; fikrga nisbatan «ma’qul ko‘rdi, qabul qila oldi»."},
{num:187,time:"00:14:42,779 --> 00:14:48,379",arabic:"لَا يَهُمُّ، لَا أَحَدَ سَيَسْأَلُكَ عَنْ ذَلِكَ إِنْ لَمْ تُجَاهِرْ بِالْعَدَاوَةِ لِإِخْوَتِنَا.",segs:[{ar:"لَا يَهُمُّ",uz:"ahamiyati yo‘q"},{ar:"لَا أَحَدَ سَيَسْأَلُكَ عَنْ ذَلِكَ",uz:"hech kim sizdan bu haqda so‘ramaydi"},{ar:"إِنْ لَمْ تُجَاهِرْ بِالْعَدَاوَةِ",uz:"agar dushmanligingizni oshkora bildirmasangiz"},{ar:"لِإِخْوَتِنَا",uz:"birodarlarimizga"}],full_uz:"Ahamiyati yo‘q. Birodarlarimizga dushmanligingizni oshkora bildirmasangiz, hech kim sizdan bu haqda so‘ramaydi.",note:"جَاهَرَ بِالْعَدَاوَةِ — «dushmanligini oshkora bildirdi»."},
{num:188,time:"00:14:48,379 --> 00:14:52,419",arabic:"وَمَا شَأْنِي بِهِمْ حَتَّى أُجَاهِرَ بِعَدَاوَتِهِمْ؟",segs:[{ar:"وَمَا شَأْنِي بِهِمْ",uz:"ular bilan nima ishim bor"},{ar:"حَتَّى أُجَاهِرَ بِعَدَاوَتِهِمْ",uz:"ularga dushmanligimni oshkora bildiradigan"}],full_uz:"Ularga dushmanligimni oshkora bildiradigan nima ishim bor?",note:"مَا شَأْنِي بِـ — «...bilan nima ishim bor?». حَتَّى dan keyin أُجَاهِرَ mansub kelgan."},
{num:189,time:"00:14:52,419 --> 00:14:54,579",arabic:"جَيِّدٌ.",segs:null,full_uz:"Yaxshi.",note:null},
{num:190,time:"00:14:54,579 --> 00:14:56,879",arabic:"هَذَا هُوَ الْمَطْلُوبُ.",segs:null,full_uz:"Kerak bo‘lgani shu.",note:"الْمَطْلُوبُ — talab qilinayotgan, kerak bo‘lgan narsa."},
{num:191,time:"00:14:56,879 --> 00:15:00,620",arabic:"لَا تُرَدِّدْ مَا يَقُولُهُ الْغَوْغَاءُ عَنَّا.",segs:[{ar:"لَا تُرَدِّدْ",uz:"takrorlamang"},{ar:"مَا يَقُولُهُ الْغَوْغَاءُ عَنَّا",uz:"olomon biz haqimizda aytayotgan gaplarni"}],full_uz:"Olomon biz haqimizda aytayotgan gaplarni takrorlamang.",note:"رَدَّدَ — «takrorladi». الْغَوْغَاءُ — tartibsiz yoki shovqinchi olomonni kamsitib atash."},
{num:192,time:"00:15:00,620 --> 00:15:02,500",arabic:"وَلَنْ يَعْتَرِضَ طَرِيقَكَ أَحَدٌ.",segs:[{ar:"وَلَنْ يَعْتَرِضَ طَرِيقَكَ",uz:"yo‘lingizga to‘g‘anoq bo‘lmaydi"},{ar:"أَحَدٌ",uz:"hech kim"}],full_uz:"Shunda hech kim yo‘lingizga to‘g‘anoq bo‘lmaydi.",note:"اِعْتَرَضَ طَرِيقَهُ — «uning yo‘lini to‘sdi, unga to‘sqinlik qildi»."},
{num:193,time:"00:15:02,500 --> 00:15:08,539",arabic:"وَأَنَا أَعِدُكَ بِأَنْ أُكَلِّمَ الْوَزِيرَ ابْنَ أَبِي دُؤَادٍ فِي شَأْنِكَ.",segs:[{ar:"وَأَنَا أَعِدُكَ",uz:"men sizga va’da beraman"},{ar:"بِأَنْ أُكَلِّمَ الْوَزِيرَ",uz:"vazir bilan gaplashishga"},{ar:"ابْنَ أَبِي دُؤَادٍ",uz:"Ibn Abu Duod"},{ar:"فِي شَأْنِكَ",uz:"sizning masalangizda"}],full_uz:"Sizning masalangizda vazir Ibn Abu Duod bilan gaplashishga va’da beraman.",note:null},
{num:194,time:"00:15:08,539 --> 00:15:15,639",arabic:"مَا هِيَ أَحْوَالُ الرَّعِيَّةِ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"مَا هِيَ أَحْوَالُ الرَّعِيَّةِ",uz:"xalqning ahvoli qanday"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Xalqning ahvoli qanday, Abu Abbos?",note:"الرَّعِيَّةُ — hukmdor boshqaruvidagi xalq. أَحْوَالٌ — حَالٌ ning ko‘pligi."},
{num:195,time:"00:15:15,639 --> 00:15:17,639",arabic:"إِنَّهُمْ عَلَى مَا يُحِبُّ مَوْلَايَ وَيَرْضَى.",segs:[{ar:"إِنَّهُمْ عَلَى مَا",uz:"ular shunday holatdaki"},{ar:"يُحِبُّ مَوْلَايَ وَيَرْضَى",uz:"hukmdorim sevadi va rozi bo‘ladi"}],full_uz:"Ular hukmdorim sevadigan va rozi bo‘ladigan holatda.",note:"عَلَى مَا يُحِبُّ — «u istagan, yoqtirgan tarzda»."},
{num:196,time:"00:15:17,639 --> 00:15:20,419",arabic:"عَلَى أَنَّ هُنَاكَ بَعْضَ التَّذَمُّرِ يَا مَوْلَايَ.",segs:[{ar:"عَلَى أَنَّ هُنَاكَ",uz:"biroq bor"},{ar:"بَعْضَ التَّذَمُّرِ",uz:"biroz norozilik"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Biroq biroz norozilik bor, hukmdorim.",note:"عَلَى أَنَّ bu yerda oldingi fikrga cheklov qo‘shadi: «biroq, shunday bo‘lsa-da». تَذَمُّرٌ — nolish, norozilik."},
{num:197,time:"00:15:20,419 --> 00:15:21,639",arabic:"تَذَمُّرٌ؟",segs:null,full_uz:"Norozilik?",note:null},
{num:198,time:"00:15:22,419 --> 00:15:26,000",arabic:"وَمِمَّاذَا التَّذَمُّرُ؟",segs:null,full_uz:"Nimadan norozilik?",note:"مِمَّاذَا — مِنْ va مَاذَا birikmasi: «nimadan?»."},
{num:199,time:"00:15:26,000 --> 00:15:28,599",arabic:"بَعْضُ الْفُقَهَاءِ وَأَهْلُ الْحَدِيثِ خَاصَّةً...",segs:[{ar:"بَعْضُ الْفُقَهَاءِ",uz:"ayrim faqihlar"},{ar:"وَأَهْلُ الْحَدِيثِ خَاصَّةً",uz:"ayniqsa, hadis ahli"}],full_uz:"Ayrim faqihlar, ayniqsa, hadis ahli...",note:"خَاصَّةً — «ayniqsa, xususan»."},
{num:200,time:"00:15:28,599 --> 00:15:32,539",arabic:"لَمْ يُعْجِبْهُمْ أَنْ نُجَاهِرَ بِمُعْتَقَدَاتِنَا وَآرَائِنَا عَلَى رُؤُوسِ الْأَشْهَادِ.",segs:[{ar:"لَمْ يُعْجِبْهُمْ",uz:"ularga yoqmadi"},{ar:"أَنْ نُجَاهِرَ بِمُعْتَقَدَاتِنَا وَآرَائِنَا",uz:"e’tiqodlarimiz va fikrlarimizni oshkora aytishimiz"},{ar:"عَلَى رُؤُوسِ الْأَشْهَادِ",uz:"barchaning ko‘z o‘ngida"}],full_uz:"E’tiqodlarimiz va fikrlarimizni barchaning ko‘z o‘ngida oshkora aytishimiz ularga yoqmadi.",note:"عَلَى رُؤُوسِ الْأَشْهَادِ — «hammaning oldida, oshkora» ma’nosidagi ibora."},
{num:201,time:"00:15:32,539 --> 00:15:35,599",arabic:"أَيُّ عُقُولٍ تِلْكَ؟",segs:null,full_uz:"Bu qanday aqllar o‘zi?",note:"أَيُّ so‘roq so‘zi bu yerda qoralash va ajablanishni bildiradi."},
{num:202,time:"00:15:37,299 --> 00:15:40,659",arabic:"أَلَا يَجْدُرُ بِهِمْ أَنْ يَحْمَدُوا اللَّهَ عَلَى أَنَّ أَمِيرَ الْمُؤْمِنِينَ...",segs:[{ar:"أَلَا يَجْدُرُ بِهِمْ",uz:"ularga lozim emasmi"},{ar:"أَنْ يَحْمَدُوا اللَّهَ",uz:"Allohga hamd aytish"},{ar:"عَلَى أَنَّ أَمِيرَ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri ...gani uchun"}],full_uz:"Mo‘minlar amiri ...gani uchun Allohga hamd aytishlari lozim emasmi?",note:"يَجْدُرُ بِهِمْ أَنْ — «ular ...ishlari lozim, ularga ...ish munosib»."},
{num:203,time:"00:15:40,659 --> 00:15:43,599",arabic:"سَمَحَ لَهُمْ بِالْمُجَاهَرَةِ بِمُعْتَقَدَاتِهِمُ الْفَاسِدَةِ؟",segs:[{ar:"سَمَحَ لَهُمْ",uz:"ularga ruxsat bergani"},{ar:"بِالْمُجَاهَرَةِ",uz:"oshkora bildirishga"},{ar:"بِمُعْتَقَدَاتِهِمُ الْفَاسِدَةِ",uz:"buzuq e’tiqodlarini"}],full_uz:"Ularga buzuq e’tiqodlarini oshkora bildirishga ruxsat bergani uchun?",note:"سَمَحَ لَهُ بِـ — «unga ...ga ruxsat berdi». مُجَاهَرَةٌ — oshkora aytish yoki ko‘rsatish."},
{num:204,time:"00:15:44,159 --> 00:15:46,599",arabic:"أَيُلَامُ صَاحِبُ الْحَقِّ عَلَى إِظْهَارِهِ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"أَيُلَامُ صَاحِبُ الْحَقِّ",uz:"haq sohibi malomat qilinadimi"},{ar:"عَلَى إِظْهَارِهِ",uz:"uni oshkor qilgani uchun"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Haq sohibi uni oshkor qilgani uchun malomat qilinadimi, Abu Abbos?",note:"لَامَ — «malomat qildi»; يُلَامُ — «malomat qilinadi». Boshidagi أَ so‘roq hamzasidir."},
{num:205,time:"00:15:47,259 --> 00:15:49,599",arabic:"وَمِمَّنْ؟ مِمَّنْ هُمْ أَقْرَبُ إِلَى الضَّلَالَةِ؟",segs:[{ar:"وَمِمَّنْ",uz:"yana kim tomonidan"},{ar:"مِمَّنْ هُمْ أَقْرَبُ إِلَى الضَّلَالَةِ",uz:"adashishga yaqinroq bo‘lganlar tomonidanmi"}],full_uz:"Yana kim tomonidan? Adashishga yaqinroq bo‘lganlar tomonidanmi?",note:"Birinchi مِمَّنْ so‘roq: «kimdan?»; ikkinchisi nisbiy ma’noda: «...bo‘lgan kishilardan»."},
{num:206,time:"00:15:49,600 --> 00:15:53,060",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"hech qanday qudrat ham, kuch ham yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilangina bor"}],full_uz:"Qudrat va kuch faqat Allohning yordami bilangina bo‘ladi.",note:null},
{num:207,time:"00:15:53,060 --> 00:15:58,540",arabic:"قُلْ لِي، مَاذَا عَنْ أَصْحَابِكَ الْمُعْتَزِلَةِ؟",segs:[{ar:"قُلْ لِي",uz:"menga ayting"},{ar:"مَاذَا عَنْ أَصْحَابِكَ الْمُعْتَزِلَةِ",uz:"mu’taziliy safdoshlaringiz-chi"}],full_uz:"Menga ayting, mu’taziliy safdoshlaringiz-chi?",note:"مَاذَا عَنْ — suhbatni boshqa kishi yoki mavzuga buradi: «...haqida-chi?»."},
{num:208,time:"00:15:58,540 --> 00:16:02,680",arabic:"إِنَّهُمْ يَرْفُلُونَ فِي نِعْمَةِ أَمِيرِ الْمُؤْمِنِينَ وَيَنْعَمُونَ بِرَاحَةِ الْبَالِ.",segs:[{ar:"إِنَّهُمْ يَرْفُلُونَ",uz:"ular farovon yashamoqdalar"},{ar:"فِي نِعْمَةِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining ne’mati ichida"},{ar:"وَيَنْعَمُونَ بِرَاحَةِ الْبَالِ",uz:"va ko‘ngil xotirjamligidan bahramandlar"}],full_uz:"Ular mo‘minlar amirining ne’mati ichida farovon yashab, ko‘ngil xotirjamligidan bahramand bo‘lmoqdalar.",note:"رَفَلَ فِي النِّعْمَةِ — «ne’mat va farovonlik ichida yashadi». رَاحَةُ الْبَالِ — ko‘ngil xotirjamligi."},
{num:209,time:"00:16:02,680 --> 00:16:07,200",arabic:"وَلَا تَجِدُهُمْ يَا مَوْلَايَ إِلَّا سَعْيًا فِي دَعْوَتِهِمْ...",segs:[{ar:"وَلَا تَجِدُهُمْ",uz:"ularni topmaysiz"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"},{ar:"إِلَّا سَعْيًا فِي دَعْوَتِهِمْ",uz:"faqat da’vatlari yo‘lida intilayotgan holda"}],full_uz:"Ularni faqat da’vatlari yo‘lida intilayotgan holda ko‘rasiz, hukmdorim...",note:"سَعْيًا masdar bo‘lib, bu yerda faol intilish holatini ifodalaydi. لَا ... إِلَّا — «faqat ...»."},
{num:210,time:"00:16:07,200 --> 00:16:09,879",arabic:"وَدَأْبًا فِي نَشْرِ عَقِيدَتِهِمْ وَمَذْهَبِهِمْ.",segs:[{ar:"وَدَأْبًا",uz:"va tinimsiz mehnatda"},{ar:"فِي نَشْرِ عَقِيدَتِهِمْ وَمَذْهَبِهِمْ",uz:"aqida va mazhablarini yoyishda"}],full_uz:"Va aqida hamda mazhablarini yoyishda tinimsiz mehnat qilayotgan holda.",note:"دَأْبٌ — bir ishni uzluksiz va qunt bilan bajarish."},
{num:211,time:"00:16:09,879 --> 00:16:12,620",arabic:"لَعَلَّهُمْ يَتَذَمَّرُونَ أَيْضًا.",segs:[{ar:"لَعَلَّهُمْ يَتَذَمَّرُونَ",uz:"balki ular ham noliyotgandir"},{ar:"أَيْضًا",uz:"ham"}],full_uz:"Balki ular ham noliyotgandir.",note:"لَعَلَّ bu yerda ehtimol yoki taxminni bildiradi."},
{num:212,time:"00:16:12,620 --> 00:16:13,920",arabic:"قَوْلُكَ حَقٌّ يَا مَوْلَايَ.",segs:[{ar:"قَوْلُكَ حَقٌّ",uz:"gapingiz rost"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Gapingiz rost, hukmdorim.",note:null},
{num:213,time:"00:16:13,920 --> 00:16:16,960",arabic:"إِنَّ رِضَا النَّاسِ غَايَةٌ لَا تُدْرَكُ.",segs:[{ar:"إِنَّ رِضَا النَّاسِ",uz:"odamlarning roziligi"},{ar:"غَايَةٌ لَا تُدْرَكُ",uz:"erishib bo‘lmaydigan maqsaddir"}],full_uz:"Odamlarning roziligi erishib bo‘lmaydigan maqsaddir.",note:"تُدْرَكُ — majhul nisbat: «unga erishiladi». Ibora hammani birdek rozi qilishning imkonsizligini anglatadi."},
{num:214,time:"00:16:16,960 --> 00:16:20,560",arabic:"أَنَا أَعْلَمُ مَا يُرِيدُونَ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"أَنَا أَعْلَمُ مَا يُرِيدُونَ",uz:"ular nima istashini bilaman"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Ular nima istashini bilaman, Abu Abbos.",note:null},
{num:215,time:"00:16:20,560 --> 00:16:26,240",arabic:"يُرِيدُونَ مِنِّي أَنْ أُضَيِّقَ عَلَى الْفُقَهَاءِ وَأَهْلِ الْحَدِيثِ.",segs:[{ar:"يُرِيدُونَ مِنِّي",uz:"mendan istaydilar"},{ar:"أَنْ أُضَيِّقَ",uz:"siquvga olishimni"},{ar:"عَلَى الْفُقَهَاءِ وَأَهْلِ الْحَدِيثِ",uz:"faqihlar va hadis ahlini"}],full_uz:"Mendan faqihlar va hadis ahlini siquvga olishimni istaydilar.",note:"ضَيَّقَ عَلَى فُلَانٍ — «falonchini siquvga oldi, uning imkoniyatlarini chekladi»."},
{num:216,time:"00:16:26,240 --> 00:16:28,780",arabic:"إِنَّ الْأَمِيرَ أَدْرَى بِمَا يَكُونُ.",segs:[{ar:"إِنَّ الْأَمِيرَ أَدْرَى",uz:"amir yaxshiroq biladilar"},{ar:"بِمَا يَكُونُ",uz:"nimalar bo‘layotganini"}],full_uz:"Amir nimalar bo‘layotganini yaxshiroq biladilar.",note:"أَدْرَى بِـ — «...ni yaxshiroq biladigan, ...dan ko‘proq xabardor»."},
{num:217,time:"00:16:28,780 --> 00:16:31,379",arabic:"وَمَا يَجِبُ أَنْ يَكُونَ.",segs:null,full_uz:"Va nimalar bo‘lishi kerakligini ham.",note:"مَا يَجِبُ أَنْ يَكُونَ — «bo‘lishi lozim bo‘lgan narsa»."},
{num:218,time:"00:16:31,379 --> 00:16:37,460",arabic:"مَاذَا تَقْصِدُ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"مَاذَا تَقْصِدُ",uz:"nimani nazarda tutyapsiz"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Nimani nazarda tutyapsiz, Abu Abbos?",note:null},
{num:219,time:"00:16:37,460 --> 00:16:39,240",arabic:"ثَمَّ أُمُورٌ تَجْرِي لَا أَطْمَئِنُّ لَهَا.",segs:[{ar:"ثَمَّ أُمُورٌ تَجْرِي",uz:"ayrim ishlar yuz bermoqda"},{ar:"لَا أَطْمَئِنُّ لَهَا",uz:"ulardan ko‘nglim tinch emas"}],full_uz:"Ayrim ishlar yuz bermoqda, ulardan ko‘nglim tinch emas.",note:"ثَمَّ — «u yerda, bor». ثُمَّ («keyin») bilan adashtirmang. اِطْمَأَنَّ — xotirjam bo‘ldi."},
{num:220,time:"00:16:39,240 --> 00:16:43,860",arabic:"وَلَكِنَّنِي سَأُؤَجِّلُ نَقْلَهَا إِلَى مَوْلَايَ حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهَا.",segs:[{ar:"وَلَكِنَّنِي سَأُؤَجِّلُ نَقْلَهَا",uz:"lekin ularni yetkazishni kechiktiraman"},{ar:"إِلَى مَوْلَايَ",uz:"hukmdorimga"},{ar:"حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهَا",uz:"to‘g‘riligiga qat’iy ishonch hosil qilgunimcha"}],full_uz:"Lekin to‘g‘riligiga qat’iy ishonch hosil qilgunimcha, ularni hukmdorimga yetkazishni kechiktiraman.",note:"أَجَّلَ — «kechiktirdi». تَيَقَّنَ مِنْ — «...ga qat’iy ishonch hosil qildi»."},
{num:221,time:"00:16:43,860 --> 00:16:48,580",arabic:"أَيَجْدُرُ بِمَوْلَاكَ الْقَلَقُ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"أَيَجْدُرُ بِمَوْلَاكَ الْقَلَقُ",uz:"hukmdoringiz tashvishlanishi kerakmi"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Hukmdoringiz tashvishlanishi kerakmi, Abu Abbos?",note:"الْقَلَقُ — tashvish, bezovtalik."},
{num:222,time:"00:16:48,580 --> 00:16:50,080",arabic:"لَا أَقْلَقَ اللَّهُ رَاحَةَ مَوْلَايَ.",segs:[{ar:"لَا أَقْلَقَ اللَّهُ",uz:"Alloh buzmasin"},{ar:"رَاحَةَ مَوْلَايَ",uz:"hukmdorimning xotirjamligini"}],full_uz:"Alloh hukmdorimning xotirjamligini buzmasin.",note:"أَقْلَقَ — «bezovta qildi». لَا va o‘tgan zamon fe’li bu yerda duo ma’nosida."},
{num:223,time:"00:16:50,080 --> 00:16:52,360",arabic:"إِنَّمَا الْقَلَقُ شَأْنُنَا.",segs:[{ar:"إِنَّمَا الْقَلَقُ",uz:"tashvishlanish esa"},{ar:"شَأْنُنَا",uz:"bizning ishimiz"}],full_uz:"Tashvishlanish bizning ishimiz.",note:"إِنَّمَا cheklashni bildiradi: bu vazifa aynan so‘zlovchi tomonning zimmasida ekanini ta’kidlaydi."},
{num:224,time:"00:16:52,360 --> 00:16:54,279",arabic:"وَلَكِنِ اعْذُرْنِي يَا مَوْلَايَ...",segs:[{ar:"وَلَكِنِ اعْذُرْنِي",uz:"lekin meni ma’zur tuting"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Lekin meni ma’zur tuting, hukmdorim...",note:"اِعْذُرْنِي — «uzrimni qabul qiling, meni ma’zur tuting»."},
{num:225,time:"00:16:54,279 --> 00:16:57,600",arabic:"عَنِ الْإِدْلَاءِ بِشَيْءٍ حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهِ.",segs:[{ar:"عَنِ الْإِدْلَاءِ بِشَيْءٍ",uz:"biror ma’lumot aytishdan tiyilishimda"},{ar:"حَتَّى أَتَيَقَّنَ مِنْ صِحَّتِهِ",uz:"uning to‘g‘riligiga ishonch hosil qilgunimcha"}],full_uz:"To‘g‘riligiga ishonch hosil qilgunimcha biror ma’lumot aytmasligimni ma’zur tuting.",note:"أَدْلَى بِخَبَرٍ — «xabarni bildirdi». الْإِدْلَاءُ — ma’lumot yoki ko‘rsatma berish."},
{num:226,time:"00:17:03,180 --> 00:17:04,099",arabic:"اتَّقِ اللَّهَ.",segs:null,full_uz:"Allohdan qo‘rqing.",note:"اتَّقِ — اتَّقَى fe’lining buyruq shakli. Oxirgi illat harfi buyruqda tushgan."},
{num:227,time:"00:17:04,099 --> 00:17:05,380",arabic:"مَا بِكَ؟ أَخْبِرْنِي.",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"أَخْبِرْنِي",uz:"menga ayting"}],full_uz:"Sizga nima bo‘ldi? Menga ayting.",note:null},
{num:228,time:"00:17:05,380 --> 00:17:26,380",arabic:"أَلَمْ أَقُلْ لَكُمْ إِنَّهُ يَبِيعُكُمْ لِلْمَأْمُونِ؟",segs:[{ar:"أَلَمْ أَقُلْ لَكُمْ",uz:"sizlarga aytmaganmidim"},{ar:"إِنَّهُ يَبِيعُكُمْ لِلْمَأْمُونِ",uz:"u sizlarni Ma’munga sotayotganini"}],full_uz:"U sizlarni Ma’munga sotayotganini sizlarga aytmaganmidim?",note:"بَاعَ فُلَانًا bu yerda ko‘chma ma’noda «unga xiyonat qildi, uni boshqalarga tutib berdi». أَقُولُ fe’li لَمْ dan keyin أَقُلْ bo‘ladi."},
{num:229,time:"00:17:26,380 --> 00:17:29,820",arabic:"أَعْرِفُ أَمْثَالَ هَؤُلَاءِ.",segs:[{ar:"أَعْرِفُ",uz:"men bilaman"},{ar:"أَمْثَالَ هَؤُلَاءِ",uz:"bular kabi kishilarni"}],full_uz:"Bular kabi kishilarni bilaman.",note:"أَمْثَالٌ — مِثْلٌ ning ko‘pligi: «o‘xshashlar»."},
{num:230,time:"00:17:29,820 --> 00:17:33,720",arabic:"مِمَّنْ يُخْفُونَ وَرَاءَ الِابْتِسَامَةِ خُبْثًا زُعَافًا.",segs:[{ar:"مِمَّنْ يُخْفُونَ",uz:"yashiradigan kishilardan"},{ar:"وَرَاءَ الِابْتِسَامَةِ",uz:"tabassum ortida"},{ar:"خُبْثًا زُعَافًا",uz:"o‘ldiruvchi zahardek yovuzlikni"}],full_uz:"Tabassum ortida o‘ldiruvchi zahardek yovuzlikni yashiradigan kishilarni.",note:"خُبْثٌ — ichki yovuzlik, qabihlik. زُعَافٌ — tez o‘ldiradigan zahar; bu yerda yovuzlikni kuchaytirib tasvirlaydi."},
{num:231,time:"00:17:33,720 --> 00:17:38,220",arabic:"هَؤُلَاءِ الَّذِينَ يَسْعَوْنَ وَرَاءَ الدُّنْيَا...",segs:[{ar:"هَؤُلَاءِ الَّذِينَ",uz:"bu kishilarki"},{ar:"يَسْعَوْنَ وَرَاءَ الدُّنْيَا",uz:"dunyo ortidan quvadilar"}],full_uz:"Dunyo ortidan quvadigan bu kishilar...",note:"سَعَى وَرَاءَ — «...ortidan quvdi, ...ga erishishga intildi». الدُّنْيَا bu yerda dunyoviy manfaatlar."},
{num:232,time:"00:17:38,220 --> 00:17:41,000",arabic:"لَا يَرْدَعُهُمْ دِينٌ وَلَا ضَمِيرٌ.",segs:[{ar:"لَا يَرْدَعُهُمْ",uz:"ularni tiyib turolmaydi"},{ar:"دِينٌ وَلَا ضَمِيرٌ",uz:"na din, na vijdon"}],full_uz:"Ularni na din, na vijdon tiyib turolmaydi.",note:"رَدَعَ — «tiydi, yomonlikdan qaytardi». ضَمِيرٌ — vijdon."},
{num:233,time:"00:17:41,000 --> 00:17:43,259",arabic:"مَعَكَ حَقٌّ، مَعَكَ حَقٌّ.",segs:null,full_uz:"Haqsiz, haqsiz.",note:"مَعَكَ حَقٌّ — «siz haqsiz». Takror ta’kid uchun kelgan."},
{num:234,time:"00:17:43,259 --> 00:17:45,120",arabic:"لَيْسَ ذَلِكَ مَا يَشْغَلُنَا الْآنَ.",segs:[{ar:"لَيْسَ ذَلِكَ",uz:"bu emas"},{ar:"مَا يَشْغَلُنَا الْآنَ",uz:"hozir bizni tashvishga solayotgan narsa"}],full_uz:"Hozir bizni tashvishga solayotgan narsa bu emas.",note:"شَغَلَهُ bu yerda «uning xayolini band qildi, tashvishga soldi»."},
{num:235,time:"00:17:45,120 --> 00:17:46,740",arabic:"قُلْ لِي، مَا الْعَمَلُ؟",segs:[{ar:"قُلْ لِي",uz:"menga ayting"},{ar:"مَا الْعَمَلُ",uz:"nima qilish kerak"}],full_uz:"Menga ayting, nima qilish kerak?",note:"مَا الْعَمَلُ؟ — yechim yoki keyingi qadamni so‘rash iborasi."},
{num:236,time:"00:17:46,740 --> 00:17:48,819",arabic:"وَتَسْأَلُ: مَا الْعَمَلُ؟",segs:[{ar:"وَتَسْأَلُ",uz:"yana so‘rayapsizmi"},{ar:"مَا الْعَمَلُ",uz:"nima qilish kerak deb"}],full_uz:"Yana «nima qilish kerak?» deb so‘rayapsizmi?",note:null},
{num:237,time:"00:17:48,819 --> 00:17:52,720",arabic:"مَنْ يَقِفْ عَقَبَةً فِي طَرِيقِنَا...",segs:[{ar:"مَنْ يَقِفْ عَقَبَةً",uz:"kim to‘siq bo‘lib tursa"},{ar:"فِي طَرِيقِنَا",uz:"yo‘limizda"}],full_uz:"Kim yo‘limizda to‘siq bo‘lib tursa...",note:"مَنْ shart yuklamasi sifatida يَقِفْ fe’lini jazm qilgan. عَقَبَةٌ — to‘siq, g‘ov."},
{num:238,time:"00:17:52,720 --> 00:17:54,720",arabic:"يُسْتَأْصَلْ.",segs:null,full_uz:"Ildizi bilan yo‘q qilinadi.",note:"اِسْتَأْصَلَ — «ildizi bilan yo‘q qildi». يُسْتَأْصَلْ majhul nisbatda, oldingi shartning javobi bo‘lgani uchun jazm holatida."},
{num:239,time:"00:17:54,720 --> 00:17:57,640",arabic:"تَقْصِدُ؟",segs:null,full_uz:"Nimani nazarda tutyapsiz?",note:"قَصَدَ — «nazarda tutdi, maqsad qildi». Qisqa savolda مَاذَا mazmunan tushuniladi."},
{num:240,time:"00:18:33,720 --> 00:18:46,160",arabic:"لَا بُدَّ أَنَّ اللُّصُوصَ قَتَلُوهُ طَمَعًا فِي مَالِهِ.",segs:[{ar:"لَا بُدَّ أَنَّ اللُّصُوصَ قَتَلُوهُ",uz:"uni o‘g‘rilar o‘ldirgan bo‘lsa kerak"},{ar:"طَمَعًا فِي مَالِهِ",uz:"moliga tama qilib"}],full_uz:"Uni moliga tama qilib o‘g‘rilar o‘ldirgan bo‘lsa kerak.",note:"لَا بُدَّ أَنَّ bu yerda kuchli taxminni bildiradi. طَمَعًا — harakat sababini bildiruvchi masdar."},
{num:241,time:"00:18:46,160 --> 00:18:48,140",arabic:"أُولَئِكَ الْعَيَّارُونَ...",segs:null,full_uz:"O‘sha bezorilar...",note:"الْعَيَّارُونَ bu tarixiy kontekstda bezorilik va talonchilik bilan bog‘liq kishilarni anglatadi."},
{num:242,time:"00:18:48,140 --> 00:18:51,259",arabic:"يُحِبُّونَ الْمَالَ حُبَّ قَارُونَ.",segs:[{ar:"يُحِبُّونَ الْمَالَ",uz:"mol-dunyoni sevadilar"},{ar:"حُبَّ قَارُونَ",uz:"Qorun sevganidek"}],full_uz:"Mol-dunyoni Qorun sevganidek sevadilar.",note:"حُبَّ قَارُونَ maf’ul mutlaq bo‘lib, sevishning qandayligini bildiradi."},
{num:243,time:"00:18:51,259 --> 00:18:53,279",arabic:"وَيَتَعَطَّشُونَ لِلدَّمِ.",segs:null,full_uz:"Va qonga tashnadirlar.",note:"تَعَطَّشَ لِـ — «...ga tashna bo‘ldi». Bu yerda qon to‘kishga kuchli moyillik ko‘chma tarzda ifodalangan."},
{num:244,time:"00:18:53,279 --> 00:18:55,400",arabic:"كَمَا قَابِيلُ.",segs:null,full_uz:"Xuddi Qobil kabi.",note:"Oldingi banddagi qonga tashnalik holati Qobilga o‘xshatilmoqda."},
{num:245,time:"00:18:55,400 --> 00:19:01,400",arabic:"لَا أَظُنُّ ذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"لَا أَظُنُّ ذَلِكَ",uz:"bunday deb o‘ylamayman"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Bunday deb o‘ylamayman, Ibn Abu Duod.",note:null},
{num:246,time:"00:19:01,400 --> 00:19:08,580",arabic:"إِذَنْ مَاذَا يَظُنُّ مَوْلَايَ؟",segs:[{ar:"إِذَنْ",uz:"unday bo‘lsa"},{ar:"مَاذَا يَظُنُّ مَوْلَايَ",uz:"hukmdorim nima deb o‘ylaydilar"}],full_uz:"Unday bo‘lsa, hukmdorim nima deb o‘ylaydilar?",note:null},
{num:247,time:"00:19:08,580 --> 00:19:13,880",arabic:"أَظُنُّ أَنَّهُ أَمْرٌ دُبِّرَ بِلَيْلٍ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"أَظُنُّ أَنَّهُ أَمْرٌ",uz:"menimcha, bu bir ish"},{ar:"دُبِّرَ بِلَيْلٍ",uz:"tunda yashirin rejalashtirilgan"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Menimcha, bu tunda yashirin rejalashtirilgan ish, Ibn Abu Duod.",note:"دُبِّرَ — majhul nisbat: «rejalashtirildi». دُبِّرَ بِلَيْلٍ ko‘pincha yashirin fitna uyushtirilganini anglatadi."},
{num:248,time:"00:19:13,880 --> 00:19:17,680",arabic:"وَأَنَّ مَنْ أَرَادَ قَتْلَ أَبِي الْعَبَّاسِ...",segs:[{ar:"وَأَنَّ مَنْ أَرَادَ",uz:"va istagan kishi"},{ar:"قَتْلَ أَبِي الْعَبَّاسِ",uz:"Abu Abbosni o‘ldirishni"}],full_uz:"Va Abu Abbosni o‘ldirishni istagan kishi...",note:null},
{num:249,time:"00:19:17,680 --> 00:19:21,540",arabic:"إِنَّمَا أَرَادَ أَنْ يَقْبُرَ مَعَهُ سِرًّا كَبِيرًا.",segs:[{ar:"إِنَّمَا أَرَادَ",uz:"faqat istagan"},{ar:"أَنْ يَقْبُرَ مَعَهُ",uz:"u bilan birga ko‘mishni"},{ar:"سِرًّا كَبِيرًا",uz:"katta bir sirni"}],full_uz:"U bilan birga katta bir sirni ko‘mishni istagan, xolos.",note:"قَبَرَ — «ko‘mdi». Sirni ko‘mish uning oshkor bo‘lishiga butunlay yo‘l qo‘ymaslikni bildiradi."},
{num:250,time:"00:19:21,540 --> 00:19:25,040",arabic:"إِنْ شَاءَ مَوْلَايَ...",segs:null,full_uz:"Hukmdorim istasalar...",note:"إِنْ شَاءَ — «agar istasa». Keyingi band shartning javobini beradi."},
{num:251,time:"00:19:25,040 --> 00:19:29,500",arabic:"مَحَّصْنَا الْأَمْرَ حَتَّى نَقِفَ عَلَى حَقِيقَتِهِ.",segs:[{ar:"مَحَّصْنَا الْأَمْرَ",uz:"ishni sinchiklab tekshiramiz"},{ar:"حَتَّى نَقِفَ عَلَى حَقِيقَتِهِ",uz:"uning haqiqatini bilib olgunimizcha"}],full_uz:"Haqiqatini bilib olgunimizcha ishni sinchiklab tekshiramiz.",note:"مَحَّصَ — «sinchiklab tekshirdi». وَقَفَ عَلَى حَقِيقَةِ الْأَمْرِ — «ishning asl mohiyatini bilib oldi»."},
{num:252,time:"00:19:29,500 --> 00:19:34,779",arabic:"فَنَرْدَعَ مُرْتَكِبَهُ بِمَا يَسْتَحِقُّ مِنَ الْعِقَابِ.",segs:[{ar:"فَنَرْدَعَ مُرْتَكِبَهُ",uz:"va uni sodir etgan kishini tiyib qo‘yamiz"},{ar:"بِمَا يَسْتَحِقُّ مِنَ الْعِقَابِ",uz:"loyiq bo‘lgan jazosi bilan"}],full_uz:"Va uni sodir etgan kishini loyiq bo‘lgan jazosi bilan tiyib qo‘yamiz.",note:"مُرْتَكِبٌ — bir ishni, ko‘pincha jinoyatni sodir etgan kishi. اِسْتَحَقَّ — «loyiq bo‘ldi»."},
{num:253,time:"00:19:34,779 --> 00:19:38,940",arabic:"مُرْنِي يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"مُرْنِي",uz:"menga buyuring"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Menga buyuring, ey mo‘minlar amiri.",note:"مُرْ — أَمَرَ fe’lining buyruq shakllaridan biri. ـنِي — «menga»."},
{num:254,time:"00:19:38,940 --> 00:19:45,940",arabic:"لَا يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Yo‘q, Ibn Abu Duod.",note:null},
{num:255,time:"00:19:45,940 --> 00:19:49,200",arabic:"دَعِ الْأُمُورَ تَجْرِي بِقَدَرِهَا.",segs:[{ar:"دَعِ الْأُمُورَ",uz:"ishlarni qo‘ying"},{ar:"تَجْرِي بِقَدَرِهَا",uz:"o‘z taqdiri bilan ketsin"}],full_uz:"Ishlarni qo‘ying, o‘z taqdiri bilan ketsin.",note:"دَعْ — «qo‘ying». Keyingi so‘zga ulab o‘qishda ikki sukun to‘qnashmasligi uchun دَعِ bo‘lgan; bu ayolga qaratilgan دَعِي shakli emas."},
{num:256,time:"00:19:49,200 --> 00:19:52,799",arabic:"رَحِمَ اللَّهُ أَبَا الْعَبَّاسِ.",segs:[{ar:"رَحِمَ اللَّهُ",uz:"Alloh rahmatiga olsin"},{ar:"أَبَا الْعَبَّاسِ",uz:"Abu Abbosni"}],full_uz:"Alloh Abu Abbosni rahmatiga olsin.",note:"أَبَا to‘ldiruvchi bo‘lgani uchun alif bilan mansub kelgan."},
{num:257,time:"00:19:52,799 --> 00:19:55,539",arabic:"رَحَلَ بِسِرِّهِ.",segs:null,full_uz:"Sirini o‘zi bilan olib ketdi.",note:"رَحَلَ — «ketdi»; bu yerda vafot etishga ishora qiladi."},
{num:258,time:"00:20:29,480 --> 00:20:31,480",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"sizlarga salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga salom va Allohning rahmati bo‘lsin.",note:null},
{num:259,time:"00:20:34,480 --> 00:20:36,480",arabic:"مَا وَرَاءَكَ يَا ابْنَ نُوحٍ؟",segs:[{ar:"مَا وَرَاءَكَ",uz:"qanday xabar bilan keldingiz"},{ar:"يَا ابْنَ نُوحٍ",uz:"ey Ibn Nuh"}],full_uz:"Qanday xabar bilan keldingiz, Ibn Nuh?",note:"مَا وَرَاءَكَ؟ so‘zma-so‘z «ortingizda nima bor?»; kelgan kishidan xabar yoki maqsadini so‘rash uchun ishlatiladi."},
{num:260,time:"00:20:38,480 --> 00:20:41,480",arabic:"أَحْسَنَ اللَّهُ عَزَاءَكَ فِي أَبِي عَبْدِ اللَّهِ.",segs:[{ar:"أَحْسَنَ اللَّهُ عَزَاءَكَ",uz:"Alloh sizga go‘zal sabr va tasalli bersin"},{ar:"فِي أَبِي عَبْدِ اللَّهِ",uz:"Abu Abdullohdan ayrilganingizda"}],full_uz:"Abu Abdullohdan ayrilganingizda Alloh sizga go‘zal sabr va tasalli bersin.",note:"أَحْسَنَ اللَّهُ عَزَاءَكَ — ta’ziya bildirish duosi. عَزَاءٌ — musibatga sabr qilish va tasalli."},
{num:261,time:"00:20:46,480 --> 00:20:48,480",arabic:"فَقَدْ وَصَلَتْنَا الْأَخْبَارُ مِنْ مِصْرَ...",segs:[{ar:"فَقَدْ وَصَلَتْنَا الْأَخْبَارُ",uz:"bizga xabar yetib keldi"},{ar:"مِنْ مِصْرَ",uz:"Misrdan"}],full_uz:"Bizga Misrdan xabar yetib keldi...",note:"وَصَلَتْنَا — «bizga yetib keldi». الْأَخْبَارُ g‘ayri oqil ko‘plik bo‘lgani uchun fe’l birlik muannasda."},
{num:262,time:"00:20:48,480 --> 00:20:50,480",arabic:"أَنَّ الْمَنِيَّةَ قَدْ وَافَتْهُ.",segs:[{ar:"أَنَّ الْمَنِيَّةَ",uz:"ajal"},{ar:"قَدْ وَافَتْهُ",uz:"unga yetganligi haqida"}],full_uz:"Unga ajal yetganligi haqida.",note:"وَافَتْهُ الْمَنِيَّةُ — «unga ajal yetdi, u vafot etdi». الْمَنِيَّةُ — ajal, o‘lim."},
{num:263,time:"00:20:54,480 --> 00:20:56,480",arabic:"رَحِمَكَ اللَّهُ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"رَحِمَكَ اللَّهُ",uz:"Alloh sizni rahmatiga olsin"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Alloh sizni rahmatiga olsin, Abu Abdulloh.",note:null},
{num:264,time:"00:20:59,480 --> 00:21:05,720",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ.",segs:[{ar:"إِنَّا لِلَّهِ",uz:"albatta, biz Allohnikimiz"},{ar:"وَإِنَّا إِلَيْهِ رَاجِعُونَ",uz:"va albatta, Unga qaytuvchimiz"}],full_uz:"Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.",note:"رَاجِعُونَ — رَاجِعٌ («qaytuvchi»)ning ko‘pligi. إِلَيْهِ oldinga chiqib, qaytish Allohga ekanini ta’kidlaydi."},
{num:265,time:"00:23:15,599 --> 00:23:18,599",arabic:"نَحْنُ ذَاهِبُونَ إِنْ شَاءَ اللَّهُ، تُرِيدِينَ شَيْئًا؟",segs:[{ar:"نَحْنُ ذَاهِبُونَ",uz:"biz ketyapmiz"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"},{ar:"تُرِيدِينَ شَيْئًا",uz:"biror narsa istaysizmi"}],full_uz:"Alloh xohlasa, biz ketyapmiz. Biror narsa istaysizmi?",note:"تُرِيدِينَ ayol kishiga qaratilgan. Savol bu yerda so‘roq yuklamasisiz, ohang orqali ifodalangan."},
{num:266,time:"00:23:18,599 --> 00:23:21,599",arabic:"أَسَيَخْرُجُ مَعَكَ وَلَدُنَا صَالِحٌ؟",segs:[{ar:"أَسَيَخْرُجُ مَعَكَ",uz:"siz bilan chiqadimi"},{ar:"وَلَدُنَا صَالِحٌ",uz:"o‘g‘limiz Solih"}],full_uz:"O‘g‘limiz Solih ham siz bilan chiqadimi?",note:"أَسَيَخْرُجُ — so‘roq hamzasi أَ, kelasi zamon سَـ va يَخْرُجُ fe’lidan tuzilgan."},
{num:267,time:"00:23:21,599 --> 00:23:24,180",arabic:"سَيَصْحَبُنِي فِي طَرِيقِي إِلَى حَلْقَةِ شَيْخِهِ.",segs:[{ar:"سَيَصْحَبُنِي",uz:"u menga hamroh bo‘ladi"},{ar:"فِي طَرِيقِي",uz:"yo‘limda"},{ar:"إِلَى حَلْقَةِ شَيْخِهِ",uz:"ustozining dars davrasiga borishda"}],full_uz:"Ustozining dars davrasiga borishda yo‘lda menga hamroh bo‘ladi.",note:"صَحِبَ — «hamroh bo‘ldi». حَلْقَةُ الشَّيْخِ — ustoz atrofida tashkil etiladigan dars davrasi."},
{num:268,time:"00:23:24,180 --> 00:23:27,019",arabic:"لَنْ تُفْلِتَ إِذَنْ مِنْ يَدِ أَبِيكَ يَا صَالِحُ.",segs:[{ar:"لَنْ تُفْلِتَ إِذَنْ",uz:"unday bo‘lsa, ajralmaysiz"},{ar:"مِنْ يَدِ أَبِيكَ",uz:"otangizning qo‘lidan"},{ar:"يَا صَالِحُ",uz:"ey Solih"}],full_uz:"Unday bo‘lsa, otangizning qo‘lidan ajralmaysiz, Solih.",note:"أَفْلَتَ مِنْ — «...dan chiqib ketdi, qutulib ketdi». Bu yerda bolaning otasidan uzoqlashmasligi nazarda tutilgan."},
{num:269,time:"00:23:27,019 --> 00:23:28,900",arabic:"وَلَنْ تَذْهَبَ إِلَى أَيِّ مَكَانٍ...",segs:[{ar:"وَلَنْ تَذْهَبَ",uz:"va bormaysiz"},{ar:"إِلَى أَيِّ مَكَانٍ",uz:"hech qaysi joyga"}],full_uz:"Va hech qaysi joyga bormaysiz...",note:"لَنْ kelasi zamondagi inkorni bildiradi; bu nutqda qat’iy ko‘rsatma ma’nosida ishlatilgan."},
{num:270,time:"00:23:28,900 --> 00:23:30,380",arabic:"إِلَّا إِلَى الْحَلْقَةِ.",segs:null,full_uz:"Faqat dars davrasiga.",note:"Oldingi inkor bilan birga لَنْ ... إِلَّا tuzilishi hosil bo‘lgan: «faqat ...ga borasiz»."},
{num:271,time:"00:23:30,380 --> 00:23:32,280",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Sizlarga salom bo‘lsin.",note:null},
{num:272,time:"00:23:32,280 --> 00:23:34,780",arabic:"فِي حِفْظِ اللَّهِ وَرِعَايَتِهِ.",segs:[{ar:"فِي حِفْظِ اللَّهِ",uz:"Allohning himoyasida"},{ar:"وَرِعَايَتِهِ",uz:"va g‘amxo‘rligida"}],full_uz:"Allohning himoyasi va g‘amxo‘rligida bo‘ling.",note:"Xayrlashishda aytiladigan yaxshi tilak. «Bo‘ling» ma’nosi gapda yashirin."},
{num:273,time:"00:23:48,360 --> 00:23:52,240",arabic:"إِنَّ السِّنِينَ قَدْ نَالَتْ مِنْ عَمِّكَ كَمَا تَرَى.",segs:[{ar:"إِنَّ السِّنِينَ",uz:"Darhaqiqat, yillar"},{ar:"قَدْ نَالَتْ مِنْ عَمِّكَ",uz:"amakingizni ancha zaiflashtirdi"},{ar:"كَمَا تَرَى",uz:"ko‘rib turganingizdek"}],full_uz:"Ko‘rib turganingizdek, yillar amakingizni ancha zaiflashtirdi.",note:"نَالَ مِنْ — biror kishiga zarar yetkazmoq, uni zaiflashtirmoq. Bu yerda qarilikning ta’siri nazarda tutilgan."},
{num:274,time:"00:23:52,240 --> 00:23:54,420",arabic:"فِدَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"فِدَاكَ نَفْسِي",uz:"Jonim sizga fido bo‘lsin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Jonim sizga fido bo‘lsin, ey mo‘minlar amiri.",note:"فِدَاكَ نَفْسِي — sadoqat va hurmatni bildiruvchi «jonim sizga fido» iborasi."},
{num:275,time:"00:23:54,420 --> 00:23:56,640",arabic:"إِنَّكَ أَفْتَى مِنْ أَنْ تَقُولَ ذَلِكَ.",segs:[{ar:"إِنَّكَ أَفْتَى",uz:"Siz hali juda navqironsiz"},{ar:"مِنْ أَنْ تَقُولَ ذَلِكَ",uz:"bunday deyish uchun"}],full_uz:"Siz bunday deyish uchun hali juda navqironsiz.",note:"أَفْتَى — yoshroq, navqironroq. أَفْعَلُ مِنْ أَنْ tuzilmasi bu yerda kishining holati aytilgan ishga mos kelmasligini bildiradi."},
{num:276,time:"00:23:56,640 --> 00:24:01,500",arabic:"وَأَعْلَمُ أَنَّكَ لَوْ شَهَرْتَ سَيْفَكَ الْآنَ لَفَرَّ مِنْكَ أَبْنَاءُ الْمَعَارِكِ.",segs:[{ar:"وَأَعْلَمُ أَنَّكَ",uz:"Va bilamanki, siz"},{ar:"لَوْ شَهَرْتَ سَيْفَكَ الْآنَ",uz:"hozir qilichingizni yalang‘ochlasangiz"},{ar:"لَفَرَّ مِنْكَ",uz:"sizdan qochib ketardi"},{ar:"أَبْنَاءُ الْمَعَارِكِ",uz:"janglarda chiniqqan jangchilar"}],full_uz:"Bilamanki, hozir qilichingizni yalang‘ochlasangiz, janglarda chiniqqan jangchilar ham sizdan qochib ketardi.",note:"شَهَرَ سَيْفَهُ — qilichini qinidan chiqarib ko‘tarmoq. أَبْنَاءُ الْمَعَارِكِ so‘zma-so‘z «janglarning farzandlari», ya’ni tajribali jangchilar."},
{num:277,time:"00:24:01,500 --> 00:24:05,900",arabic:"عَمُّكَ الْآنَ شَيْخٌ هَرِمٌ مَرِيضٌ مُتْعَبٌ.",segs:[{ar:"عَمُّكَ الْآنَ",uz:"Amakingiz hozir"},{ar:"شَيْخٌ هَرِمٌ",uz:"juda qarib qolgan chol"},{ar:"مَرِيضٌ مُتْعَبٌ",uz:"kasal va holdan toygan"}],full_uz:"Amakingiz hozir juda qarib qolgan, kasal va holdan toygan chol.",note:"هَرِمٌ — yoshi juda ulg‘ayib, kuchdan qolgan. مُتْعَبٌ — charchagan, holdan toygan; مُتْعِبٌ esa «charchatadigan» degani."},
{num:278,time:"00:24:05,900 --> 00:24:10,780",arabic:"أَلَا قُلْ لِي، مَا الْأَخْبَارُ عَنْ أَبِيكَ؟",segs:[{ar:"أَلَا قُلْ لِي",uz:"Qani, menga ayting"},{ar:"مَا الْأَخْبَارُ عَنْ أَبِيكَ؟",uz:"otangizdan qanday xabarlar bor?"}],full_uz:"Qani, menga ayting, otangizdan qanday xabarlar bor?",note:"أَلَا bu yerda e’tiborni tortish uchun kelgan; inkor ma’nosini bildirmaydi."},
{num:279,time:"00:24:10,780 --> 00:24:13,800",arabic:"بَعَثْتُ إِلَى أَبِي أُخْبِرُهُ عَنْ مَرَضِ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"بَعَثْتُ إِلَى أَبِي",uz:"Otamga xabar yubordim"},{ar:"أُخْبِرُهُ",uz:"unga bildirish uchun"},{ar:"عَنْ مَرَضِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining kasalligi haqida"}],full_uz:"Otamga mo‘minlar amirining kasalligi haqida xabar yubordim.",note:"بَعَثْتُ إِلَى أَبِي jumlasida yuborilgan narsa ochiq aytilmagan; mazmundan xat yoki xabar tushuniladi."},
{num:280,time:"00:24:13,800 --> 00:24:16,500",arabic:"وَكَانَ اللَّهُ فِي عَوْنِهِ إِنْ عَلِمَ ذَلِكَ.",segs:[{ar:"وَكَانَ اللَّهُ فِي عَوْنِهِ",uz:"Alloh unga madadkor bo‘lsin"},{ar:"إِنْ عَلِمَ ذَلِكَ",uz:"buni bilib qolsa"}],full_uz:"Buni bilib qolsa, Alloh unga madadkor bo‘lsin.",note:"كَانَ اللَّهُ فِي عَوْنِهِ shaklan o‘tgan zamonda bo‘lsa ham, bu yerda duo ma’nosida ishlatilgan."},
{num:281,time:"00:24:16,500 --> 00:24:22,680",arabic:"حَفِظَكَ اللَّهُ يَا ابْنَ أَخِي وَأَبْقَى أَبَاكَ.",segs:[{ar:"حَفِظَكَ اللَّهُ",uz:"Alloh sizni asrasin"},{ar:"يَا ابْنَ أَخِي",uz:"ey jiyanim"},{ar:"وَأَبْقَى أَبَاكَ",uz:"va otangizning umrini uzoq qilsin"}],full_uz:"Alloh sizni asrasin, ey jiyanim, otangizning umrini ham uzoq qilsin.",note:"ابْنُ أَخِي — aka yoki ukaning o‘g‘li. أَبْقَى أَبَاكَ bu duoda «otangizni uzoq yashatsin» ma’nosida."},
{num:282,time:"00:24:22,680 --> 00:24:27,080",arabic:"عِشْقُهُ لِلثُّغُورِ حَرَمَهُ مِنْ أَكْثَرِ مَتَاعِ الْحَيَاةِ.",segs:[{ar:"عِشْقُهُ لِلثُّغُورِ",uz:"Uning chegara qal’alariga bo‘lgan muhabbati"},{ar:"حَرَمَهُ",uz:"uni mahrum qildi"},{ar:"مِنْ أَكْثَرِ مَتَاعِ الْحَيَاةِ",uz:"hayot rohatlarining ko‘pidan"}],full_uz:"Uning chegara qal’alariga bo‘lgan muhabbati uni hayot rohatlarining ko‘pidan mahrum qildi.",note:"الثُّغُورُ — bu yerda chegaradagi mudofaa joylari va qal’alar. حَرَمَ فُلَانًا مِنْ شَيْءٍ — biror kishini bir narsadan mahrum qilmoq."},
{num:283,time:"00:24:27,080 --> 00:24:31,680",arabic:"مَوْلَايَ، أَمَا زِلْتَ تُعَانِي مِنْ مَرَضِكَ؟",segs:[{ar:"مَوْلَايَ",uz:"Hazratim"},{ar:"أَمَا زِلْتَ تُعَانِي",uz:"hali ham azob chekyapsizmi"},{ar:"مِنْ مَرَضِكَ؟",uz:"kasalligingizdan?"}],full_uz:"Hazratim, hali ham kasalligingizdan azob chekyapsizmi?",note:"مَا زِلْتَ — «hali ham ... qilyapsiz». Boshidagi أَ so‘roq yuklamasi bo‘lib, davom etayotgan holat haqida savol hosil qiladi."},
{num:284,time:"00:24:33,380 --> 00:24:36,680",arabic:"إِنَّ مَرَضِي يَزْدَادُ يَوْمًا بَعْدَ يَوْمٍ يَا ابْنَ أَخِي.",segs:[{ar:"إِنَّ مَرَضِي يَزْدَادُ",uz:"Kasalligim kuchayib boryapti"},{ar:"يَوْمًا بَعْدَ يَوْمٍ",uz:"kundan kunga"},{ar:"يَا ابْنَ أَخِي",uz:"ey jiyanim"}],full_uz:"Kasalligim kundan kunga kuchayib boryapti, ey jiyanim.",note:"يَوْمًا بَعْدَ يَوْمٍ — kundan kunga, kun sayin."},
{num:285,time:"00:24:36,680 --> 00:24:46,560",arabic:"لَمْ أَسْأَلْ أَحَدًا عَنْهُ إِلَّا وَمَدَحَهُ كَثِيرًا.",segs:[{ar:"لَمْ أَسْأَلْ أَحَدًا عَنْهُ",uz:"U haqda kimdan so‘ramay"},{ar:"إِلَّا وَمَدَحَهُ كَثِيرًا",uz:"uni juda maqtadi"}],full_uz:"U haqda kimdan so‘ramay, uni juda maqtadi.",note:"لَمْ ... إِلَّا tuzilmasi bu yerda istisnosiz holatni bildiradi: so‘ralganlarning hammasi uni maqtagan."},
{num:286,time:"00:24:46,560 --> 00:24:49,799",arabic:"هُوَ رَجُلٌ مَيْسُورُ الْحَالِ وَذُو أَخْلَاقٍ حَمِيدَةٍ.",segs:[{ar:"هُوَ رَجُلٌ مَيْسُورُ الْحَالِ",uz:"U moddiy ahvoli yaxshi odam"},{ar:"وَذُو أَخْلَاقٍ حَمِيدَةٍ",uz:"va yaxshi xulq egasi"}],full_uz:"U moddiy ahvoli yaxshi, yaxshi xulqli odam.",note:"مَيْسُورُ الْحَالِ — moddiy jihatdan ta’minlangan. ذُو — ega, sohib; undan keyingi ot qaratqich kelishigida keladi."},
{num:287,time:"00:24:49,799 --> 00:24:52,299",arabic:"لَمْ يَذْكُرْ أَحَدٌ شَيْئًا يَعِيبُهُ.",segs:[{ar:"لَمْ يَذْكُرْ أَحَدٌ",uz:"Hech kim aytmadi"},{ar:"شَيْئًا يَعِيبُهُ",uz:"uni aybli ko‘rsatadigan biror narsani"}],full_uz:"Hech kim uning biror aybini aytmadi.",note:null},
{num:288,time:"00:24:52,299 --> 00:24:58,720",arabic:"أَمُتَأَكِّدٌ أَنْتَ يَا قَيْسُ؟ أَنْتَ تَعْرِفُ أَنَّ سَعَادَةَ هِيَ ابْنَتِيَ الصُّغْرَى، وَأُرِيدُ أَنْ أَطْمَئِنَّ عَلَيْهَا.",segs:[{ar:"أَمُتَأَكِّدٌ أَنْتَ",uz:"Ishonchingiz komilmi"},{ar:"يَا قَيْسُ؟",uz:"ey Qays?"},{ar:"أَنْتَ تَعْرِفُ",uz:"Siz bilasiz"},{ar:"أَنَّ سَعَادَةَ هِيَ ابْنَتِيَ الصُّغْرَى",uz:"Saodat mening kenja qizim ekanini"},{ar:"وَأُرِيدُ أَنْ أَطْمَئِنَّ عَلَيْهَا",uz:"va uning xotirjamligini bilib, ko‘nglim tinch bo‘lishini istayman"}],full_uz:"Ishonchingiz komilmi, ey Qays? Saodat mening kenja qizim ekanini bilasiz. Uning taqdiridan ko‘nglim xotirjam bo‘lishini istayman.",note:"الصُّغْرَى — أَصْغَرُ ning muannas shakli; farzandlar haqida «kenja» ma’nosida keladi. اِطْمَأَنَّ عَلَى فُلَانٍ — birovning ahvolidan ko‘ngli xotirjam bo‘lmoq."},
{num:289,time:"00:24:58,720 --> 00:25:03,940",arabic:"لَا تَدَعْ خَوْفَكَ يَقِفُ فِي طَرِيقِهَا يَا أَبَا فَوْزٍ، وَاتَّكِلْ عَلَى اللَّهِ.",segs:[{ar:"لَا تَدَعْ خَوْفَكَ",uz:"Qo‘rquvingizga yo‘l qo‘ymang"},{ar:"يَقِفُ فِي طَرِيقِهَا",uz:"uning yo‘liga to‘siq bo‘lishiga"},{ar:"يَا أَبَا فَوْزٍ",uz:"ey Abu Favz"},{ar:"وَاتَّكِلْ عَلَى اللَّهِ",uz:"va Allohga tavakkal qiling"}],full_uz:"Ey Abu Favz, qo‘rquvingiz uning yo‘liga to‘siq bo‘lishiga yo‘l qo‘ymang. Allohga tavakkal qiling.",note:"لَا تَدَعْ — yo‘l qo‘ymang, qo‘yib bermang. وَقَفَ فِي طَرِيقِهِ — uning yo‘liga to‘siq bo‘lmoq."},
{num:290,time:"00:25:03,940 --> 00:25:06,919",arabic:"وَهُوَ كَذَلِكَ، وَنِعْمَ الِاتِّكَالُ.",segs:[{ar:"وَهُوَ كَذَلِكَ",uz:"Shunday bo‘lsin"},{ar:"وَنِعْمَ الِاتِّكَالُ",uz:"bu qanday yaxshi tavakkal"}],full_uz:"Shunday bo‘lsin. Allohga tavakkal qilish qanday yaxshi.",note:"نِعْمَ — maqtovni ifodalovchi fe’l. Uni «ha» ma’nosidagi نَعَمْ bilan adashtirmang."},
{num:291,time:"00:25:06,919 --> 00:25:10,559",arabic:"تَفَضَّلْ.",segs:null,full_uz:"Marhamat.",note:"تَفَضَّلْ — erkak kishiga aytiladigan muloyim taklif. Vaziyatga qarab «marhamat, oling», «kiring» yoki «o‘tiring» degani bo‘ladi."},
{num:292,time:"00:25:10,559 --> 00:25:12,559",arabic:"بَارَكَ اللَّهُ.",segs:null,full_uz:"Alloh baraka bersin.",note:null},
{num:293,time:"00:25:12,559 --> 00:25:17,220",arabic:"الْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ يَا مَوْلَايَ، أَرَاكَ الْيَوْمَ بِصِحَّةٍ جَيِّدَةٍ.",segs:[{ar:"الْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ",uz:"Sog‘-salomatligingiz uchun Allohga hamd bo‘lsin"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"},{ar:"أَرَاكَ الْيَوْمَ",uz:"Bugun sizni ko‘ryapman"},{ar:"بِصِحَّةٍ جَيِّدَةٍ",uz:"sog‘lig‘ingiz yaxshi holda"}],full_uz:"Sog‘-salomatligingiz uchun Allohga hamd bo‘lsin, hazratim. Bugun sog‘lig‘ingiz yaxshi ko‘rinadi.",note:"الْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ — kasallikdan tuzalgan yoki safardan qaytgan kishiga aytiladigan ibora."},
{num:294,time:"00:25:20,220 --> 00:25:24,039",arabic:"الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"عَلَى كُلِّ حَالٍ",uz:"har qanday holatda"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Har qanday holatda Allohga hamd bo‘lsin, ey Ibn Abu Duod.",note:null},
{num:295,time:"00:25:25,900 --> 00:25:30,539",arabic:"لَقَدْ رَأَيْتُ أَنْ أُرْسِلَ إِلَى وَالِيكُمْ فِي بَغْدَادَ.",segs:[{ar:"لَقَدْ رَأَيْتُ",uz:"Men ma’qul deb topdim"},{ar:"أَنْ أُرْسِلَ إِلَى وَالِيكُمْ",uz:"sizning voliyingizga xabar yuborishni"},{ar:"فِي بَغْدَادَ",uz:"Bag‘doddagi"}],full_uz:"Bag‘doddagi voliyingizga xabar yuborishni ma’qul deb topdim.",note:"رَأَيْتُ bu yerda «ko‘rdim» emas, «lozim yoki ma’qul deb topdim» ma’nosida."},
{num:296,time:"00:25:32,519 --> 00:25:34,819",arabic:"أَنْ يَسْأَلَ الْقُضَاةَ هُنَاكَ.",segs:[{ar:"أَنْ يَسْأَلَ الْقُضَاةَ",uz:"Qozilardan so‘rashini"},{ar:"هُنَاكَ",uz:"u yerdagi"}],full_uz:"U yerdagi qozilardan so‘rashini.",note:"الْقُضَاةُ — قَاضٍ «qozi» so‘zining ko‘pligi. Bu parcha oldingi topshiriqning davomidir."},
{num:297,time:"00:25:34,819 --> 00:25:38,160",arabic:"وَمَنْ يَتَصَدَّرُونَ حَلَقَاتِ الْعِلْمِ فِي الْمَسَاجِدِ.",segs:[{ar:"وَمَنْ يَتَصَدَّرُونَ",uz:"Va boshchilik qiladiganlardan"},{ar:"حَلَقَاتِ الْعِلْمِ",uz:"ilm halqalariga"},{ar:"فِي الْمَسَاجِدِ",uz:"masjidlardagi"}],full_uz:"Va masjidlardagi ilm halqalariga boshchilik qiladiganlardan.",note:"تَصَدَّرَ — oldingi o‘rinni egallamoq, boshchilik qilmoq. حَلَقَاتُ الْعِلْمِ — ilm o‘rganish uchun tuzilgan dars davralari."},
{num:298,time:"00:25:38,160 --> 00:25:40,720",arabic:"عَنْ قَوْلِهِمْ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ.",segs:[{ar:"عَنْ قَوْلِهِمْ",uz:"Ularning fikri haqida"},{ar:"فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ",uz:"Qur’onning yaratilganligi masalasidagi"}],full_uz:"Ularning Qur’onning yaratilganligi masalasidagi fikri haqida.",note:"قَوْلٌ bu yerda «so‘z» emas, bir masaladagi fikr yoki qarash ma’nosida."},
{num:299,time:"00:25:40,720 --> 00:25:50,360",arabic:"أَتَظُنُّ الْوَقْتَ مُنَاسِبًا لِذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ؟",segs:[{ar:"أَتَظُنُّ الْوَقْتَ مُنَاسِبًا",uz:"Vaqtni munosib deb o‘ylaysizmi"},{ar:"لِذَلِكَ",uz:"buning uchun"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ؟",uz:"ey Ibn Abu Duod?"}],full_uz:"Ey Ibn Abu Duod, buning uchun vaqtni munosib deb o‘ylaysizmi?",note:"ظَنَّ fe’li bu tuzilmada ikkita to‘ldiruvchini tushum kelishigida oladi: الْوَقْتَ va مُنَاسِبًا."},
{num:300,time:"00:25:50,360 --> 00:25:54,860",arabic:"الْحِفَاظُ عَلَى عَقِيدَةِ الرَّعِيَّةِ مِنْ مَهَامِّ وَلِيِّ الْأَمْرِ يَا مَوْلَايَ.",segs:[{ar:"الْحِفَاظُ عَلَى عَقِيدَةِ الرَّعِيَّةِ",uz:"Raiyatning e’tiqodini saqlash"},{ar:"مِنْ مَهَامِّ وَلِيِّ الْأَمْرِ",uz:"hukmdorning vazifalaridandir"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"}],full_uz:"Raiyatning e’tiqodini saqlash hukmdorning vazifalaridandir, hazratim.",note:"الرَّعِيَّةُ — hukmdor boshqaruvidagi xalq. وَلِيُّ الْأَمْرِ — boshqaruv va hokimiyat egasi."},
{num:301,time:"00:25:54,860 --> 00:25:57,240",arabic:"أَخْشَى أَنْ يُفْسِدَ عَلَى النَّاسِ اعْتِقَادَهُمْ.",segs:[{ar:"أَخْشَى أَنْ يُفْسِدَ",uz:"Buzishidan qo‘rqaman"},{ar:"عَلَى النَّاسِ اعْتِقَادَهُمْ",uz:"odamlarning e’tiqodini"}],full_uz:"Odamlarning e’tiqodini buzishidan qo‘rqaman.",note:"أَفْسَدَ عَلَى فُلَانٍ شَيْئًا — birovning biror narsasini buzmoq. Ishni bajaruvchi keyingi bandda keladi."},
{num:302,time:"00:25:57,240 --> 00:26:03,100",arabic:"بَعْضُ دُعَاةِ الْعِلْمِ مِنْ أَهْلِ الْحَدِيثِ. إِلَامَ نَصْبِرُ عَلَى أَمْرٍ لَا يَرْضَاهُ اللَّهُ يَا مَوْلَايَ؟",segs:[{ar:"بَعْضُ دُعَاةِ الْعِلْمِ",uz:"Ilmga da’vat qiluvchilarning ayrimlari"},{ar:"مِنْ أَهْلِ الْحَدِيثِ",uz:"hadis ahli orasidan"},{ar:"إِلَامَ نَصْبِرُ",uz:"Qachongacha sabr qilamiz"},{ar:"عَلَى أَمْرٍ لَا يَرْضَاهُ اللَّهُ",uz:"Alloh rozi bo‘lmaydigan ishga"},{ar:"يَا مَوْلَايَ؟",uz:"ey hazratim?"}],full_uz:"Hadis ahli orasidagi ilmga da’vat qiluvchilarning ayrimlari. Hazratim, Alloh rozi bo‘lmaydigan ishga qachongacha sabr qilamiz?",note:"إِلَامَ — إِلَى va so‘roq bildiruvchi مَا birikmasi; «nimagacha?» yoki vaziyatga qarab «qachongacha?» degani. Old qo‘shimchadan keyin so‘roq مَا ning alifi tushadi."},
{num:303,time:"00:26:03,100 --> 00:26:08,980",arabic:"لَقَدْ أَمْهَلْنَا هَؤُلَاءِ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ دَهْرًا أَنْ يَرْجِعُوا عَنْ غَيِّهِمْ.",segs:[{ar:"لَقَدْ أَمْهَلْنَا",uz:"Biz muhlat berdik"},{ar:"هَؤُلَاءِ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ",uz:"bu faqihlar va hadis ahliga"},{ar:"دَهْرًا",uz:"uzoq vaqt"},{ar:"أَنْ يَرْجِعُوا عَنْ غَيِّهِمْ",uz:"adashgan yo‘llaridan qaytishlari uchun"}],full_uz:"Biz bu faqihlar va hadis ahliga adashgan yo‘llaridan qaytishlari uchun uzoq vaqt muhlat berdik.",note:"أَمْهَلَ — muhlat bermoq. رَجَعَ عَنْ — bir qarash yoki ishdan qaytmoq, undan voz kechmoq."},
{num:304,time:"00:26:08,980 --> 00:26:10,240",arabic:"فَمَا رَجَعُوا.",segs:null,full_uz:"Ammo ular qaytmadilar.",note:"مَا bu yerda inkor yuklamasi bo‘lib, o‘tgan zamondagi harakatni inkor qiladi."},
{num:305,time:"00:26:10,720 --> 00:26:14,720",arabic:"فَمَنْ شَاءَ أَنْ يَبْقَى عَلَى ضَلَالَتِهِ فَلْيَبْقَ.",segs:[{ar:"فَمَنْ شَاءَ",uz:"Kim istasa"},{ar:"أَنْ يَبْقَى عَلَى ضَلَالَتِهِ",uz:"o‘z zalolatida qolishni"},{ar:"فَلْيَبْقَ",uz:"qolaversin"}],full_uz:"Kim o‘z zalolatida qolishni istasa, qolaversin.",note:"فَلْيَبْقَ dagi لْ buyruq ma’nosini beradi. يَبْقَى fe’li shu yuklama sababli oxiridagi kuchsiz harfini yo‘qotgan."},
{num:306,time:"00:26:14,720 --> 00:26:19,940",arabic:"نَحْنُ يَا مَوْلَايَ لَا نُكْرِهُ النَّاسَ عَلَى أَنْ يُصْبِحُوا مُؤْمِنِينَ.",segs:[{ar:"نَحْنُ يَا مَوْلَايَ",uz:"Biz, hazratim"},{ar:"لَا نُكْرِهُ النَّاسَ",uz:"odamlarni majburlamaymiz"},{ar:"عَلَى أَنْ يُصْبِحُوا مُؤْمِنِينَ",uz:"mo‘min bo‘lishga"}],full_uz:"Hazratim, biz odamlarni mo‘min bo‘lishga majburlamaymiz.",note:"أَكْرَهَ فُلَانًا عَلَى شَيْءٍ — birovni bir narsaga majburlamoq. يُصْبِحُوا bu yerda «ertalab turish» emas, «bo‘lish» ma’nosida."},
{num:307,time:"00:26:19,940 --> 00:26:24,759",arabic:"لَكِنَّنَا لَنْ نَتَحَمَّلَ جَرِيرَةَ ذَلِكَ.",segs:[{ar:"لَكِنَّنَا لَنْ نَتَحَمَّلَ",uz:"Ammo biz zimmamizga olmaymiz"},{ar:"جَرِيرَةَ ذَلِكَ",uz:"buning gunohi va javobgarligini"}],full_uz:"Ammo buning gunohi va javobgarligini zimmamizga olmaymiz.",note:"جَرِيرَةٌ — gunoh, qilmish yoki uning uchun javobgarlik. لَنْ dan keyingi hozirgi-kelasi zamon fe’li nasb holatida keladi."},
{num:308,time:"00:26:24,759 --> 00:26:31,140",arabic:"إِلَى مَتَى نَتْرُكُهُمْ يُضِلُّونَ النَّاسَ بِأَقَاوِيلِهِمُ الْبَاطِلَةِ؟",segs:[{ar:"إِلَى مَتَى نَتْرُكُهُمْ",uz:"Qachongacha ularga yo‘l qo‘yamiz"},{ar:"يُضِلُّونَ النَّاسَ",uz:"odamlarni adashtirishlariga"},{ar:"بِأَقَاوِيلِهِمُ الْبَاطِلَةِ؟",uz:"botil gaplari bilan?"}],full_uz:"Ularning botil gaplari bilan odamlarni adashtirishlariga qachongacha yo‘l qo‘yamiz?",note:"ضَلَّ — o‘zi adashmoq; أَضَلَّ — boshqani adashtirmoq. يُضِلُّونَ ikkinchi fe’ldan yasalgan."},
{num:309,time:"00:26:31,140 --> 00:26:38,180",arabic:"إِنْ كَانَ الْأَمْرُ كَذَلِكَ فَلَا بَأْسَ.",segs:[{ar:"إِنْ كَانَ الْأَمْرُ كَذَلِكَ",uz:"Agar ish shunday bo‘lsa"},{ar:"فَلَا بَأْسَ",uz:"zarari yo‘q"}],full_uz:"Agar ish shunday bo‘lsa, zarari yo‘q.",note:"لَا بَأْسَ — «zarari yo‘q», «mayli»; vaziyatga qarab rozilik yoki taskin bildiradi."},
{num:310,time:"00:26:38,180 --> 00:26:47,759",arabic:"أَطَالَ اللَّهُ فِي عُمْرِكَ يَا مَوْلَايَ، نَصِيرًا لِلْحَقِّ مُدَافِعًا عَنْ أَتْبَاعِهِ.",segs:[{ar:"أَطَالَ اللَّهُ فِي عُمْرِكَ",uz:"Alloh umringizni uzoq qilsin"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"},{ar:"نَصِيرًا لِلْحَقِّ",uz:"haqning yordamchisi bo‘lib"},{ar:"مُدَافِعًا عَنْ أَتْبَاعِهِ",uz:"uning izdoshlarini himoya qilib"}],full_uz:"Hazratim, haqning yordamchisi va uning izdoshlarini himoya qiluvchi bo‘lib, Alloh umringizni uzoq qilsin.",note:"نَصِيرًا va مُدَافِعًا hol vazifasida kelib, umr qanday holatda davom etishi tilanayotganini bildiradi."},
{num:311,time:"00:26:47,759 --> 00:26:53,580",arabic:"آنَ الْأَوَانُ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا وَكَلِمَةُ الْبَاطِلِ هِيَ السُّفْلَى.",segs:[{ar:"آنَ الْأَوَانُ",uz:"Vaqti keldi"},{ar:"لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا",uz:"Allohning kalimasi eng yuksak bo‘lishi uchun"},{ar:"وَكَلِمَةُ الْبَاطِلِ هِيَ السُّفْلَى",uz:"botilning kalimasi esa eng past bo‘lishi uchun"}],full_uz:"Allohning kalimasi eng yuksak, botilning kalimasi esa eng past bo‘ladigan vaqt keldi.",note:"آنَ الْأَوَانُ — vaqti yetdi. الْعُلْيَا va السُّفْلَى — أَعْلَى va أَسْفَلُ ning muannas shakllari."},
{num:312,time:"00:26:53,580 --> 00:27:02,680",arabic:"غَدًا إِنْ شَاءَ اللَّهُ سَأَبْعَثُ لِوَالِينَا فِي بَغْدَادَ لِيَكُونَ الْقَوْلُ فِي خَلْقِ الْقُرْآنِ هُوَ مِيزَانَ الْحَقِّ.",segs:[{ar:"غَدًا إِنْ شَاءَ اللَّهُ",uz:"Ertaga, Alloh xohlasa"},{ar:"سَأَبْعَثُ لِوَالِينَا",uz:"voliyimizga xabar yuboraman"},{ar:"فِي بَغْدَادَ",uz:"Bag‘doddagi"},{ar:"لِيَكُونَ الْقَوْلُ فِي خَلْقِ الْقُرْآنِ",uz:"Qur’onning yaratilganligi haqidagi qarash bo‘lishi uchun"},{ar:"هُوَ مِيزَانَ الْحَقِّ",uz:"haqni o‘lchash mezoni"}],full_uz:"Ertaga, Alloh xohlasa, Qur’onning yaratilganligi haqidagi qarash haqni o‘lchash mezoni bo‘lishi uchun Bag‘doddagi voliyimizga xabar yuboraman.",note:"مِيزَانٌ aslida «tarozi»; bu yerda ko‘chma ma’noda «mezon». لِيَكُونَ boshidagi لِ maqsadni bildiradi."},
{num:313,time:"00:27:02,680 --> 00:27:07,380",arabic:"وَمَنْ خَالَفَ ذَلِكَ عَاقَبْنَاهُ بِحُكْمِهِ.",segs:[{ar:"وَمَنْ خَالَفَ ذَلِكَ",uz:"Kim bunga qarshi chiqsa"},{ar:"عَاقَبْنَاهُ بِحُكْمِهِ",uz:"uni tegishli hukm bilan jazolaymiz"}],full_uz:"Kim bunga qarshi chiqsa, uni tegishli hukm bilan jazolaymiz.",note:"مَنْ shart ma’nosida kelgan. Shart gapdagi o‘tgan zamon fe’llari bu yerda kelajakda yuz berishi mumkin bo‘lgan ishni bildiradi."},
{num:314,time:"00:27:07,380 --> 00:27:23,840",arabic:"أَنَا عَائِدٌ إِلَى الْبَيْتِ.",segs:null,full_uz:"Men uyga qaytyapman.",note:"عَائِدٌ — عَادَ «qaytmoq» fe’lining sifatdoshi; bu jumlada yaqin vaqtdagi harakatni bildiradi."},
{num:315,time:"00:27:23,840 --> 00:27:27,400",arabic:"تَفَقَّدُوا الْمَسَاجِينَ.",segs:null,full_uz:"Mahbuslarni tekshirib chiqinglar.",note:"تَفَقَّدَ — tekshirib chiqmoq, holidan xabar olmoq. تَفَقَّدُوا — ko‘plikdagi buyruq."},
{num:316,time:"00:27:27,400 --> 00:27:29,520",arabic:"وَاحْرِصُوا عَلَى حُسْنِ سَيْرِ الْأُمُورِ.",segs:[{ar:"وَاحْرِصُوا",uz:"Va e’tiborli bo‘linglar"},{ar:"عَلَى حُسْنِ سَيْرِ الْأُمُورِ",uz:"ishlarning yaxshi borishiga"}],full_uz:"Ishlarning yaxshi borishiga e’tiborli bo‘linglar.",note:"حَرَصَ عَلَى — biror ishga jiddiy e’tibor bermoq, uni ta’minlashga intilmoq. سَيْرُ الْأُمُورِ — ishlarning borishi."},
{num:317,time:"00:27:29,520 --> 00:27:31,280",arabic:"وَخُذُوا حِذْرَكُمْ.",segs:null,full_uz:"Va ehtiyot bo‘linglar.",note:"خُذُوا حِذْرَكُمْ — hushyor va ehtiyot bo‘lishga chaqiruvchi turg‘un ibora."},
{num:318,time:"00:27:31,280 --> 00:27:32,880",arabic:"أَمْرُكَ سَيِّدِي.",segs:null,full_uz:"Buyrug‘ingiz bosh ustiga, janobim.",note:"أَمْرُكَ — buyruqqa itoatni bildiradigan qisqa javob."},
{num:319,time:"00:27:39,380 --> 00:27:42,220",arabic:"أَجَلْ، عَوْفُ بْنُ مَيْسَمٍ الدِّمَشْقِيُّ.",segs:[{ar:"أَجَلْ",uz:"Ha"},{ar:"عَوْفُ بْنُ مَيْسَمٍ الدِّمَشْقِيُّ",uz:"damashqlik Avf ibn Maysam"}],full_uz:"Ha, damashqlik Avf ibn Maysam.",note:"الدِّمَشْقِيُّ — Damashqqa mansub, damashqlik. Joy nomiga qo‘shilgan يّ nisbatni bildiradi."},
{num:320,time:"00:27:42,220 --> 00:27:45,320",arabic:"رَجُلٌ ذُو مَكَانَةٍ وَحَظْوَةٍ بَيْنَ النَّاسِ.",segs:[{ar:"رَجُلٌ ذُو مَكَانَةٍ وَحَظْوَةٍ",uz:"Obro‘ va hurmatga ega odam"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"}],full_uz:"Odamlar orasida obro‘ va hurmatga ega odam.",note:"ذُو — ega, sohib. حَظْوَةٌ — boshqalar huzuridagi hurmat, e’tibor va yaqinlik."},
{num:321,time:"00:27:45,320 --> 00:27:47,440",arabic:"وَهُوَ مِنَ التُّجَّارِ الْمَيْسُورِينَ.",segs:[{ar:"وَهُوَ مِنَ التُّجَّارِ",uz:"U savdogarlardan"},{ar:"الْمَيْسُورِينَ",uz:"moddiy ahvoli yaxshi bo‘lgan"}],full_uz:"U moddiy ahvoli yaxshi savdogarlardan.",note:"التُّجَّارُ — تَاجِرٌ «savdogar» so‘zining ko‘pligi."},
{num:322,time:"00:27:47,440 --> 00:27:55,380",arabic:"كَأَنَّ الْأَمْرَ لَمْ يُعْجِبْكِ.",segs:[{ar:"كَأَنَّ الْأَمْرَ",uz:"Bu ish go‘yo"},{ar:"لَمْ يُعْجِبْكِ",uz:"sizga yoqmagandek"}],full_uz:"Bu ish sizga yoqmaganga o‘xshaydi.",note:"أَعْجَبَكِ — sizga yoqdi. كِ qo‘shimchasi ayol kishiga murojaatni bildiradi."},
{num:323,time:"00:27:55,380 --> 00:27:58,860",arabic:"لَيْسَ الْأَمْرُ كَذَلِكَ يَا أَبَا فَوْزٍ.",segs:[{ar:"لَيْسَ الْأَمْرُ كَذَلِكَ",uz:"Gap unday emas"},{ar:"يَا أَبَا فَوْزٍ",uz:"ey Abu Favz"}],full_uz:"Gap unday emas, ey Abu Favz.",note:null},
{num:324,time:"00:27:58,860 --> 00:28:03,760",arabic:"لَكِنَّكَ تَعْلَمُ أَنَّ سَعَادَةَ هِيَ ابْنَتُنَا الصُّغْرَى.",segs:[{ar:"لَكِنَّكَ تَعْلَمُ",uz:"Ammo siz bilasiz"},{ar:"أَنَّ سَعَادَةَ هِيَ ابْنَتُنَا الصُّغْرَى",uz:"Saodat bizning kenja qizimiz ekanini"}],full_uz:"Ammo Saodat bizning kenja qizimiz ekanini bilasiz.",note:null},
{num:325,time:"00:28:03,760 --> 00:28:06,120",arabic:"وَسَيَصْعُبُ عَلَيَّ فِرَاقُهَا.",segs:[{ar:"وَسَيَصْعُبُ عَلَيَّ",uz:"Va menga og‘ir bo‘ladi"},{ar:"فِرَاقُهَا",uz:"undan ayrilish"}],full_uz:"Undan ayrilish menga og‘ir bo‘ladi.",note:"صَعُبَ عَلَى فُلَانٍ — birovga qiyin yoki og‘ir bo‘lmoq. فِرَاقُهَا gapning egasi bo‘lib, fe’ldan keyin kelgan."},
{num:326,time:"00:28:07,380 --> 00:28:10,140",arabic:"الْبِنْتُ ضَيْفَةٌ فِي بَيْتِ أَبِيهَا يَا أُمَّ فَوْزٍ.",segs:[{ar:"الْبِنْتُ ضَيْفَةٌ",uz:"Qiz bola mehmon"},{ar:"فِي بَيْتِ أَبِيهَا",uz:"otasining uyida"},{ar:"يَا أُمَّ فَوْزٍ",uz:"ey Ummu Favz"}],full_uz:"Qiz bola otasining uyida mehmon, ey Ummu Favz.",note:"ضَيْفَةٌ — ayol mehmon. Bu yerda qizning turmushga chiqib, ota uyidan ketishi nazarda tutilgan."},
{num:327,time:"00:28:10,140 --> 00:28:11,680",arabic:"سَرْعَانَ مَا تُغَادِرُ.",segs:null,full_uz:"Ko‘p o‘tmay ketadi.",note:"سَرْعَانَ مَا — tez orada, ko‘p o‘tmay. Undagi مَا inkor bildirmaydi."},
{num:328,time:"00:28:11,680 --> 00:28:15,640",arabic:"وَإِذَا جَاءَكُمْ رَجُلٌ تَرْضَوْنَهُ زَوْجًا فَزَوِّجُوهُ.",segs:[{ar:"وَإِذَا جَاءَكُمْ رَجُلٌ",uz:"Agar oldingizga bir erkak kelsa"},{ar:"تَرْضَوْنَهُ زَوْجًا",uz:"uni er sifatida ma’qul ko‘rsangiz"},{ar:"فَزَوِّجُوهُ",uz:"unga qizingizni nikohlab beringlar"}],full_uz:"Agar oldingizga er sifatida ma’qul ko‘radigan bir erkak kelsa, unga qizingizni nikohlab beringlar.",note:"زَوَّجَ — uylantirmoq yoki turmushga bermoq. تَزَوَّجَ esa kishining o‘zi nikoh qurishini bildiradi."},
{num:329,time:"00:28:15,640 --> 00:28:17,780",arabic:"لَا أَعْرِفُ يَا مَرْوَانُ.",segs:[{ar:"لَا أَعْرِفُ",uz:"Bilmayman"},{ar:"يَا مَرْوَانُ",uz:"ey Marvon"}],full_uz:"Bilmayman, ey Marvon.",note:null},
{num:330,time:"00:28:17,780 --> 00:28:19,860",arabic:"دَعْنِي أُفَكِّرْ قَلِيلًا.",segs:[{ar:"دَعْنِي",uz:"Menga imkon bering"},{ar:"أُفَكِّرْ قَلِيلًا",uz:"biroz o‘ylab olay"}],full_uz:"Biroz o‘ylab olishimga imkon bering.",note:"دَعْنِي — meni qo‘ying, menga imkon bering. أُفَكِّرْ bu yerda buyruqning natijasi sifatida jazm holatida kelgan."},
{num:331,time:"00:28:19,860 --> 00:28:21,200",arabic:"كَمَا تَشَائِينَ.",segs:null,full_uz:"Xohlaganingizdek.",note:"تَشَائِينَ — ayol kishiga nisbatan «siz xohlaysiz». Erkakka murojaatda تَشَاءُ deyiladi."},
{num:332,time:"00:28:21,200 --> 00:28:23,980",arabic:"وَلَكِنِ اعْلَمِي أَنَّ الزَّوْجَ الصَّالِحَ...",segs:[{ar:"وَلَكِنِ اعْلَمِي",uz:"Lekin bilingki"},{ar:"أَنَّ الزَّوْجَ الصَّالِحَ",uz:"yaxshi er"}],full_uz:"Lekin bilingki, yaxshi er...",note:"اعْلَمِي — ayol kishiga qaratilgan «biling» buyrug‘i. الزَّوْجُ bu suhbatda qizning bo‘lajak erini anglatadi."},
{num:333,time:"00:28:23,980 --> 00:28:26,240",arabic:"نِعْمَةٌ مُهْدَاةٌ وَهَدِيَّةٌ مُزْجَاةٌ.",segs:[{ar:"نِعْمَةٌ مُهْدَاةٌ",uz:"In’om etilgan ne’mat"},{ar:"وَهَدِيَّةٌ مُزْجَاةٌ",uz:"va taqdim etilgan hadya"}],full_uz:"In’om etilgan ne’mat va taqdim etilgan hadyadir.",note:"مُهْدَاةٌ — أَهْدَى «hadya qilmoq» fe’lining majhul sifatdoshi. مُزْجَاةٌ ham bu yerda «yuborilgan, taqdim etilgan» ma’nosida."},
{num:334,time:"00:28:26,240 --> 00:28:28,340",arabic:"لَا يَنْبَغِي التَّفْرِيطُ فِيهِ.",segs:[{ar:"لَا يَنْبَغِي",uz:"Kerak emas"},{ar:"التَّفْرِيطُ فِيهِ",uz:"uni qo‘ldan chiqarish"}],full_uz:"Uni qo‘ldan chiqarish kerak emas.",note:"فَرَّطَ فِي شَيْءٍ — bir narsaga beparvo qarab, uni boy bermoq. التَّفْرِيطُ shu fe’lning masdari."},
{num:335,time:"00:28:28,340 --> 00:28:32,920",arabic:"حَدَّثَنَا عَبْدُ الرَّزَّاقِ.",segs:null,full_uz:"Bizga Abdurrazzoq rivoyat qildi.",note:"حَدَّثَنَا — «bizga so‘zlab berdi, rivoyat qildi». Hadis rivoyatida undan keyin rivoyat qiluvchining ismi keladi."},
{num:336,time:"00:28:32,920 --> 00:28:36,720",arabic:"حَدَّثَنَا مَعْمَرٌ.",segs:null,full_uz:"Bizga Ma’mar rivoyat qildi.",note:null},
{num:337,time:"00:28:36,720 --> 00:28:39,420",arabic:"عَنِ الزُّهْرِيِّ.",segs:null,full_uz:"Zuhriydan.",note:"Rivoyat zanjirida عَنْ bir xabar kimdan rivoyat qilinganini bildiradi."},
{num:338,time:"00:28:39,420 --> 00:28:43,920",arabic:"عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ:",segs:[{ar:"عَنْ عُرْوَةَ",uz:"Urvadan"},{ar:"عَنْ عَائِشَةَ",uz:"Oishadan"},{ar:"قَالَتْ",uz:"u aytdi"}],full_uz:"Urvadan, u esa Oishadan rivoyat qiladi. Oisha aytdi:",note:"عُرْوَةَ va عَائِشَةَ tanvin olmaydigan atoqli otlar bo‘lgani uchun عَنْ dan keyin ham oxirida fatha kelgan."},
{num:339,time:"00:28:43,920 --> 00:28:48,620",arabic:"كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"كَانَ رَسُولُ اللَّهِ",uz:"Allohning Rasuli ... edilar"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Allohning Rasuli, sollallohu alayhi vasallam, ... edilar.",note:"كَانَ bilan boshlangan gap keyingi banddagi يُصَلِّي bilan davom etadi. كَانَ يُصَلِّي — muntazam ravishda namoz o‘qir edilar."},
{num:340,time:"00:28:48,620 --> 00:28:51,640",arabic:"يُصَلِّي مِنَ اللَّيْلِ.",segs:null,full_uz:"Tunda namoz o‘qir edilar.",note:"مِنَ اللَّيْلِ — tunning bir qismida."},
{num:341,time:"00:28:51,640 --> 00:28:56,019",arabic:"إِحْدَى عَشْرَةَ رَكْعَةً.",segs:null,full_uz:"O‘n bir rakat.",note:"رَكْعَةٌ muannas bo‘lgani uchun «o‘n bir» إِحْدَى عَشْرَةَ shaklida kelgan. Sanalayotgan ot birlikda, tushum kelishigida: رَكْعَةً."},
{num:342,time:"00:28:56,019 --> 00:29:00,519",arabic:"فَإِذَا انْفَجَرَ الْفَجْرُ...",segs:null,full_uz:"Tong otgach esa...",note:"انْفَجَرَ الْفَجْرُ — tong otdi, tong yorishdi."},
{num:343,time:"00:29:00,519 --> 00:29:04,940",arabic:"صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ.",segs:[{ar:"صَلَّى رَكْعَتَيْنِ",uz:"Ikki rakat namoz o‘qir edilar"},{ar:"خَفِيفَتَيْنِ",uz:"qisqa"}],full_uz:"Ikki rakat qisqa namoz o‘qir edilar.",note:"رَكْعَتَيْنِ — ikki rakat. Uning sifati خَفِيفَتَيْنِ ham ikkilik va tushum kelishigida kelgan."},
{num:344,time:"00:29:06,720 --> 00:29:10,740",arabic:"ثُمَّ اتَّكَأَ عَلَى شِقِّهِ الْأَيْمَنِ.",segs:[{ar:"ثُمَّ اتَّكَأَ",uz:"So‘ng yonboshlardilar"},{ar:"عَلَى شِقِّهِ الْأَيْمَنِ",uz:"o‘ng yonlariga"}],full_uz:"So‘ng o‘ng yonlariga yonboshlardilar.",note:"شِقٌّ — bu yerda tananing yon tomoni. الْأَيْمَنُ — o‘ng, الْأَيْسَرُ — chap."},
{num:345,time:"00:29:10,740 --> 00:29:15,579",arabic:"حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ يُؤْذِنُهُ لِلصَّلَاةِ.",segs:[{ar:"حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ",uz:"Muazzin u zotning oldilariga kelgunicha"},{ar:"يُؤْذِنُهُ لِلصَّلَاةِ",uz:"namozga xabar berish uchun"}],full_uz:"Muazzin namozga xabar berish uchun oldilariga kelgunicha.",note:"يُؤْذِنُهُ — unga xabar beradi, bildiradi; bu آذَنَ fe’lidan. «Azon aytadi» ma’nosidagi يُؤَذِّنُ bilan farqlang."},
{num:346,time:"00:29:15,579 --> 00:29:18,059",arabic:"هَاتِ، نَاوِلْنِي، أَقْرَأْ مَا كَتَبْتَ.",segs:[{ar:"هَاتِ، نَاوِلْنِي",uz:"Qani, menga uzating"},{ar:"أَقْرَأْ مَا كَتَبْتَ",uz:"yozganingizni o‘qib olay"}],full_uz:"Qani, menga uzating, yozganingizni o‘qib olay.",note:"هَاتِ — erkak kishiga aytiladigan «bering, keltiring» buyrug‘i. Ayolga هَاتِي deyiladi."},
{num:347,time:"00:29:23,620 --> 00:29:25,740",arabic:"عَبَّاسَةُ، قَدْ نَامَ صَالِحٌ.",segs:[{ar:"عَبَّاسَةُ",uz:"Abbosa"},{ar:"قَدْ نَامَ صَالِحٌ",uz:"Solih uxlab qolibdi"}],full_uz:"Abbosa, Solih uxlab qolibdi.",note:null},
{num:348,time:"00:29:25,740 --> 00:29:33,220",arabic:"دَعْهُ يَرْتَحْ قَلِيلًا.",segs:[{ar:"دَعْهُ",uz:"Uni qo‘ying"},{ar:"يَرْتَحْ قَلِيلًا",uz:"biroz dam olsin"}],full_uz:"Uni qo‘ying, biroz dam olsin.",note:"يَرْتَحْ — يَرْتَاحُ fe’lining jazm shakli. Jazmda o‘zak ichidagi alif tushgan."},
{num:349,time:"00:29:33,220 --> 00:29:37,880",arabic:"أَمْ تَظُنُّهُ فِي مِثْلِ جَلَدِكَ وَصَبْرِكَ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"أَمْ تَظُنُّهُ",uz:"Yoki uni deb o‘ylaysizmi"},{ar:"فِي مِثْلِ جَلَدِكَ وَصَبْرِكَ",uz:"sizdek bardoshli va sabrli"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"ey Abu Abdulloh?"}],full_uz:"Yoki uni sizdek bardoshli va sabrli deb o‘ylaysizmi, ey Abu Abdulloh?",note:"جَلَدٌ — bardosh, chidamlilik. جِلْدٌ esa «teri» degani; harakat o‘zgarishi ma’noni o‘zgartiradi."},
{num:350,time:"00:29:37,880 --> 00:29:41,480",arabic:"الْعِلْمُ لَا يُنَالُ بِالرَّاحَةِ، يَظْفَرُ بِهِ مَنْ جَدَّ وَتَعِبَ.",segs:[{ar:"الْعِلْمُ لَا يُنَالُ بِالرَّاحَةِ",uz:"Ilmga rohat bilan erishilmaydi"},{ar:"يَظْفَرُ بِهِ",uz:"unga erishadi"},{ar:"مَنْ جَدَّ وَتَعِبَ",uz:"astoydil harakat qilib, mehnat chekkan kishi"}],full_uz:"Ilmga rohat bilan erishilmaydi. Unga astoydil harakat qilib, mehnat chekkan kishi erishadi.",note:"يُنَالُ — «erishiladi», majhul nisbat. ظَفِرَ بِشَيْءٍ — bir narsaga erishmoq. جَدَّ — jiddiy harakat qilmoq."},
{num:351,time:"00:29:41,480 --> 00:29:44,640",arabic:"رَحِمَكِ اللَّهُ يَا أُمِّي.",segs:[{ar:"رَحِمَكِ اللَّهُ",uz:"Alloh sizni rahmatiga olsin"},{ar:"يَا أُمِّي",uz:"ey onajonim"}],full_uz:"Alloh sizni rahmatiga olsin, onajonim.",note:null},
{num:352,time:"00:29:44,640 --> 00:29:46,799",arabic:"تَعَالَيْ وَانْظُرِي وَلَدَ أَحْمَدَ.",segs:[{ar:"تَعَالَيْ وَانْظُرِي",uz:"Keling va qarang"},{ar:"وَلَدَ أَحْمَدَ",uz:"Ahmadning o‘g‘liga"}],full_uz:"Keling, Ahmadning o‘g‘liga qarang.",note:"تَعَالَيْ va انْظُرِي — ayol kishiga qaratilgan buyruqlar. أَحْمَدَ tanvin olmaydigan ism bo‘lgani uchun izofada ham fatha bilan kelgan."},
{num:353,time:"00:29:46,799 --> 00:29:51,860",arabic:"أَتَظُنُّهَا كَانَتْ سَتَتْرُكُهُ يَخْلُدُ إِلَى النَّوْمِ وَيَتْرُكُ الْحَلْقَةَ؟",segs:[{ar:"أَتَظُنُّهَا كَانَتْ سَتَتْرُكُهُ",uz:"Unga yo‘l qo‘ygan bo‘lardi deb o‘ylaysizmi"},{ar:"يَخْلُدُ إِلَى النَّوْمِ",uz:"uyquga ketishiga"},{ar:"وَيَتْرُكُ الْحَلْقَةَ؟",uz:"va dars halqasini tark etishiga?"}],full_uz:"Uning uyquga ketib, dars halqasini tark etishiga onam yo‘l qo‘ygan bo‘lardi deb o‘ylaysizmi?",note:"خَلَدَ إِلَى النَّوْمِ — uyquga ketmoq. كَانَتْ سَتَتْرُكُهُ — o‘tgan vaziyatga nisbatan «unga yo‘l qo‘ygan bo‘lardi» ma’nosida."},
{num:354,time:"00:30:03,220 --> 00:30:08,519",arabic:"إِنْ كَانَ الْأَمْرُ يُضَايِقُكَ إِلَى هَذَا الْحَدِّ...",segs:[{ar:"إِنْ كَانَ الْأَمْرُ يُضَايِقُكَ",uz:"Agar bu ish sizni bezovta qilayotgan bo‘lsa"},{ar:"إِلَى هَذَا الْحَدِّ",uz:"shu darajada"}],full_uz:"Agar bu ish sizni shu darajada bezovta qilayotgan bo‘lsa...",note:"إِلَى هَذَا الْحَدِّ — shu darajada, shunchalik."},
{num:355,time:"00:30:08,519 --> 00:30:12,220",arabic:"لِمَ لَا تَتْرُكُهُ وَتَتَفَرَّغُ لِأَعْمَالِكَ؟",segs:[{ar:"لِمَ لَا تَتْرُكُهُ",uz:"Nega uni tashlamaysiz"},{ar:"وَتَتَفَرَّغُ لِأَعْمَالِكَ؟",uz:"va o‘z ishlaringiz bilan to‘liq shug‘ullanmaysiz?"}],full_uz:"Nega uni tashlab, o‘z ishlaringiz bilan to‘liq shug‘ullanmaysiz?",note:"تَفَرَّغَ لِشَيْءٍ — boshqa ishlardan bo‘shab, bor vaqtini bir ishga ajratmoq. لِمَ — «nega?»."},
{num:356,time:"00:30:13,940 --> 00:30:14,720",arabic:"أَأَتْرُكُ عَمَلِي؟",segs:null,full_uz:"Ishimni tashlaymi?",note:"Birinchi أَ so‘roq yuklamasi, ikkinchisi esa أَتْرُكُ «men tashlayman» fe’lining bir qismi."},
{num:357,time:"00:30:16,059 --> 00:30:19,940",arabic:"فَإِنْ لَمْ تَسْتَطِعْ أَنْ تُحِبَّ مَا تَعْمَلُ فَاعْمَلْ مَا تُحِبُّ.",segs:[{ar:"فَإِنْ لَمْ تَسْتَطِعْ",uz:"Agar qodir bo‘lmasangiz"},{ar:"أَنْ تُحِبَّ مَا تَعْمَلُ",uz:"qilayotgan ishingizni sevishga"},{ar:"فَاعْمَلْ مَا تُحِبُّ",uz:"unda sevgan ishingizni qiling"}],full_uz:"Agar qilayotgan ishingizni seva olmasangiz, sevgan ishingizni qiling.",note:"مَا تَعْمَلُ — siz qiladigan narsa yoki ish. Bu yerda مَا so‘roq yoki inkor emas, «...gan narsa» ma’nosidagi bog‘lovchi olmosh."},
{num:358,time:"00:30:19,940 --> 00:30:23,220",arabic:"لَدَيْكَ دَكَاكِينُكَ إِنْ كُنْتَ تَكْرَهُ الْجُلُوسَ فِي الْبَيْتِ.",segs:[{ar:"لَدَيْكَ دَكَاكِينُكَ",uz:"Sizning do‘konlaringiz bor"},{ar:"إِنْ كُنْتَ تَكْرَهُ الْجُلُوسَ",uz:"agar o‘tirishni yoqtirmasangiz"},{ar:"فِي الْبَيْتِ",uz:"uyda"}],full_uz:"Agar uyda o‘tirishni yoqtirmasangiz, do‘konlaringiz bor-ku.",note:"دَكَاكِينُ — دُكَّانٌ «do‘kon» so‘zining ko‘pligi. الْجُلُوسُ — جَلَسَ «o‘tirmoq» fe’lining masdari."},
{num:359,time:"00:30:25,660 --> 00:30:28,220",arabic:"أَنَا رَجُلٌ أَمْضَى عُمْرَهُ مَعَ الْعَسْكَرِ.",segs:[{ar:"أَنَا رَجُلٌ",uz:"Men bir odamman"},{ar:"أَمْضَى عُمْرَهُ",uz:"umrini o‘tkazgan"},{ar:"مَعَ الْعَسْكَرِ",uz:"askarlar bilan"}],full_uz:"Men umrini askarlar bilan o‘tkazgan odamman.",note:"أَمْضَى عُمْرَهُ — umrini o‘tkazdi. أَمْضَى bilan boshlangan gap noaniq رَجُلٌ otini tavsiflab kelgan."},
{num:360,time:"00:30:28,220 --> 00:30:32,120",arabic:"لَا أَجِدُ نَفْسِي إِلَّا بَيْنَ الْجُنْدِ وَقَعْقَعَةِ السُّيُوفِ.",segs:[{ar:"لَا أَجِدُ نَفْسِي إِلَّا",uz:"O‘zimni faqat ... topaman"},{ar:"بَيْنَ الْجُنْدِ",uz:"askarlar orasida"},{ar:"وَقَعْقَعَةِ السُّيُوفِ",uz:"va qilichlar jarangi ichida"}],full_uz:"O‘zimni faqat askarlar orasida, qilichlar jarangi ichida topaman.",note:"أَجِدُ نَفْسِي bu yerda «o‘zimni o‘z o‘rnimda his qilaman» ma’nosida. قَعْقَعَةٌ — qattiq narsalarning bir-biriga urilishidan chiqadigan jarang."},
{num:361,time:"00:30:32,119 --> 00:30:35,319",arabic:"زَوْجِي رَجُلٌ وَلُوعٌ بِالْمَتَاعِبِ.",segs:[{ar:"زَوْجِي رَجُلٌ",uz:"Erim shunday odamki"},{ar:"وَلُوعٌ بِالْمَتَاعِبِ",uz:"mashaqqatlarni juda yaxshi ko‘radi"}],full_uz:"Erim mashaqqatlarni juda yaxshi ko‘radigan odam.",note:"وَلُوعٌ بِشَيْءٍ — bir narsaga juda ishqiboz, uni juda yaxshi ko‘radigan. الْمَتَاعِبُ — mashaqqatlar, qiyinchiliklar."},
{num:362,time:"00:30:35,319 --> 00:30:37,619",arabic:"أَلَسْتَ غَيْرَ رَاضٍ عَنْ عَمَلِكَ؟",segs:[{ar:"أَلَسْتَ غَيْرَ رَاضٍ",uz:"Axir norozi emasmisiz"},{ar:"عَنْ عَمَلِكَ؟",uz:"ishingizdan?"}],full_uz:"Axir ishingizdan norozi emasmisiz?",note:"رَاضٍ عَنْ — ...dan rozi. غَيْرَ رَاضٍ — norozi. رَاضٍ so‘zi noaniq bosh va qaratqich kelishiklarida oxirgi ي harfini yo‘qotadi."},
{num:363,time:"00:30:37,619 --> 00:30:39,039",arabic:"إِنَّ الَّذِينَ جَاءُوا مِنْ بَعْدِي...",segs:[{ar:"إِنَّ الَّذِينَ جَاءُوا",uz:"Darhaqiqat, kelganlar"},{ar:"مِنْ بَعْدِي",uz:"mendan keyin"}],full_uz:"Mendan keyin kelganlar esa...",note:"مِنْ بَعْدِي — mendan keyin. Gapning xabari keyingi bandda keladi."},
{num:364,time:"00:30:39,039 --> 00:30:42,439",arabic:"يَتَوَلَّوْنَ الْآنَ قِيَادَةَ الْجُنْدِ وَالدَّوَاوِينِ.",segs:[{ar:"يَتَوَلَّوْنَ الْآنَ",uz:"Hozir zimmasiga olmoqdalar"},{ar:"قِيَادَةَ الْجُنْدِ وَالدَّوَاوِينِ",uz:"qo‘shin va devonlar boshqaruvini"}],full_uz:"Hozir qo‘shin va devonlarni boshqarmoqdalar.",note:"تَوَلَّى — bir ishni zimmasiga olmoq, boshqarmoq. الدَّوَاوِينُ bu yerda davlat boshqaruv idoralarini bildiradi."},
{num:365,time:"00:30:42,439 --> 00:30:45,379",arabic:"وَأَنَا أَلْقَوْا بِي إِلَى السِّجْنِ.",segs:[{ar:"وَأَنَا",uz:"Meni esa"},{ar:"أَلْقَوْا بِي إِلَى السِّجْنِ",uz:"qamoqxonaga tashlashdi"}],full_uz:"Meni esa qamoqxonaga tashlashdi.",note:"أَلْقَى بِهِ — uni tashladi. Bu suhbatda qamoqxonada xizmat qilishga yuborilganini norozilik bilan ifodalamoqda."},
{num:366,time:"00:30:45,379 --> 00:30:48,439",arabic:"فَلَسْتُ أَدْرِي مَاذَا بَعْدَ السِّجْنِ.",segs:[{ar:"فَلَسْتُ أَدْرِي",uz:"Endi bilmayman"},{ar:"مَاذَا بَعْدَ السِّجْنِ",uz:"qamoqxonadan keyin nima bo‘lishini"}],full_uz:"Endi qamoqxonadan keyin nima bo‘lishini bilmayman.",note:"لَسْتُ أَدْرِي — bilmayman. أَدْرِي — دَرَى «bilmoq» fe’lining birinchi shaxs shakli."},
{num:367,time:"00:30:48,439 --> 00:30:51,619",arabic:"إِنَّهُ الْبَيْتُ.",segs:null,full_uz:"Keyingisi uy.",note:"إِنَّهُ الْبَيْتُ so‘zma-so‘z «u — uy». Oldingi savolga javoban navbatdagi joy uy bo‘lishi aytilmoqda."},
{num:368,time:"00:30:51,619 --> 00:30:53,299",arabic:"غَرِيبٌ أَمْرُكَ وَاللَّهِ.",segs:[{ar:"غَرِيبٌ أَمْرُكَ",uz:"Ishingiz g‘alati"},{ar:"وَاللَّهِ",uz:"Allohga qasam"}],full_uz:"Allohga qasam, ishingiz g‘alati.",note:"غَرِيبٌ xabar bo‘lib, أَمْرُكَ egasidan oldin kelgan. وَاللَّهِ dagi وَ qasamni bildiradi."},
{num:369,time:"00:30:53,299 --> 00:30:56,759",arabic:"تَصْبِرُ عَلَى الْعَمَلِ مَعَهُمْ وَلَسْتُمْ عَلَى وِفَاقٍ.",segs:[{ar:"تَصْبِرُ عَلَى الْعَمَلِ مَعَهُمْ",uz:"Ular bilan ishlashga chidaysiz"},{ar:"وَلَسْتُمْ عَلَى وِفَاقٍ",uz:"holbuki, o‘zaro kelishmaysizlar"}],full_uz:"O‘zaro kelishmasangiz ham, ular bilan ishlashga chidaysiz.",note:"عَلَى وِفَاقٍ — o‘zaro kelishgan, ahil holatda. وَ bu yerda bir vaqtdagi holatni bildirib, «holbuki» deb tarjima qilinadi."},
{num:370,time:"00:30:56,759 --> 00:31:00,679",arabic:"لَا أَنْتَ تَلِينُ لَهُمْ أَوْ تَعْتَنِقُ مَذْهَبَهُمْ، وَلَا هُمْ كَذَلِكَ.",segs:[{ar:"لَا أَنْتَ تَلِينُ لَهُمْ",uz:"Na siz ularga yon berasiz"},{ar:"أَوْ تَعْتَنِقُ مَذْهَبَهُمْ",uz:"yoki ularning mazhabini qabul qilasiz"},{ar:"وَلَا هُمْ كَذَلِكَ",uz:"na ular ham shunday qiladilar"}],full_uz:"Na siz ularga yon berasiz yoki mazhabini qabul qilasiz, na ular ham shunday qiladilar.",note:"لَانَ لَهُ — unga yumshoq munosabatda bo‘lmoq, yon bermoq. اعْتَنَقَ مَذْهَبًا — bir mazhab yoki qarashni qabul qilmoq."},
{num:371,time:"00:31:00,679 --> 00:31:01,659",arabic:"لَا يَا فَوْزُ.",segs:null,full_uz:"Yo‘q, ey Favz.",note:null},
{num:372,time:"00:31:01,660 --> 00:31:05,080",arabic:"هُمْ أَهْوَنُ مِنْ أَنْ أُدَاهِنَهُمْ وَأَخْضَعَ لَهُمْ.",segs:[{ar:"هُمْ أَهْوَنُ",uz:"Ular juda arzimas"},{ar:"مِنْ أَنْ أُدَاهِنَهُمْ",uz:"men ularga xushomad qilishim uchun"},{ar:"وَأَخْضَعَ لَهُمْ",uz:"va ularga bo‘ysunishim uchun"}],full_uz:"Ular mening xushomad qilishimga va bo‘ysunishimga arzimaydi.",note:"أَهْوَنُ — arzimasroq, qadrsizroq. دَاهَنَ — manfaat uchun yon bermoq yoki xushomad qilmoq. خَضَعَ لِـ — ...ga bo‘ysunmoq."},
{num:373,time:"00:31:05,080 --> 00:31:08,340",arabic:"لَسْتُ أَنَا مَنْ يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا.",segs:[{ar:"لَسْتُ أَنَا مَنْ يَبِيعُ دِينَهُ",uz:"Men dinini sotadigan kishi emasman"},{ar:"بِعَرَضٍ مِنَ الدُّنْيَا",uz:"dunyoning o‘tkinchi matohi evaziga"}],full_uz:"Men dunyoning o‘tkinchi matohi evaziga dinini sotadigan kishi emasman.",note:"عَرَضٌ — bu yerda o‘tkinchi dunyoviy mol-manfaat. بِـ sotish yoki almashtirish evaziga olinadigan narsani bildiradi."},
{num:374,time:"00:31:08,340 --> 00:31:09,440",arabic:"سُحْقًا لَهُ.",segs:null,full_uz:"Yo‘qolsin u!",note:"سُحْقًا لَهُ — qattiq norozilik va qarg‘ishni bildiradigan ibora."},
{num:375,time:"00:31:09,440 --> 00:31:15,120",arabic:"وَكُلَّ يَوْمٍ يَبْلُغُ إِجْلَالِي لَكَ مَدَاهُ يَا شَفِيقُ.",segs:[{ar:"وَكُلَّ يَوْمٍ",uz:"Va har kuni"},{ar:"يَبْلُغُ إِجْلَالِي لَكَ مَدَاهُ",uz:"sizga bo‘lgan hurmatim eng yuqori darajasiga yetadi"},{ar:"يَا شَفِيقُ",uz:"ey Shafiq"}],full_uz:"Ey Shafiq, har kuni sizga bo‘lgan hurmatim eng yuqori darajasiga yetadi.",note:"إِجْلَالٌ — chuqur hurmat, ulug‘lash. بَلَغَ مَدَاهُ — eng yuqori darajasiga yoki chegarasiga yetdi."},
{num:376,time:"00:31:15,120 --> 00:31:16,680",arabic:"فَاصْبِرْ.",segs:null,full_uz:"Bas, sabr qiling.",note:"اصْبِرْ — صَبَرَ يَصْبِرُ fe’lining buyruq shakli."},
{num:377,time:"00:31:16,680 --> 00:31:18,740",arabic:"إِنَّ اللَّهَ مَعَ الصَّابِرِينَ.",segs:[{ar:"إِنَّ اللَّهَ",uz:"Albatta, Alloh"},{ar:"مَعَ الصَّابِرِينَ",uz:"sabr qiluvchilar bilan"}],full_uz:"Albatta, Alloh sabr qiluvchilar bilan.",note:"الصَّابِرِينَ — صَابِرٌ «sabr qiluvchi» so‘zining ko‘pligi. مَعَ dan keyin qaratqich kelishigida kelgan."},
{num:378,time:"00:32:01,660 --> 00:32:11,940",arabic:"هُوَ شَرْحٌ مُمْتِعٌ أَيْضًا كَعَادَتِهِ، حَبَاهُ اللَّهُ.",segs:[{ar:"هُوَ شَرْحٌ مُمْتِعٌ أَيْضًا",uz:"Bu ham maroqli sharh"},{ar:"كَعَادَتِهِ",uz:"uning odatidek"},{ar:"حَبَاهُ اللَّهُ",uz:"Alloh unga in’om bersin"}],full_uz:"Bu ham uning odatidek maroqli sharh. Alloh unga in’om bersin.",note:"حَبَا — in’om bermoq, ato qilmoq. كَعَادَتِهِ — uning odatidek."},
{num:379,time:"00:32:11,940 --> 00:32:18,840",arabic:"مَا بِكَ يَا أَبَا نَصْرٍ؟ تَبْدُو عَلَى غَيْرِ سَجِيَّتِكَ هَذَا الْيَوْمَ.",segs:[{ar:"مَا بِكَ",uz:"Sizga nima bo‘ldi"},{ar:"يَا أَبَا نَصْرٍ؟",uz:"ey Abu Nasr?"},{ar:"تَبْدُو عَلَى غَيْرِ سَجِيَّتِكَ",uz:"Odatdagi holatingizdan boshqacha ko‘rinyapsiz"},{ar:"هَذَا الْيَوْمَ",uz:"bugun"}],full_uz:"Sizga nima bo‘ldi, ey Abu Nasr? Bugun odatdagi holatingizdan boshqacha ko‘rinyapsiz.",note:"سَجِيَّةٌ — kishining tabiati, odatiy fe’l-atvori. عَلَى غَيْرِ سَجِيَّتِكَ — odatdagi tabiatingizga mos bo‘lmagan holatda."},
{num:380,time:"00:32:18,840 --> 00:32:22,420",arabic:"لَا أَكْتُمُكَ سِرًّا يَا ابْنَ نُوحٍ.",segs:[{ar:"لَا أَكْتُمُكَ سِرًّا",uz:"Sizdan sir yashirmayman"},{ar:"يَا ابْنَ نُوحٍ",uz:"ey Ibn Nuh"}],full_uz:"Sizdan sir yashirmayman, ey Ibn Nuh.",note:"لَا أَكْتُمُكَ سِرًّا — ochiq gapirish oldidan ishlatiladigan «sizdan yashirmayman» iborasi."},
{num:381,time:"00:32:22,420 --> 00:32:25,880",arabic:"الْأَخْبَارُ غَيْرُ مُطْمَئِنَةٍ.",segs:null,full_uz:"Xabarlar ko‘ngilni xotirjam qiladigan emas.",note:"الْأَخْبَارُ jonsiz narsalar ko‘pligi bo‘lgani uchun مُطْمَئِنَةٍ muannas birlik shaklida kelgan."},
{num:382,time:"00:32:25,880 --> 00:32:27,660",arabic:"أَيُّ أَخْبَارٍ؟",segs:null,full_uz:"Qanday xabarlar?",note:null},
{num:383,time:"00:32:28,400 --> 00:32:29,660",arabic:"أَخْبَارُ قَصْرِ الْخِلَافَةِ.",segs:null,full_uz:"Xalifalik saroyining xabarlari.",note:"أَخْبَارُ قَصْرِ الْخِلَافَةِ — ketma-ket izofa: «xalifalik saroyining xabarlari»."},
{num:384,time:"00:32:29,660 --> 00:32:32,660",arabic:"أَتَقْصِدُ مَا أُشِيعَ عَنْ مَرَضِ الْمَأْمُونِ؟",segs:[{ar:"أَتَقْصِدُ مَا أُشِيعَ",uz:"Tarqalgan gaplarni nazarda tutyapsizmi"},{ar:"عَنْ مَرَضِ الْمَأْمُونِ؟",uz:"Ma’munning kasalligi haqidagi?"}],full_uz:"Ma’munning kasalligi haqida tarqalgan gaplarni nazarda tutyapsizmi?",note:"أُشِيعَ — tarqatildi, yoyildi; أَشَاعَ fe’lining majhul shakli. مَا أُشِيعَ — tarqalgan gap yoki xabar."},
{num:385,time:"00:32:34,660 --> 00:32:43,660",arabic:"لَا، الْأَمْرُ أَخْطَرُ مِنْ ذَلِكَ، وَلَكِنَّنِي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ.",segs:[{ar:"لَا، الْأَمْرُ أَخْطَرُ مِنْ ذَلِكَ",uz:"Yo‘q, masala bundan xavfliroq"},{ar:"وَلَكِنَّنِي لَمْ أَتَأَكَّدْ مِنْهُ بَعْدُ",uz:"lekin men hali uning rostligiga ishonch hosil qilganim yo‘q"}],full_uz:"Yo‘q, masala bundan xavfliroq. Lekin men hali uning rostligiga ishonch hosil qilganim yo‘q.",note:"تَأَكَّدَ مِنْ — bir narsaning aniqligi yoki rostligiga ishonch hosil qilmoq. لَمْ ... بَعْدُ — hali ...gani yo‘q."},
{num:386,time:"00:32:44,660 --> 00:32:48,660",arabic:"لَقَدْ زِدْتَنِي قَلَقًا فَوْقَ قَلَقِي يَا أَبَا نَصْرٍ، فَمَا الْخَطْبُ؟",segs:[{ar:"لَقَدْ زِدْتَنِي قَلَقًا",uz:"Tashvishimni oshirdingiz"},{ar:"فَوْقَ قَلَقِي",uz:"avvalgi tashvishim ustiga"},{ar:"يَا أَبَا نَصْرٍ",uz:"ey Abu Nasr"},{ar:"فَمَا الْخَطْبُ؟",uz:"Xo‘sh, nima gap?"}],full_uz:"Ey Abu Nasr, tashvishim ustiga yana tashvish qo‘shdingiz. Xo‘sh, nima gap?",note:"مَا الْخَطْبُ؟ — «nima bo‘ldi?», «qanday jiddiy ish yuz berdi?» degan savol. الْخَطْبُ odatda muhim yoki og‘ir voqeani anglatadi."},
{num:387,time:"00:32:49,660 --> 00:32:57,660",arabic:"سَمِعْتُ مِنْ أَحَدِ الْإِخْوَةِ الَّذِينَ يَعْمَلُونَ فِي الْقَصْرِ أَنَّ الْمَأْمُونَ يُبَيِّتُ أَمْرًا بِلَيْلٍ.",segs:[{ar:"سَمِعْتُ مِنْ أَحَدِ الْإِخْوَةِ",uz:"Birodarlardan biridan eshitdim"},{ar:"الَّذِينَ يَعْمَلُونَ فِي الْقَصْرِ",uz:"saroyda ishlaydigan"},{ar:"أَنَّ الْمَأْمُونَ يُبَيِّتُ أَمْرًا بِلَيْلٍ",uz:"Ma’mun tunda bir ishni yashirincha rejalashtirayotganini"}],full_uz:"Saroyda ishlaydigan birodarlardan biridan Ma’mun tunda bir ishni yashirincha rejalashtirayotganini eshitdim.",note:"بَيَّتَ أَمْرًا — bir ishni tunda yoki yashirincha rejalashtirmoq. بِلَيْلٍ — tunda."},
{num:388,time:"00:32:57,660 --> 00:33:04,660",arabic:"الْمَأْمُونُ سَيَفْرِضُ مَذْهَبَ الِاعْتِزَالِ دِينًا لِلدَّوْلَةِ.",segs:[{ar:"الْمَأْمُونُ سَيَفْرِضُ",uz:"Ma’mun majburiy joriy qiladi"},{ar:"مَذْهَبَ الِاعْتِزَالِ",uz:"mo‘tazila mazhabini"},{ar:"دِينًا لِلدَّوْلَةِ",uz:"davlat dini sifatida"}],full_uz:"Ma’mun mo‘tazila mazhabini davlat dini sifatida majburiy joriy qiladi.",note:"فَرَضَ — majburiy qilmoq, joriy etmoq. مَذْهَبُ الِاعْتِزَالِ bu suhbatda mo‘tazila yo‘nalishini anglatadi."},
{num:389,time:"00:33:04,660 --> 00:33:06,660",arabic:"أَعُوذُ بِاللَّهِ مِنْ مَقْتِ اللَّهِ.",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنْ مَقْتِ اللَّهِ",uz:"Allohning qattiq g‘azabidan"}],full_uz:"Allohning qattiq g‘azabidan Allohdan panoh so‘rayman.",note:"عَاذَ بِـ ... مِنْ ... — biror narsadan panoh so‘rab, kimgadir yuzlanmoq. مَقْتٌ — qattiq nafrat va g‘azab."},
{num:390,time:"00:33:06,660 --> 00:33:08,660",arabic:"سَلِّمْ يَا رَبِّي سَلِّمْ.",segs:[{ar:"سَلِّمْ يَا رَبِّي",uz:"O‘zingiz asrang, ey Rabbim"},{ar:"سَلِّمْ",uz:"asrang"}],full_uz:"O‘zingiz asrang, ey Rabbim, asrang.",note:"سَلِّمْ bu duoda «omon saqla, ofatdan asra» ma’nosida."},
{num:391,time:"00:33:08,660 --> 00:33:12,660",arabic:"لَمْ أَتَأَكَّدْ بَعْدُ مِنَ الْخَبَرِ كَمَا قُلْتُ لَكَ.",segs:[{ar:"لَمْ أَتَأَكَّدْ بَعْدُ مِنَ الْخَبَرِ",uz:"Hali xabarning rostligiga ishonch hosil qilmadim"},{ar:"كَمَا قُلْتُ لَكَ",uz:"sizga aytganimdek"}],full_uz:"Sizga aytganimdek, hali xabarning rostligiga ishonch hosil qilmadim.",note:null},
{num:392,time:"00:33:12,660 --> 00:33:16,660",arabic:"فَاجْعَلْ مَا ذَكَرْتُ طَيَّ الْكِتْمَانِ.",segs:[{ar:"فَاجْعَلْ مَا ذَكَرْتُ",uz:"Shunday ekan, aytganlarimni saqlang"},{ar:"طَيَّ الْكِتْمَانِ",uz:"sir holda"}],full_uz:"Shunday ekan, aytganlarimni sir saqlang.",note:"طَيَّ الْكِتْمَانِ — sir tutilgan, oshkor qilinmagan holda. كِتْمَانٌ — yashirish, sir saqlash."},
{num:393,time:"00:33:18,660 --> 00:33:21,660",arabic:"وَلَكِنَّهُ إِنْ كَانَ صَحِيحًا...",segs:[{ar:"وَلَكِنَّهُ",uz:"Ammo u"},{ar:"إِنْ كَانَ صَحِيحًا",uz:"agar rost bo‘lsa"}],full_uz:"Ammo agar u rost bo‘lsa...",note:"هُ olmoshi oldingi الْخَبَرُ «xabar» so‘ziga qaytmoqda."},
{num:394,time:"00:33:21,660 --> 00:33:24,660",arabic:"فَنَحْنُ أَمَامَ أَيَّامِ الْمَوْتِ.",segs:[{ar:"فَنَحْنُ أَمَامَ",uz:"Unda biz qarshisidamiz"},{ar:"أَيَّامِ الْمَوْتِ",uz:"o‘lim kunlarining"}],full_uz:"Unda bizni o‘lim kunlari kutmoqda.",note:"نَحْنُ أَمَامَ ... so‘zma-so‘z «biz ... qarshisidamiz»; kelajakdagi voqealar haqida «bizni ... kutmoqda» deb tarjima qilinadi."},
{num:395,time:"00:33:24,660 --> 00:33:29,100",arabic:"وَنَحْنُ أَمَامَ أَيَّامِ الْمِحَنِ وَالِابْتِلَاءِ.",segs:[{ar:"وَنَحْنُ أَمَامَ",uz:"Va biz qarshisidamiz"},{ar:"أَيَّامِ الْمِحَنِ وَالِابْتِلَاءِ",uz:"musibat va sinov kunlarining"}],full_uz:"Bizni musibat va sinov kunlari kutmoqda.",note:"مِحَنٌ — مِحْنَةٌ «og‘ir sinov, musibat» so‘zining ko‘pligi. ابْتِلَاءٌ — sinash, sinov."},
{num:396,time:"00:33:33,160 --> 00:33:46,660",arabic:"لَيْتَ أَبِي يَأْذَنُ لِي بِالْعَمَلِ مَعَكَ يَا عُمَرُ.",segs:[{ar:"لَيْتَ أَبِي يَأْذَنُ لِي",uz:"Qaniydi, otam menga ruxsat bersalar"},{ar:"بِالْعَمَلِ مَعَكَ",uz:"siz bilan ishlashga"},{ar:"يَا عُمَرُ",uz:"ey Umar"}],full_uz:"Qaniydi, otam siz bilan ishlashimga ruxsat bersalar, ey Umar.",note:"لَيْتَ — amalga oshishi orzu qilinayotgan istakni bildiradi. أَذِنَ لَهُ بِشَيْءٍ — unga biror narsaga ruxsat bermoq."},
{num:397,time:"00:33:46,660 --> 00:33:49,160",arabic:"عَجَبًا يَا صَالِحُ!",segs:null,full_uz:"Ajabo, ey Solih!",note:"عَجَبًا — hayratni ifodalovchi so‘z: «ajabo!», «qiziq!»."},
{num:398,time:"00:33:49,160 --> 00:33:52,440",arabic:"أَيَسْتَبْدِلُ عَاقِلٌ طَلَبَ الْعِلْمِ بِإِصْلَاحِ نِعَالِ النَّاسِ؟",segs:[{ar:"أَيَسْتَبْدِلُ عَاقِلٌ",uz:"Aqlli odam almashtiradimi"},{ar:"طَلَبَ الْعِلْمِ",uz:"ilm olishni"},{ar:"بِإِصْلَاحِ نِعَالِ النَّاسِ؟",uz:"odamlarning oyoq kiyimlarini tuzatishga?"}],full_uz:"Aqlli odam ilm olishni odamlarning oyoq kiyimlarini tuzatishga almashtiradimi?",note:"Bu so‘roq javob olishdan ko‘ra norozilik va taajjubni bildiradi. نِعَالٌ — نَعْلٌ «kavush, shippak» so‘zining ko‘pligi."},
{num:399,time:"00:33:52,440 --> 00:33:56,299",arabic:"يَبْدُو أَنَّكَ لَمْ تَرِثْ عَنْ أَبِيكَ حُبَّهُ لِلْعِلْمِ.",segs:[{ar:"يَبْدُو أَنَّكَ",uz:"Aftidan, siz"},{ar:"لَمْ تَرِثْ عَنْ أَبِيكَ",uz:"otangizdan meros olmabsiz"},{ar:"حُبَّهُ لِلْعِلْمِ",uz:"uning ilmga muhabbatini"}],full_uz:"Aftidan, otangizning ilmga muhabbati sizga meros bo‘lib o‘tmabdi.",note:"وَرِثَ يَرِثُ — meros olmoq. لَمْ تَرِثْ shaklida fe’l jazm qilingan, shuning uchun oxiri sukunli."},
{num:400,time:"00:33:56,299 --> 00:33:58,240",arabic:"وَمَنْ لَا يُحِبُّ الْعِلْمَ يَا عُمَرُ؟",segs:[{ar:"وَمَنْ لَا يُحِبُّ الْعِلْمَ",uz:"Ilmni kim sevmaydi"},{ar:"يَا عُمَرُ؟",uz:"ey Umar?"}],full_uz:"Ilmni kim sevmaydi, ey Umar?",note:null},
{num:401,time:"00:33:58,240 --> 00:34:01,480",arabic:"وَلَكِنَّنِي أُرِيدُ أَنْ أُسَاعِدَ أَبِي عَلَى تَكَالِيفِ الْحَيَاةِ.",segs:[{ar:"وَلَكِنَّنِي أُرِيدُ",uz:"Lekin men istayman"},{ar:"أَنْ أُسَاعِدَ أَبِي",uz:"otamga yordam berishni"},{ar:"عَلَى تَكَالِيفِ الْحَيَاةِ",uz:"turmush xarajatlarini qoplashda"}],full_uz:"Lekin men otamga turmush xarajatlarini qoplashda yordam bermoqchiman.",note:"تَكَالِيفُ الْحَيَاةِ — yashash, turmush xarajatlari. سَاعَدَهُ عَلَى شَيْءٍ — unga biror ishda yordam bermoq."},
{num:402,time:"00:34:01,480 --> 00:34:05,279",arabic:"أَتَعْلَمُ إِنْ رَآكَ الْإِمَامُ عِنْدِي مَاذَا سَيَفْعَلُ؟",segs:[{ar:"أَتَعْلَمُ",uz:"Bilasizmi"},{ar:"إِنْ رَآكَ الْإِمَامُ عِنْدِي",uz:"agar imom sizni mening yonimda ko‘rsalar"},{ar:"مَاذَا سَيَفْعَلُ؟",uz:"nima qiladilar?"}],full_uz:"Imom sizni mening yonimda ko‘rsalar, nima qilishlarini bilasizmi?",note:"رَآكَ — sizni ko‘rdi. إِنْ shart yuklamasidan keyin o‘tgan zamon shakli kelajakdagi ehtimoliy holatni ham bildirishi mumkin."},
{num:403,time:"00:34:05,279 --> 00:34:06,019",arabic:"مَاذَا سَيَفْعَلُ؟",segs:null,full_uz:"Nima qiladilar?",note:null},
{num:404,time:"00:34:06,019 --> 00:34:06,900",arabic:"سَيَطْرُدُنَا مَعًا.",segs:null,full_uz:"Ikkalamizni ham haydab yuboradilar.",note:"نَا — «bizni» ma’nosidagi to‘ldiruvchi olmosh. مَعًا — birga, birgalikda."},
{num:405,time:"00:34:08,559 --> 00:34:09,800",arabic:"وَعَلَيْكُمُ السَّلَامُ.",segs:null,full_uz:"Sizlarga ham tinchlik bo‘lsin.",note:null},
{num:406,time:"00:34:09,800 --> 00:34:11,579",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga ham tinchlik va Allohning rahmati bo‘lsin.",note:null},
{num:407,time:"00:34:11,579 --> 00:34:17,559",arabic:"كَيْفَ هِيَ الْأَسْعَارُ لَدَيْكَ الْيَوْمَ؟",segs:[{ar:"كَيْفَ هِيَ الْأَسْعَارُ",uz:"Narxlar qanday"},{ar:"لَدَيْكَ الْيَوْمَ؟",uz:"bugun sizda?"}],full_uz:"Bugun sizda narxlar qanday?",note:"أَسْعَارٌ — سِعْرٌ «narx» so‘zining ko‘pligi."},
{num:408,time:"00:34:17,559 --> 00:34:20,559",arabic:"كَمَا كَانَتْ بِالْأَمْسِ أَيُّهَا الْمُحْتَسِبُ.",segs:[{ar:"كَمَا كَانَتْ بِالْأَمْسِ",uz:"Kechagidek"},{ar:"أَيُّهَا الْمُحْتَسِبُ",uz:"ey muhtasib"}],full_uz:"Kechagidek, ey muhtasib.",note:"الْمُحْتَسِبُ — bu suhbatda bozordagi savdo tartibini nazorat qiluvchi mansabdor. كَانَتْ ning yashirin egasi الْأَسْعَارُ so‘ziga qaytadi."},
{num:409,time:"00:34:20,559 --> 00:34:27,139",arabic:"وَكَيْفَ كَانَتْ فِي الْأَمْسِ؟ أَظُنُّكَ سَتَقُولُ لِي: كَمَا كَانَتْ قَبْلَ أَمْسِ.",segs:[{ar:"وَكَيْفَ كَانَتْ فِي الْأَمْسِ؟",uz:"Kecha qanday edi?"},{ar:"أَظُنُّكَ سَتَقُولُ لِي",uz:"O‘ylashimcha, menga deysiz"},{ar:"كَمَا كَانَتْ قَبْلَ أَمْسِ",uz:"o‘tgan kungidek"}],full_uz:"Kecha qanday edi? O‘ylashimcha, menga «o‘tgan kungidek» deysiz.",note:"أَمْسِ — kecha. قَبْلَ أَمْسِ — kechadan oldingi kun, o‘tgan kun."},
{num:410,time:"00:34:27,139 --> 00:34:36,579",arabic:"نَحْنُ لَسْنَا مِنْ أُولَئِكَ الَّذِينَ يَتَلَاعَبُونَ بِالْأَسْعَارِ.",segs:[{ar:"نَحْنُ لَسْنَا مِنْ أُولَئِكَ",uz:"Biz o‘sha kishilardan emasmiz"},{ar:"الَّذِينَ يَتَلَاعَبُونَ بِالْأَسْعَارِ",uz:"narxlarni o‘z bilganicha o‘zgartiradigan"}],full_uz:"Biz narxlarni o‘z bilganicha o‘zgartiradigan kishilardan emasmiz.",note:"تَلَاعَبَ بِـ — bir narsani suiiste’mol qilmoq, u bilan o‘z manfaatiga mos ravishda o‘ynashmoq."},
{num:411,time:"00:34:36,579 --> 00:34:39,920",arabic:"نَحْنُ نَخَافُ اللَّهَ، اللَّهَ فَقَطْ.",segs:[{ar:"نَحْنُ نَخَافُ اللَّهَ",uz:"Biz Allohdan qo‘rqamiz"},{ar:"اللَّهَ فَقَطْ",uz:"faqat Allohdan"}],full_uz:"Biz Allohdan, faqat Allohdan qo‘rqamiz.",note:"اللَّهَ so‘zining takrorlanishi ta’kidni kuchaytiradi. فَقَطْ — faqat, xolos."},
{num:412,time:"00:34:39,920 --> 00:34:42,440",arabic:"جَيِّدٌ، جَيِّدٌ.",segs:null,full_uz:"Yaxshi, yaxshi.",note:null},
{num:413,time:"00:34:42,440 --> 00:34:47,940",arabic:"فَبَعْضُ مَنْ لَا دِينَ لَهُ وَلَا ضَمِيرَ عِنْدَهُ يَحْتَجُّ بِالْبَاطِلِ كَيْ يَرْفَعَ الْأَسْعَارَ كَيْفَمَا شَاءَ.",segs:[{ar:"فَبَعْضُ مَنْ لَا دِينَ لَهُ",uz:"Dini yo‘q kishilarning ba’zilari"},{ar:"وَلَا ضَمِيرَ عِنْدَهُ",uz:"va vijdoni ham yo‘q"},{ar:"يَحْتَجُّ بِالْبَاطِلِ",uz:"asossiz dalillarni ro‘kach qiladi"},{ar:"كَيْ يَرْفَعَ الْأَسْعَارَ",uz:"narxlarni ko‘tarish uchun"},{ar:"كَيْفَمَا شَاءَ",uz:"o‘zi xohlagancha"}],full_uz:"Dini ham, vijdoni ham yo‘q ayrim kishilar narxlarni o‘zi xohlagancha ko‘tarish uchun asossiz dalillarni ro‘kach qiladi.",note:"احْتَجَّ بِـ — bir narsani dalil qilib keltirmoq. كَيْ — maqsadni bildiradi va undan keyingi fe’lni nasb qiladi: يَرْفَعَ."},
{num:414,time:"00:34:50,559 --> 00:34:52,239",arabic:"مَا اسْمُكَ أَيُّهَا الْفَتَى؟",segs:[{ar:"مَا اسْمُكَ",uz:"Ismingiz nima"},{ar:"أَيُّهَا الْفَتَى؟",uz:"ey yigitcha?"}],full_uz:"Ismingiz nima, ey yigitcha?",note:"الْفَتَى — o‘g‘il bola, yosh yigit. الْفَتَاةُ esa qiz bola degani."},
{num:415,time:"00:35:03,980 --> 00:35:06,420",arabic:"إِنَّهُ ابْنُ الْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ.",segs:[{ar:"إِنَّهُ ابْنُ الْإِمَامِ",uz:"U imomning o‘g‘li"},{ar:"أَحْمَدَ بْنِ حَنْبَلٍ",uz:"Ahmad ibn Hanbalning"}],full_uz:"U imom Ahmad ibn Hanbalning o‘g‘li.",note:null},
{num:416,time:"00:35:06,420 --> 00:35:08,000",arabic:"شَيْخِ بَغْدَادَ وَإِمَامِهَا.",segs:[{ar:"شَيْخِ بَغْدَادَ",uz:"Bag‘dodning shayxi"},{ar:"وَإِمَامِهَا",uz:"va uning imomi"}],full_uz:"Bag‘dodning shayxi va imomining.",note:"Bu parcha oldingi banddagi imomni tavsiflaydi. هَا olmoshi بَغْدَادَ shahriga qaytmoqda."},
{num:417,time:"00:35:08,000 --> 00:35:11,559",arabic:"الشَّيْخُ وَالْإِمَامُ؟",segs:null,full_uz:"Shayx va imom?",note:null},
{num:418,time:"00:35:12,340 --> 00:35:13,559",arabic:"هَلْ قُلْتُ مَا يُضْحِكُ؟",segs:[{ar:"هَلْ قُلْتُ",uz:"Men aytdimmi"},{ar:"مَا يُضْحِكُ؟",uz:"kuldiradigan biror narsa?"}],full_uz:"Men kuldiradigan biror narsa aytdimmi?",note:"ضَحِكَ — kulmoq. أَضْحَكَ يُضْحِكُ — kuldirmoq. مَا يُضْحِكُ — kuldiradigan narsa."},
{num:419,time:"00:35:16,860 --> 00:35:19,299",arabic:"انْتَبِهْ لِكَلَامِكَ أَيُّهَا الرَّجُلُ.",segs:[{ar:"انْتَبِهْ لِكَلَامِكَ",uz:"Gapingizga ehtiyot bo‘ling"},{ar:"أَيُّهَا الرَّجُلُ",uz:"ey kishi"}],full_uz:"Gapingizga ehtiyot bo‘ling, ey kishi.",note:"انْتَبَهَ لِـ — ...ga e’tibor bermoq. انْتَبِهْ لِكَلَامِكَ ogohlantirish sifatida «gapirayotgan gapingizga qarang» degani."},
{num:420,time:"00:35:19,300 --> 00:35:22,140",arabic:"وَإِلَّا سَتَكُونُ الْعَوَاقِبُ وَخِيمَةً.",segs:[{ar:"وَإِلَّا",uz:"Aks holda"},{ar:"سَتَكُونُ الْعَوَاقِبُ وَخِيمَةً",uz:"oqibatlari og‘ir bo‘ladi"}],full_uz:"Aks holda, oqibatlari og‘ir bo‘ladi.",note:"عَوَاقِبُ — عَاقِبَةٌ «oqibat» so‘zining ko‘pligi. وَخِيمَةٌ — og‘ir, yomon oqibatli."},
{num:421,time:"00:35:37,300 --> 00:35:40,060",arabic:"وَلَا بُدَّ لِلْمُسْلِمِينَ مِنْ حَاكِمٍ مُسْلِمٍ.",segs:[{ar:"وَلَا بُدَّ لِلْمُسْلِمِينَ",uz:"Musulmonlar uchun zarur"},{ar:"مِنْ حَاكِمٍ مُسْلِمٍ",uz:"musulmon hukmdor bo‘lishi"}],full_uz:"Musulmonlar uchun musulmon hukmdor bo‘lishi zarur.",note:"لَا بُدَّ مِنْ — ... bo‘lishi zarur, ...siz bo‘lmaydi."},
{num:422,time:"00:35:40,060 --> 00:35:42,920",arabic:"بِالشُّرُوطِ الَّتِي حَدَّدَهَا الشَّرْعُ.",segs:[{ar:"بِالشُّرُوطِ",uz:"Shartlarga muvofiq"},{ar:"الَّتِي حَدَّدَهَا الشَّرْعُ",uz:"shariat belgilagan"}],full_uz:"Shariat belgilagan shartlarga muvofiq.",note:"الشُّرُوطُ jonsiz narsalar ko‘pligi bo‘lgani uchun unga الَّتِي va هَا muannas birlik shakllari bilan ishora qilingan."},
{num:423,time:"00:35:42,920 --> 00:35:44,620",arabic:"وَإِلَّا ضَاعَتْ حُقُوقُ النَّاسِ.",segs:[{ar:"وَإِلَّا",uz:"Aks holda"},{ar:"ضَاعَتْ حُقُوقُ النَّاسِ",uz:"odamlarning huquqlari zoye bo‘ladi"}],full_uz:"Aks holda, odamlarning huquqlari zoye bo‘ladi.",note:"ضَاعَ — yo‘qolmoq, zoye bo‘lmoq. Huquqlar haqida ularning poymol bo‘lishini ham anglatadi."},
{num:424,time:"00:35:44,620 --> 00:35:47,280",arabic:"فَإِذَا كَانَ السُّلْطَانُ صَالِحًا...",segs:[{ar:"فَإِذَا كَانَ السُّلْطَانُ",uz:"Agar hukmdor bo‘lsa"},{ar:"صَالِحًا",uz:"solih"}],full_uz:"Agar hukmdor solih bo‘lsa...",note:null},
{num:425,time:"00:35:47,280 --> 00:35:49,600",arabic:"فَهُوَ خَيْرٌ مِنْ صَالِحِي الْأُمَّةِ.",segs:[{ar:"فَهُوَ خَيْرٌ",uz:"U yaxshiroqdir"},{ar:"مِنْ صَالِحِي الْأُمَّةِ",uz:"ummatning solih kishilaridan"}],full_uz:"U ummatning solih kishilaridan yaxshiroqdir.",note:"صَالِحِي — صَالِحِينَ so‘zining izofadagi shakli. Jam’i muzakkar solim izofaga kirganda oxiridagi ن tushadi."},
{num:426,time:"00:35:49,600 --> 00:35:51,620",arabic:"وَإِذَا كَانَ فَاسِقًا...",segs:null,full_uz:"Agar fosiq bo‘lsa esa...",note:"فَاسِقٌ — itoatdan chiqqan, gunohkor kishi. كَانَ ning yashirin egasi hukmdorga qaytadi."},
{num:427,time:"00:35:51,620 --> 00:35:53,920",arabic:"فَصَالِحُو الْأُمَّةِ خَيْرٌ مِنْهُ.",segs:[{ar:"فَصَالِحُو الْأُمَّةِ",uz:"Ummatning solih kishilari"},{ar:"خَيْرٌ مِنْهُ",uz:"undan yaxshiroqdir"}],full_uz:"Ummatning solih kishilari undan yaxshiroqdir.",note:"صَالِحُو — صَالِحُونَ so‘zining izofadagi bosh kelishik shakli. Oldingi صَالِحِي shakli esa مِنْ sababli qaratqich kelishigida edi."},
{num:428,time:"00:35:53,920 --> 00:35:57,380",arabic:"وَلَا أَرَى الْخُرُوجَ عَلَيْهِ وَإِنْ كَانَ فَاسِقًا.",segs:[{ar:"وَلَا أَرَى الْخُرُوجَ عَلَيْهِ",uz:"Unga qarshi qo‘zg‘olonni ma’qul ko‘rmayman"},{ar:"وَإِنْ كَانَ فَاسِقًا",uz:"hatto u fosiq bo‘lsa ham"}],full_uz:"Hatto u fosiq bo‘lsa ham, unga qarshi qo‘zg‘olonni ma’qul ko‘rmayman.",note:"الْخُرُوجُ عَلَيْهِ — bu yerda hukmdorga qarshi qo‘zg‘olon qilish. وَإِنْ — «hatto ... bo‘lsa ham» ma’nosida."},
{num:429,time:"00:35:57,380 --> 00:36:00,540",arabic:"وَمَنْ خَرَجَ عَلَى إِمَامٍ مِنْ أَئِمَّةِ الْمُسْلِمِينَ...",segs:[{ar:"وَمَنْ خَرَجَ عَلَى إِمَامٍ",uz:"Kim bir rahbarga qarshi qo‘zg‘olsa"},{ar:"مِنْ أَئِمَّةِ الْمُسْلِمِينَ",uz:"musulmonlarning rahbarlaridan bo‘lgan"}],full_uz:"Kim musulmon rahbarlardan biriga qarshi qo‘zg‘olsa...",note:"إِمَامٌ bu yerda namoz imomi emas, jamoat rahbari ma’nosida. أَئِمَّةٌ uning ko‘pligi."},
{num:430,time:"00:36:00,540 --> 00:36:02,600",arabic:"وَقَدِ اجْتَمَعَ عَلَيْهِ النَّاسُ...",segs:[{ar:"وَقَدِ اجْتَمَعَ عَلَيْهِ",uz:"Holbuki, uning atrofida birlashgan bo‘lsa"},{ar:"النَّاسُ",uz:"odamlar"}],full_uz:"Holbuki, odamlar uning atrofida birlashgan bo‘lsa...",note:"اجْتَمَعَ عَلَيْهِ النَّاسُ — odamlar uning rahbarligini qabul qilib, atrofida birlashdilar."},
{num:431,time:"00:36:02,600 --> 00:36:04,280",arabic:"وَأَقَرُّوا لَهُ بِالْخِلَافَةِ...",segs:[{ar:"وَأَقَرُّوا لَهُ",uz:"Va uning haqqini tan olgan bo‘lsalar"},{ar:"بِالْخِلَافَةِ",uz:"xalifalikka"}],full_uz:"Va uning xalifaligini tan olgan bo‘lsalar...",note:"أَقَرَّ لَهُ بِشَيْءٍ — bir narsaning unga tegishli ekanini yoki uning haqqini tan olmoq."},
{num:432,time:"00:36:05,019 --> 00:36:07,780",arabic:"فَقَدْ شَقَّ عَصَا الْمُسْلِمِينَ.",segs:[{ar:"فَقَدْ شَقَّ",uz:"U parchalagan bo‘ladi"},{ar:"عَصَا الْمُسْلِمِينَ",uz:"musulmonlarning birligini"}],full_uz:"U musulmonlarning birligini parchalagan bo‘ladi.",note:"شَقَّ عَصَا الْمُسْلِمِينَ so‘zma-so‘z «musulmonlarning hassasini yordi». Bu ibora ularning birligini buzishni anglatadi."},
{num:433,time:"00:36:07,780 --> 00:36:10,600",arabic:"هَدَانَا اللَّهُ وَإِيَّاهُمْ إِلَى الْحَقِّ.",segs:[{ar:"هَدَانَا اللَّهُ وَإِيَّاهُمْ",uz:"Alloh bizni ham, ularni ham hidoyat qilsin"},{ar:"إِلَى الْحَقِّ",uz:"haqqa"}],full_uz:"Alloh bizni ham, ularni ham haqqa hidoyat qilsin.",note:"إِيَّاهُمْ — mustaqil tushum olmoshi, «ularni». Bu yerda نَا «bizni» olmoshiga bog‘langan."},
{num:434,time:"00:36:10,600 --> 00:36:11,740",arabic:"آمِينَ.",segs:null,full_uz:"Omin.",note:"آمِينَ — duodan keyin «Allohim, qabul qil» ma’nosida aytiladi."},
{num:435,time:"00:36:11,740 --> 00:36:16,440",arabic:"وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ.",segs:[{ar:"وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ",uz:"Alloh sayyidimiz Muhammadga salovot yo‘llasin"},{ar:"وَعَلَى آلِهِ وَصَحْبِهِ",uz:"va u zotning ahli hamda sahobalariga"},{ar:"وَسَلَّمَ",uz:"salom yo‘llasin"}],full_uz:"Alloh sayyidimiz Muhammadga, u zotning ahli va sahobalariga salovot va salom yo‘llasin.",note:"آلٌ — oila, ahl. صَحْبٌ — hamrohlar; bu yerda sahobalar nazarda tutilgan."},
{num:436,time:"00:36:16,440 --> 00:36:18,360",arabic:"وَالسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَالسَّلَامُ عَلَيْكُمْ",uz:"Sizlarga tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga tinchlik va Allohning rahmati bo‘lsin.",note:null},
{num:437,time:"00:36:19,519 --> 00:36:38,559",arabic:"بَدَأَ الْمُعْتَزِلَةُ يَنْشُرُونَ أَقْوَالًا لَا أَدْرِي مَدَى صِحَّتِهَا.",segs:[{ar:"بَدَأَ الْمُعْتَزِلَةُ يَنْشُرُونَ أَقْوَالًا",uz:"Mo‘taziliylar gaplar tarqata boshladilar"},{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"مَدَى صِحَّتِهَا",uz:"ularning qanchalik to‘g‘riligini"}],full_uz:"Mo‘taziliylar qandaydir gaplar tarqata boshladilar. Ularning qanchalik to‘g‘riligini bilmayman.",note:"بَدَأَ يَفْعَلُ — bir ishni qila boshladi. مَدَى صِحَّتِهَا — uning to‘g‘rilik darajasi, qanchalik to‘g‘riligi."},
{num:438,time:"00:36:38,559 --> 00:36:42,440",arabic:"وَلَكِنَّهَا إِنْ صَدَقَتْ فَتِلْكَ هِيَ الطَّامَّةُ.",segs:[{ar:"وَلَكِنَّهَا إِنْ صَدَقَتْ",uz:"Ammo ular rost bo‘lsa"},{ar:"فَتِلْكَ هِيَ الطَّامَّةُ",uz:"ana o‘sha katta falokatdir"}],full_uz:"Ammo ular rost bo‘lsa, bu katta falokatdir.",note:"الطَّامَّةُ — juda katta balo, boshqa kulfatlardan ham og‘ir falokat."},
{num:439,time:"00:36:42,440 --> 00:36:45,280",arabic:"هَدَى اللَّهُ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ.",segs:[{ar:"هَدَى اللَّهُ",uz:"Alloh hidoyat qilsin"},{ar:"أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ",uz:"mo‘minlar amiri Ma’munni"}],full_uz:"Alloh mo‘minlar amiri Ma’munni hidoyat qilsin.",note:"هَدَى اللَّهُ shaklan o‘tgan zamonda bo‘lsa ham, bu yerda duo bildiradi."},
{num:440,time:"00:36:45,280 --> 00:36:49,760",arabic:"فَقَدْ سَمَحَ لِكُلِّ مُبْتَدِعٍ أَنْ يَتَكَلَّمَ فِي دِينِ اللَّهِ بِهَوَاهُ.",segs:[{ar:"فَقَدْ سَمَحَ لِكُلِّ مُبْتَدِعٍ",uz:"U har bir bid’atchiga ruxsat berdi"},{ar:"أَنْ يَتَكَلَّمَ فِي دِينِ اللَّهِ",uz:"Allohning dini haqida gapirishga"},{ar:"بِهَوَاهُ",uz:"o‘z xohishiga ko‘ra"}],full_uz:"U har bir bid’atchiga Allohning dini haqida o‘z xohishiga ko‘ra gapirishga ruxsat berdi.",note:"سَمَحَ لَهُ أَنْ يَفْعَلَ — unga bir ishni qilishga ruxsat bermoq. هَوًى — xohish, mayl; بِهَوَاهُ — o‘z xohishiga ergashib."},
{num:441,time:"00:36:49,760 --> 00:36:53,860",arabic:"أَسْأَلُ اللَّهَ لَنَا وَلَهُ الْعَافِيَةَ.",segs:[{ar:"أَسْأَلُ اللَّهَ",uz:"Allohdan so‘rayman"},{ar:"لَنَا وَلَهُ الْعَافِيَةَ",uz:"bizga ham, unga ham ofiyat"}],full_uz:"Allohdan bizga ham, unga ham ofiyat so‘rayman.",note:"الْعَافِيَةُ — salomatlik, balo va yomonliklardan omonlik."},
{num:442,time:"00:36:55,680 --> 00:36:59,740",arabic:"لِمَاذَا لَا تَطْلُبُ الدُّخُولَ عَلَى الْمَأْمُونِ وَوُزَرَائِهِ وَأُمَرَائِهِ؟",segs:[{ar:"لِمَاذَا لَا تَطْلُبُ الدُّخُولَ",uz:"Nega huzuriga kirishni so‘ramaysiz"},{ar:"عَلَى الْمَأْمُونِ",uz:"Ma’munning"},{ar:"وَوُزَرَائِهِ وَأُمَرَائِهِ؟",uz:"va uning vazirlari hamda amirlarining?"}],full_uz:"Nega Ma’mun, uning vazirlari va amirlari huzuriga kirishni so‘ramaysiz?",note:"الدُّخُولُ عَلَى فُلَانٍ — birovning huzuriga kirish. وُزَرَاءُ — وَزِيرٌ ning, أُمَرَاءُ esa أَمِيرٌ ning ko‘pligi."},
{num:443,time:"00:36:59,740 --> 00:37:01,300",arabic:"وَتُسْدِي لَهُمْ نُصْحًا؟",segs:null,full_uz:"Va ularga nasihat qilmaysiz?",note:"أَسْدَى لَهُ نُصْحًا — unga nasihat bermoq."},
{num:444,time:"00:37:01,300 --> 00:37:02,500",arabic:"لَا يَصْلُحُ.",segs:null,full_uz:"Bu to‘g‘ri kelmaydi.",note:"صَلَحَ يَصْلُحُ — yaroqli, munosib bo‘lmoq. لَا يَصْلُحُ vaziyatga qarab «yaramaydi», «to‘g‘ri kelmaydi» deb tarjima qilinadi."},
{num:445,time:"00:37:02,500 --> 00:37:05,080",arabic:"الدُّنُوُّ مِنْهُمْ فِتْنَةٌ.",segs:[{ar:"الدُّنُوُّ مِنْهُمْ",uz:"Ularga yaqinlashish"},{ar:"فِتْنَةٌ",uz:"fitnadir"}],full_uz:"Ularga yaqinlashish fitnadir.",note:"الدُّنُوُّ — دَنَا يَدْنُو «yaqinlashmoq» fe’lining masdari. فِتْنَةٌ bu yerda kishini yo‘ldan og‘dirishi mumkin bo‘lgan sinovni anglatadi."},
{num:446,time:"00:37:05,080 --> 00:37:07,540",arabic:"وَالْجُلُوسُ مَعَهُمْ فِتْنَةٌ.",segs:[{ar:"وَالْجُلُوسُ مَعَهُمْ",uz:"Ular bilan o‘tirish ham"},{ar:"فِتْنَةٌ",uz:"fitnadir"}],full_uz:"Ular bilan o‘tirish ham fitnadir.",note:null},
{num:447,time:"00:37:07,540 --> 00:37:10,180",arabic:"وَنَحْنُ مُتَبَاعِدُونَ مِنْهُمْ لَا نَسْلَمُ.",segs:[{ar:"وَنَحْنُ مُتَبَاعِدُونَ مِنْهُمْ",uz:"Ulardan uzoq turganimizda ham"},{ar:"لَا نَسْلَمُ",uz:"omon qolmayapmiz"}],full_uz:"Ulardan uzoq turganimizda ham zararlaridan omon qolmayapmiz.",note:"نَسْلَمُ — سَلِمَ «omon qolmoq» fe’lidan. Uni نُسَلِّمُ «salom beramiz» shakli bilan adashtirmang."},
{num:448,time:"00:37:10,180 --> 00:37:12,580",arabic:"فَكَيْفَ لَوْ قَرُبْنَا مِنْهُمْ؟",segs:[{ar:"فَكَيْفَ",uz:"Unda qanday bo‘larkin"},{ar:"لَوْ قَرُبْنَا مِنْهُمْ؟",uz:"agar ularga yaqinlashsak?"}],full_uz:"Ularga yaqinlashsak, unda qanday bo‘larkin?",note:null},
{num:449,time:"00:37:12,580 --> 00:37:14,820",arabic:"وَمَاذَا تَرَى يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"وَمَاذَا تَرَى",uz:"Unda nimani ma’qul ko‘rasiz"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"ey Abu Abdulloh?"}],full_uz:"Unda nimani ma’qul ko‘rasiz, ey Abu Abdulloh?",note:"تَرَى bu yerda «ko‘rasiz» emas, «qanday fikrdasiz, nimani ma’qul ko‘rasiz» ma’nosida."},
{num:450,time:"00:37:19,000 --> 00:37:22,620",arabic:"عَلَيْكَ نَفْسَكَ.",segs:null,full_uz:"Avvalo o‘zingiz bilan shug‘ullaning.",note:"عَلَيْكَ bu yerda buyruq ma’nosidagi ism fe’l. نَفْسَكَ uning to‘ldiruvchisi bo‘lib, tushum kelishigida kelgan."},
{num:451,time:"00:37:22,620 --> 00:37:24,720",arabic:"وَادْعُ مَنْ حَوْلَكَ.",segs:null,full_uz:"Atrofingizdagilarni da’vat qiling.",note:"ادْعُ — دَعَا يَدْعُو fe’lining buyruq shakli; oxiridagi و tushgan. Bu yerda haqqa chaqirish nazarda tutilgan."},
{num:452,time:"00:37:24,720 --> 00:37:27,000",arabic:"وَاهْجُرْ صَاحِبَ الْبِدْعَةِ.",segs:null,full_uz:"Bid’at egasidan uzoqlashing.",note:"هَجَرَ — tark etmoq, aloqani uzmoq. اهْجُرْ — shu fe’lning buyruq shakli."},
{num:453,time:"00:37:27,000 --> 00:37:29,800",arabic:"وَتَمَسَّكْ بِالْقُرْآنِ وَالسُّنَّةِ.",segs:[{ar:"وَتَمَسَّكْ",uz:"Va mahkam tuting"},{ar:"بِالْقُرْآنِ وَالسُّنَّةِ",uz:"Qur’on va sunnatni"}],full_uz:"Qur’on va sunnatni mahkam tuting.",note:"تَمَسَّكَ بِـ — mahkam ushlamoq; qarash yoki yo‘l haqida «qat’iy amal qilmoq» ma’nosida."},
{num:454,time:"00:37:29,800 --> 00:37:32,740",arabic:"وَدَعْ مَا سِوَاهُمَا، فَفِيهِمَا النَّجَاةُ.",segs:[{ar:"وَدَعْ مَا سِوَاهُمَا",uz:"Ikkalasidan boshqa narsalarni tark eting"},{ar:"فَفِيهِمَا النَّجَاةُ",uz:"chunki najot shu ikkidadir"}],full_uz:"Ikkalasidan boshqa narsalarni tark eting, chunki najot shu ikkidadir.",note:"دَعْ — وَدَعَ «tark etmoq» fe’lining buyrug‘i. Uni ادْعُ «chaqir, duo qil» bilan farqlang. هُمَا — ikkilik olmoshi."},
{num:455,time:"00:37:32,740 --> 00:37:35,580",arabic:"قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:",segs:[{ar:"قَالَ رَسُولُ اللَّهِ",uz:"Allohning Rasuli aytdilar"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Allohning Rasuli, sollallohu alayhi vasallam, aytdilar:",note:null},
{num:456,time:"00:37:37,400 --> 00:37:40,800",arabic:"إِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا.",segs:[{ar:"إِنَّهُ مَنْ يَعِشْ مِنْكُمْ",uz:"Albatta, sizlardan kim yashasa"},{ar:"فَسَيَرَى اخْتِلَافًا كَثِيرًا",uz:"ko‘p ixtiloflarni ko‘radi"}],full_uz:"Albatta, sizlardan kim yashasa, ko‘p ixtiloflarni ko‘radi.",note:"يَعِشْ — يَعِيشُ fe’lining jazm shakli. Shart bildiruvchi مَنْ sababli fe’l jazm bo‘lib, o‘rtadagi ي tushgan."},
{num:457,time:"00:37:40,800 --> 00:37:42,840",arabic:"فَعَلَيْكُمْ بِسُنَّتِي.",segs:null,full_uz:"Shunday ekan, mening sunnatimni mahkam tutinglar.",note:"عَلَيْكُمْ بِـ — ko‘plikka qaratilgan «...ni mahkam tutinglar, ...ga amal qilinglar» buyrug‘i."},
{num:458,time:"00:37:42,840 --> 00:37:46,120",arabic:"وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ بَعْدِي.",segs:[{ar:"وَسُنَّةِ الْخُلَفَاءِ",uz:"Va xalifalarning sunnatini"},{ar:"الرَّاشِدِينَ الْمَهْدِيِّينَ",uz:"to‘g‘ri yo‘ldagi, hidoyat topgan"},{ar:"بَعْدِي",uz:"mendan keyingi"}],full_uz:"Va mendan keyingi to‘g‘ri yo‘ldagi, hidoyat topgan xalifalarning sunnatini.",note:"الرَّاشِدِينَ — to‘g‘ri yo‘ldagilar. الْمَهْدِيِّينَ — hidoyat qilinganlar. Ikkalasi ham الْخُلَفَاءِ so‘zini tavsiflamoqda."},
{num:459,time:"00:37:46,120 --> 00:37:48,660",arabic:"فَعَضُّوا عَلَيْهَا بِالنَّوَاجِذِ.",segs:[{ar:"فَعَضُّوا عَلَيْهَا",uz:"Uni mahkam tishlanglar"},{ar:"بِالنَّوَاجِذِ",uz:"oziq tishlar bilan"}],full_uz:"Uni oziq tishlaringiz bilan mahkam tishlanglar.",note:"Bu ibora ko‘chma ma’noda juda mahkam tutish, aslo qo‘yib yubormaslikni bildiradi. النَّوَاجِذُ — orqa oziq tishlar."},
{num:460,time:"00:37:48,660 --> 00:37:51,079",arabic:"وَإِيَّاكُمْ مُحْدَثَاتِ الْأُمُورِ.",segs:[{ar:"وَإِيَّاكُمْ",uz:"Va saqlaninglar"},{ar:"مُحْدَثَاتِ الْأُمُورِ",uz:"yangi kiritilgan ishlardan"}],full_uz:"Yangi kiritilgan ishlardan saqlaninglar.",note:"إِيَّاكُمْ — ogohlantirish va qaytarish tuzilmasi. مُحْدَثَاتٌ — keyin paydo qilingan narsalar; bu yerda diniy amallarga kiritilgan yangiliklar nazarda tutilgan."},
{num:461,time:"00:37:51,079 --> 00:37:53,600",arabic:"فَإِنَّ كُلَّ مُحْدَثَةٍ ضَلَالَةٌ.",segs:[{ar:"فَإِنَّ كُلَّ مُحْدَثَةٍ",uz:"Chunki har bir yangi kiritilgan ish"},{ar:"ضَلَالَةٌ",uz:"zalolatdir"}],full_uz:"Chunki har bir yangi kiritilgan ish zalolatdir.",note:"كُلَّ — إِنَّ ning ismi, ضَلَالَةٌ esa uning xabari. مُحْدَثَةٍ izofa sababli qaratqich kelishigida kelgan."},
{num:462,time:"00:38:12,840 --> 00:38:24,880",arabic:"قُلْتُ لَكَ غَيْرَ مَرَّةٍ يَا وَلَدُ أَنْ تَلِينَ فِي كَلَامِكَ مَعَ السَّيِّدِ الْمُحْتَسِبِ.",segs:[{ar:"قُلْتُ لَكَ غَيْرَ مَرَّةٍ",uz:"Sizga bir necha bor aytdim"},{ar:"يَا وَلَدُ",uz:"ey bola"},{ar:"أَنْ تَلِينَ فِي كَلَامِكَ",uz:"gapingizda muloyim bo‘lishingizni"},{ar:"مَعَ السَّيِّدِ الْمُحْتَسِبِ",uz:"muhtasib janoblari bilan"}],full_uz:"Ey bola, muhtasib janoblari bilan muloyim gaplashishingizni sizga bir necha bor aytdim.",note:"غَيْرَ مَرَّةٍ — bir martadan ko‘p, bir necha bor. لَانَ يَلِينُ — yumshoq, muloyim bo‘lmoq."},
{num:463,time:"00:38:24,880 --> 00:38:27,320",arabic:"أَلَا تَدْرِي مَا قَدْ يَصْنَعُ بِنَا؟",segs:[{ar:"أَلَا تَدْرِي",uz:"Bilmaysizmi"},{ar:"مَا قَدْ يَصْنَعُ بِنَا؟",uz:"u bizga nima qilishi mumkinligini?"}],full_uz:"U bizga nima qilishi mumkinligini bilmaysizmi?",note:"قَدْ hozirgi-kelasi zamon fe’li bilan bu yerda ehtimolni bildiradi: قَدْ يَصْنَعُ — qilishi mumkin."},
{num:464,time:"00:38:27,320 --> 00:38:28,960",arabic:"إِنَّمَا أُعَامِلُهُ بِمَا يَسْتَحِقُّ.",segs:[{ar:"إِنَّمَا أُعَامِلُهُ",uz:"Men unga faqat muomala qilyapman"},{ar:"بِمَا يَسْتَحِقُّ",uz:"o‘zi loyiq bo‘lgan tarzda"}],full_uz:"Men unga faqat o‘zi loyiq bo‘lgan tarzda muomala qilyapman.",note:"إِنَّمَا — fikrni cheklab, «faqat» ma’nosini beradi. اسْتَحَقَّ — loyiq bo‘lmoq, haq qilmoq."},
{num:465,time:"00:38:28,960 --> 00:38:31,320",arabic:"فَهَؤُلَاءِ سُيُوفٌ عَلَى رِقَابِنَا بِلَا فَارِسٍ.",segs:[{ar:"فَهَؤُلَاءِ سُيُوفٌ",uz:"Axir bular qilichlardir"},{ar:"عَلَى رِقَابِنَا",uz:"bo‘yinlarimiz ustidagi"},{ar:"بِلَا فَارِسٍ",uz:"chavandozsiz"}],full_uz:"Axir bular bo‘yinlarimiz ustidagi chavandozsiz qilichlardir.",note:"رِقَابٌ — رَقَبَةٌ «bo‘yin» so‘zining ko‘pligi. Bu yerda qilich obrazi doimiy tahdidni ifodalaydi."},
{num:466,time:"00:38:31,320 --> 00:38:32,600",arabic:"خَفْ عَلَى نَفْسِكَ يَا عُمَرُ.",segs:[{ar:"خَفْ عَلَى نَفْسِكَ",uz:"O‘zingizni o‘ylab, ehtiyot bo‘ling"},{ar:"يَا عُمَرُ",uz:"ey Umar"}],full_uz:"O‘zingizni o‘ylab, ehtiyot bo‘ling, ey Umar.",note:"خَافَ عَلَى — biror kishiga zarar yetishidan xavotir olmoq. خَافَ مِنْ esa biror narsadan qo‘rqishni bildiradi."},
{num:467,time:"00:38:32,600 --> 00:38:35,680",arabic:"فَإِنَّكَ تَكَادُ أَنْ تُودِيَ بِنَفْسِكَ وَبِنَا إِلَى التَّهْلُكَةِ.",segs:[{ar:"فَإِنَّكَ تَكَادُ",uz:"Axir siz oz qoldingiz"},{ar:"أَنْ تُودِيَ بِنَفْسِكَ وَبِنَا",uz:"o‘zingizni ham, bizni ham olib borishga"},{ar:"إِلَى التَّهْلُكَةِ",uz:"halokatga"}],full_uz:"Axir o‘zingizni ham, bizni ham halokatga olib borishingizga oz qoldi.",note:"كَادَ — bir ish sodir bo‘lishiga oz qolganini bildiradi. أَوْدَى بِهِ — uni halok qilmoq yoki halokatga olib bormoq."},
{num:468,time:"00:38:35,680 --> 00:38:38,680",arabic:"قُلْ لِي: مَاذَا تَكْرَهُ فِي الدُّنْيَا؟ أَقُلْ لَكَ: أَنْ أَرَى وَجْهَ مُعْتَزِلِيٍّ.",segs:[{ar:"قُلْ لِي",uz:"Mendan so‘rang"},{ar:"مَاذَا تَكْرَهُ فِي الدُّنْيَا؟",uz:"Dunyoda nimani yomon ko‘rasiz?"},{ar:"أَقُلْ لَكَ",uz:"Sizga aytaman"},{ar:"أَنْ أَرَى وَجْهَ مُعْتَزِلِيٍّ",uz:"mo‘taziliyning yuzini ko‘rishni"}],full_uz:"Mendan «Dunyoda nimani yomon ko‘rasiz?» deb so‘rang. Sizga «Mo‘taziliyning yuzini ko‘rishni» deb aytaman.",note:"أَقُلْ — أَقُولُ fe’lining jazm shakli; oldingi buyruqning natijasini bildiradi: «so‘rang, aytaman»."},
{num:469,time:"00:38:38,680 --> 00:38:41,420",arabic:"إِذَنْ لَا تَنْظُرْ فِي وَجْهِهِ.",segs:[{ar:"إِذَنْ لَا تَنْظُرْ",uz:"Unda qaramang"},{ar:"فِي وَجْهِهِ",uz:"uning yuziga"}],full_uz:"Unda uning yuziga qaramang.",note:"لَا تَنْظُرْ — taqiq shakli. لَا yuklamasi sababli fe’lning oxiri sukunli kelgan."},
{num:470,time:"00:38:41,420 --> 00:38:46,579",arabic:"لَوْ رَأَيْتَهُ كَيْفَ كَانَ يُخَاطِبُ ابْنَ الْإِمَامِ لَمَا قُلْتَ هَذَا يَا أَبِي.",segs:[{ar:"لَوْ رَأَيْتَهُ",uz:"Agar uni ko‘rganingizda"},{ar:"كَيْفَ كَانَ يُخَاطِبُ ابْنَ الْإِمَامِ",uz:"imomning o‘g‘liga qanday gapirayotganini"},{ar:"لَمَا قُلْتَ هَذَا",uz:"bunday demagan bo‘lardingiz"},{ar:"يَا أَبِي",uz:"ey otajon"}],full_uz:"Uning imomning o‘g‘liga qanday gapirayotganini ko‘rganingizda, bunday demagan bo‘lardingiz, otajon.",note:"لَوْ ... لَمَا ... — «agar ...ganida, ...magan bo‘lardi». Bu yerda لَمَا tarkibidagi مَا inkor bildiradi."},
{num:471,time:"00:38:46,579 --> 00:38:51,480",arabic:"يَا عُمَرُ، تَعْرِفُ أَنَّ الْمُعْتَزِلَةَ لَا يُطِيقُونَ فُقَهَاءَ بَغْدَادَ وَأَئِمَّتَهَا.",segs:[{ar:"يَا عُمَرُ، تَعْرِفُ",uz:"Ey Umar, bilasiz"},{ar:"أَنَّ الْمُعْتَزِلَةَ لَا يُطِيقُونَ",uz:"mo‘taziliylar toqat qilolmasligini"},{ar:"فُقَهَاءَ بَغْدَادَ وَأَئِمَّتَهَا",uz:"Bag‘dod faqihlari va imomlariga"}],full_uz:"Ey Umar, mo‘taziliylar Bag‘dod faqihlari va imomlariga toqat qilolmasligini bilasiz.",note:"أَطَاقَ يُطِيقُ — kuchi yetmoq, chiday olmoq. لَا يُطِيقُ فُلَانًا — birovni ko‘rishga ham toqat qilolmaslik."},
{num:472,time:"00:38:51,480 --> 00:38:54,099",arabic:"وَيَتَرَقَّبُونَ يَوْمَ الْفَتْكِ وَالْخَلَاصِ مِنْهُمْ.",segs:[{ar:"وَيَتَرَقَّبُونَ",uz:"Va kutib turibdilar"},{ar:"يَوْمَ الْفَتْكِ وَالْخَلَاصِ مِنْهُمْ",uz:"ularni qirib, ulardan qutuladigan kunni"}],full_uz:"Ularni qirib, ulardan qutuladigan kunni kutib turibdilar.",note:"تَرَقَّبَ — diqqat bilan kutmoq, kuzatib turmoq. الْفَتْكُ — shafqatsizlarcha o‘ldirish, qirish."},
{num:473,time:"00:38:54,099 --> 00:38:56,500",arabic:"بَلْ قُلْ: لَا يُطِيقُونَ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ.",segs:[{ar:"بَلْ قُلْ",uz:"Balki, shunday deng"},{ar:"لَا يُطِيقُونَ أَهْلَ السُّنَّةِ وَالْجَمَاعَةِ",uz:"ular ahli sunna val jamoaga toqat qilolmaydilar"}],full_uz:"Balki, ular ahli sunna val jamoaga toqat qilolmaydilar, deng.",note:"بَلْ — oldingi fikrni tuzatish yoki undan kengroq fikrga o‘tish uchun ishlatiladi."},
{num:474,time:"00:38:56,500 --> 00:38:59,320",arabic:"وَمَا جَدْوَى الْحَدِيثِ عَنْهُمْ؟",segs:[{ar:"وَمَا جَدْوَى",uz:"Nima foydasi bor"},{ar:"الْحَدِيثِ عَنْهُمْ؟",uz:"ular haqida gapirishning?"}],full_uz:"Ular haqida gapirishning nima foydasi bor?",note:"جَدْوَى — foyda, naf. مَا جَدْوَى ...؟ — «...ning nima foydasi bor?»."},
{num:475,time:"00:38:59,320 --> 00:39:03,200",arabic:"اسْمَعْ يَا وَلَدُ، نَحْنُ لَسْنَا أَهْلًا لِاسْتِعْدَاءِ الْمُعْتَزِلَةِ.",segs:[{ar:"اسْمَعْ يَا وَلَدُ",uz:"Eshiting, ey bola"},{ar:"نَحْنُ لَسْنَا أَهْلًا",uz:"Biz bunga qodir emasmiz"},{ar:"لِاسْتِعْدَاءِ الْمُعْتَزِلَةِ",uz:"mo‘taziliylarni o‘zimizga dushman qilishga"}],full_uz:"Eshiting, ey bola, mo‘taziliylarni o‘zimizga dushman qilishga qurbimiz yetmaydi.",note:"اسْتِعْدَاءٌ — kimnidir o‘ziga dushman qilib olish, adovatini qo‘zg‘atish."},
{num:476,time:"00:39:03,200 --> 00:39:06,320",arabic:"الْوَلَدُ الَّذِي تَتَحَدَّثُ عَنْهُ صَارَ رَجُلًا يَا أَبِي.",segs:[{ar:"الْوَلَدُ الَّذِي تَتَحَدَّثُ عَنْهُ",uz:"Siz gapirayotgan bola"},{ar:"صَارَ رَجُلًا",uz:"erkak bo‘lib yetishdi"},{ar:"يَا أَبِي",uz:"ey otajon"}],full_uz:"Siz gapirayotgan bola erkak bo‘lib yetishdi, otajon.",note:"صَارَ — bir holatdan boshqa holatga o‘tishni bildiradi. Uning xabari tushum kelishigida keladi: رَجُلًا."},
{num:477,time:"00:39:06,320 --> 00:39:11,280",arabic:"يَعْلَمُ مَا يَجْرِي حَوْلَهُ، وَلَنْ يَكُونَ يَوْمًا ظَهِيرًا لِمَنْ يَتَطَاوَلُ عَلَى الدِّينِ وَفُقَهَائِهِ.",segs:[{ar:"يَعْلَمُ مَا يَجْرِي حَوْلَهُ",uz:"Atrofida nima bo‘layotganini biladi"},{ar:"وَلَنْ يَكُونَ يَوْمًا ظَهِيرًا",uz:"va hech qachon yordamchi bo‘lmaydi"},{ar:"لِمَنْ يَتَطَاوَلُ عَلَى الدِّينِ وَفُقَهَائِهِ",uz:"din va uning faqihlariga til tekkizadigan kishiga"}],full_uz:"U atrofida nima bo‘layotganini biladi. Din va uning faqihlariga til tekkizadigan kishiga hech qachon yordamchi bo‘lmaydi.",note:"ظَهِيرٌ — yordamchi, qo‘llab-quvvatlovchi. تَطَاوَلَ عَلَى — haddidan oshib tegmoq, hurmatsizlik qilmoq."},
{num:478,time:"00:39:11,280 --> 00:39:17,300",arabic:"يَا وَلَدِي، يَقْصِدُ أَبُوكَ أَنَّ عُلَمَاءَ بَغْدَادَ قَادِرُونَ عَلَى التَّصَدِّي لِهَؤُلَاءِ الْقَوْمِ.",segs:[{ar:"يَا وَلَدِي",uz:"Ey bolam"},{ar:"يَقْصِدُ أَبُوكَ",uz:"otangiz nazarda tutyapti"},{ar:"أَنَّ عُلَمَاءَ بَغْدَادَ قَادِرُونَ",uz:"Bag‘dod olimlari qodir ekanini"},{ar:"عَلَى التَّصَدِّي لِهَؤُلَاءِ الْقَوْمِ",uz:"bu kishilarga qarshi turishga"}],full_uz:"Ey bolam, otangiz Bag‘dod olimlari bu kishilarga qarshi turishga qodir ekanini nazarda tutyapti.",note:"التَّصَدِّي لِـ — biror kishiga yoki hodisaga qarshi turish. قَادِرٌ عَلَى — ...ga qodir."},
{num:479,time:"00:39:17,300 --> 00:39:21,180",arabic:"أَمَّا نَحْنُ الْمَسَاكِينُ فَقَدْ نَضِيعُ تَحْتَ سَنَابِكِ الْفَرِيقَيْنِ.",segs:[{ar:"أَمَّا نَحْنُ الْمَسَاكِينُ",uz:"Biz bechoralarga kelsak"},{ar:"فَقَدْ نَضِيعُ",uz:"halok bo‘lib ketishimiz mumkin"},{ar:"تَحْتَ سَنَابِكِ الْفَرِيقَيْنِ",uz:"ikki tomonning otlari tuyoqlari ostida"}],full_uz:"Biz bechoralar esa ikki tomonning otlari tuyoqlari ostida halok bo‘lib ketishimiz mumkin.",note:"سَنَابِكُ — سُنْبُكٌ «tuyoqning old qismi» so‘zining ko‘pligi. Bu yerda ikki tomon kurashi orasida ezilib qolish obrazli ifodalangan."},
{num:480,time:"00:39:21,180 --> 00:39:24,519",arabic:"سُكُوتُنَا هُوَ مَا جَرَّأَ أَهْلَ الضَّلَالِ عَلَى النَّيْلِ مِنْ عُلَمَائِنَا.",segs:[{ar:"سُكُوتُنَا هُوَ مَا جَرَّأَ أَهْلَ الضَّلَالِ",uz:"Bizning sukutimiz zalolat ahliga jur’at berdi"},{ar:"عَلَى النَّيْلِ مِنْ عُلَمَائِنَا",uz:"olimlarimizga zarar yetkazishga"}],full_uz:"Zalolat ahliga olimlarimizga zarar yetkazish jur’atini bergan narsa bizning sukutimizdir.",note:"جَرَّأَهُ عَلَى — unga bir ishga jur’at bermoq. نَالَ مِنْ فُلَانٍ — birovga zarar yetkazmoq yoki uning sha’niga tegmoq."},
{num:481,time:"00:39:24,519 --> 00:39:29,680",arabic:"إِنْ لَمْ نَتَصَدَّ لِهَؤُلَاءِ فَالْخَطَرُ قَادِمٌ لَا مَحَالَةَ، وَسَيُغْرِقُ الْجَمِيعَ الطُّوفَانُ.",segs:[{ar:"إِنْ لَمْ نَتَصَدَّ لِهَؤُلَاءِ",uz:"Agar bularga qarshi turmasak"},{ar:"فَالْخَطَرُ قَادِمٌ لَا مَحَالَةَ",uz:"xavf muqarrar keladi"},{ar:"وَسَيُغْرِقُ الْجَمِيعَ الطُّوفَانُ",uz:"va to‘fon hammani g‘arq qiladi"}],full_uz:"Agar bularga qarshi turmasak, xavf muqarrar keladi va to‘fon hammani g‘arq qiladi.",note:"لَا مَحَالَةَ — muqarrar, shubhasiz. Oxirgi gapda الطُّوفَانُ ega, الْجَمِيعَ esa undan oldin kelgan to‘ldiruvchi."},
{num:482,time:"00:39:29,680 --> 00:39:34,700",arabic:"جِدْ لِابْنِكَ حَلًّا يَا أَبِي قَبْلَ أَنْ يُودِيَ بِنَفْسِهِ وَبِنَا إِلَى التَّهْلُكَةِ.",segs:[{ar:"جِدْ لِابْنِكَ حَلًّا",uz:"O‘g‘lingiz uchun bir yechim toping"},{ar:"يَا أَبِي",uz:"ey otajon"},{ar:"قَبْلَ أَنْ يُودِيَ بِنَفْسِهِ وَبِنَا",uz:"u o‘zini ham, bizni ham olib bormasidan oldin"},{ar:"إِلَى التَّهْلُكَةِ",uz:"halokatga"}],full_uz:"Otajon, o‘g‘lingiz o‘zini ham, bizni ham halokatga olib bormasidan oldin bir yechim toping.",note:"جِدْ — وَجَدَ يَجِدُ «topmoq» fe’lining buyrug‘i. Buyruqda o‘zakning boshidagi و tushadi."},
{num:483,time:"00:39:34,700 --> 00:39:39,920",arabic:"لَا بُدَّ أَنْ أَجِدَ لَهُ حَلًّا، فَلَسْنَا بِحَاجَةٍ إِلَى مَزِيدٍ مِنَ الْمَشَاكِلِ.",segs:[{ar:"لَا بُدَّ أَنْ أَجِدَ لَهُ حَلًّا",uz:"Unga bir yechim topishim kerak"},{ar:"فَلَسْنَا بِحَاجَةٍ",uz:"chunki biz muhtoj emasmiz"},{ar:"إِلَى مَزِيدٍ مِنَ الْمَشَاكِلِ",uz:"yana ko‘proq muammolarga"}],full_uz:"Unga bir yechim topishim kerak. Bizga yana ko‘proq muammo kerak emas.",note:"بِحَاجَةٍ إِلَى — bir narsaga ehtiyoji bor. مَزِيدٌ مِنْ — yana ko‘proq, qo‘shimcha."},
{num:484,time:"00:39:39,920 --> 00:39:42,480",arabic:"مَاذَا سَتَفْعَلُ يَا عَامِرُ؟",segs:[{ar:"مَاذَا سَتَفْعَلُ",uz:"Nima qilasiz"},{ar:"يَا عَامِرُ؟",uz:"ey Omir?"}],full_uz:"Nima qilasiz, ey Omir?",note:null},
{num:485,time:"00:39:42,480 --> 00:39:44,880",arabic:"سَأَمْلَأُ عَلَيْهِ يَوْمَهُ وَلَيْلَهُ.",segs:[{ar:"سَأَمْلَأُ عَلَيْهِ",uz:"Uning vaqtini to‘ldiraman"},{ar:"يَوْمَهُ وَلَيْلَهُ",uz:"kunduzi ham, kechasi ham"}],full_uz:"Uning kecha-kunduzini band qilib qo‘yaman.",note:"مَلَأَ عَلَيْهِ يَوْمَهُ — kunini mashg‘ulotlar bilan to‘ldirib, bo‘sh vaqt qoldirmaslik."},
{num:486,time:"00:39:44,880 --> 00:39:46,760",arabic:"لَا يَسْتَطِيعُ فَكَاكًا.",segs:null,full_uz:"Qutulib keta olmaydi.",note:"فَكَاكٌ — qutulish, ozod bo‘lish."},
{num:487,time:"00:39:46,760 --> 00:39:48,480",arabic:"سَأُزَوِّجُهُ.",segs:null,full_uz:"Uni uylantiraman.",note:"أُزَوِّجُهُ — uni uylantiraman. أَتَزَوَّجُ esa «o‘zim uylanaman» degani."},
{num:488,time:"00:39:48,480 --> 00:39:51,440",arabic:"وَكَيْفَ سَيَكُونُ زَوَاجُهُ حَلًّا؟",segs:[{ar:"وَكَيْفَ سَيَكُونُ زَوَاجُهُ",uz:"Uning uylanishi qanday qilib bo‘ladi"},{ar:"حَلًّا؟",uz:"yechim?"}],full_uz:"Uning uylanishi qanday qilib yechim bo‘ladi?",note:null},
{num:489,time:"00:39:51,440 --> 00:39:53,260",arabic:"اسْمَعْ يَا وَلَدُ، إِنَّهُ إِنْ تَزَوَّجَ...",segs:[{ar:"اسْمَعْ يَا وَلَدُ",uz:"Eshiting, ey bola"},{ar:"إِنَّهُ إِنْ تَزَوَّجَ",uz:"u uylansa"}],full_uz:"Eshiting, ey bola, u uylansa...",note:"إِنَّهُ dagi إِنَّ ta’kidni, undan keyingi إِنْ esa shartni bildiradi."},
{num:490,time:"00:39:53,260 --> 00:39:55,579",arabic:"سَيَصُبُّ جَامَ غَضَبِهِ عَلَى زَوْجِهِ.",segs:[{ar:"سَيَصُبُّ جَامَ غَضَبِهِ",uz:"Butun g‘azabini sochadi"},{ar:"عَلَى زَوْجِهِ",uz:"xotiniga"}],full_uz:"Butun g‘azabini xotiniga sochadi.",note:"صَبَّ جَامَ غَضَبِهِ عَلَى — bor g‘azabini birovga sochmoq. زَوْجٌ so‘zi matnga qarab erni ham, xotinni ham anglatishi mumkin."},
{num:491,time:"00:39:55,579 --> 00:39:58,639",arabic:"فَيَكُفُّ عَنِ التَّعَرُّضِ لِلْمَجُوسِ.",segs:[{ar:"فَيَكُفُّ",uz:"Shunda to‘xtaydi"},{ar:"عَنِ التَّعَرُّضِ لِلْمَجُوسِ",uz:"majusiylarga tegajog‘lik qilishdan"}],full_uz:"Shunda majusiylarga tegajog‘lik qilishni bas qiladi.",note:"كَفَّ عَنْ — bir ishdan tiyilmoq, uni to‘xtatmoq. تَعَرَّضَ لِفُلَانٍ bu yerda birovga tegishmoq ma’nosida."},
{num:492,time:"00:39:58,639 --> 00:40:01,220",arabic:"تَقْصِدُ الْمُعْتَزِلَةَ؟",segs:null,full_uz:"Mo‘taziliylarni nazarda tutyapsizmi?",note:null},
{num:493,time:"00:40:01,220 --> 00:40:02,820",arabic:"أَيًّا كَانَ، لَا فَرْقَ.",segs:[{ar:"أَيًّا كَانَ",uz:"Kim bo‘lsa ham"},{ar:"لَا فَرْقَ",uz:"farqi yo‘q"}],full_uz:"Kim bo‘lsa ham, farqi yo‘q.",note:"أَيًّا كَانَ — kim yoki nima bo‘lishidan qat’i nazar."},
{num:494,time:"00:40:02,820 --> 00:40:09,659",arabic:"لَا حَرَمَنَا اللَّهُ مِنْ ذَكَائِكَ وَحُسْنِ تَدْبِيرِكَ يَا أَبَا عُمَيْرٍ.",segs:[{ar:"لَا حَرَمَنَا اللَّهُ",uz:"Alloh bizni mahrum qilmasin"},{ar:"مِنْ ذَكَائِكَ وَحُسْنِ تَدْبِيرِكَ",uz:"sizning zakovatingiz va yaxshi tadbiringizdan"},{ar:"يَا أَبَا عُمَيْرٍ",uz:"ey Abu Umayr"}],full_uz:"Alloh bizni sizning zakovatingiz va yaxshi tadbiringizdan mahrum qilmasin, ey Abu Umayr.",note:"لَا حَرَمَنَا اللَّهُ — duo tuzilmasi. حُسْنُ التَّدْبِيرِ — ishni puxta o‘ylab, yaxshi tashkil qilish."},
{num:495,time:"00:40:09,659 --> 00:40:20,440",arabic:"فَاجْمَعْ مَنْ بِحَضْرَتِكَ مِنَ الْقُضَاةِ.",segs:[{ar:"فَاجْمَعْ مَنْ بِحَضْرَتِكَ",uz:"Huzuringizdagi kishilarni to‘plang"},{ar:"مِنَ الْقُضَاةِ",uz:"qozilardan bo‘lgan"}],full_uz:"Huzuringizdagi qozilarni to‘plang.",note:"بِحَضْرَتِكَ — sizning huzuringizda, yoningizda. الْقُضَاةُ — قَاضٍ «qozi» so‘zining ko‘pligi."},
{num:496,time:"00:40:20,440 --> 00:40:24,059",arabic:"وَاقْرَأْ عَلَيْهِمْ كِتَابَ أَمِيرِ الْمُؤْمِنِينَ هَذَا إِلَيْكَ.",segs:[{ar:"وَاقْرَأْ عَلَيْهِمْ",uz:"Va ularga o‘qib bering"},{ar:"كِتَابَ أَمِيرِ الْمُؤْمِنِينَ هَذَا",uz:"mo‘minlar amirining mana bu maktubini"},{ar:"إِلَيْكَ",uz:"sizga yo‘llangan"}],full_uz:"Ularga mo‘minlar amirining sizga yo‘llangan mana bu maktubini o‘qib bering.",note:"كِتَابٌ bu yerda «kitob» emas, «maktub». قَرَأَ عَلَيْهِ — unga ovoz chiqarib o‘qib bermoq."},
{num:497,time:"00:40:24,059 --> 00:40:27,379",arabic:"فَابْدَأْ بِامْتِحَانِهِمْ فِيمَا يَقُولُونَ.",segs:[{ar:"فَابْدَأْ بِامْتِحَانِهِمْ",uz:"Ularni sinashdan boshlang"},{ar:"فِيمَا يَقُولُونَ",uz:"aytayotgan gaplari yuzasidan"}],full_uz:"Ularni aytayotgan gaplari yuzasidan sinashdan boshlang.",note:"بَدَأَ بِـ — biror narsadan boshlamoq. فِيمَا — فِي va مَا birikmasi: «...gan narsa borasida»."},
{num:498,time:"00:40:27,379 --> 00:40:31,599",arabic:"وَمَا يَعْتَقِدُونَ فِي خَلْقِ اللَّهِ الْقُرْآنَ وَإِحْدَاثِهِ.",segs:[{ar:"وَمَا يَعْتَقِدُونَ",uz:"Va qanday e’tiqodda ekanlari yuzasidan"},{ar:"فِي خَلْقِ اللَّهِ الْقُرْآنَ",uz:"Allohning Qur’onni yaratishi haqida"},{ar:"وَإِحْدَاثِهِ",uz:"va uni vujudga keltirishi haqida"}],full_uz:"Va Allohning Qur’onni yaratishi hamda vujudga keltirishi haqida qanday e’tiqodda ekanlari yuzasidan.",note:"خَلْقِ اللَّهِ الْقُرْآنَ birikmasida masdar fe’l kabi ishlagan: اللَّهِ shaklan izofada bo‘lsa ham, ishni bajaruvchini; الْقُرْآنَ esa ishning to‘ldiruvchisini bildiradi."},
{num:499,time:"00:40:31,599 --> 00:40:35,219",arabic:"وَأَعْلِمْهُمْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ...",segs:[{ar:"وَأَعْلِمْهُمْ",uz:"Va ularga bildiring"},{ar:"أَنَّ أَمِيرَ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri ... ekanini"}],full_uz:"Va ularga mo‘minlar amiri ... ekanini bildiring.",note:"أَعْلِمْ — أَعْلَمَ «xabar bermoq, bildirmoq» fe’lining buyrug‘i. عَلِّمْ esa «o‘rgating» degani."},
{num:500,time:"00:40:35,219 --> 00:40:38,839",arabic:"غَيْرُ مُسْتَعِينٍ فِي عَمَلِهِ وَلَا وَاثِقٍ...",segs:[{ar:"غَيْرُ مُسْتَعِينٍ فِي عَمَلِهِ",uz:"O‘z ishida yordam olmaydi"},{ar:"وَلَا وَاثِقٍ",uz:"va ishonmaydi"}],full_uz:"O‘z ishida yordam olmasligini va ishonmasligini...",note:"مُسْتَعِينٌ — yordam so‘rovchi yoki yordamdan foydalanuvchi. وَاثِقٌ — ishonuvchi. Kimning yordami olinmasligi va kimga ishonilmasligi keyingi bandlarda keladi."},
{num:501,time:"00:40:38,840 --> 00:40:41,039",arabic:"فِيمَا قَلَّدَهُ اللَّهُ...",segs:[{ar:"فِيمَا قَلَّدَهُ",uz:"Uning zimmasiga yuklagan ishlarda"},{ar:"اللَّهُ",uz:"Alloh"}],full_uz:"Alloh uning zimmasiga yuklagan ishlarda...",note:"قَلَّدَهُ أَمْرًا — uning zimmasiga bir ish yoki mas’uliyat yuklamoq. Bu yerda قَلَّدَ «taqlid qilmoq» ma’nosida emas."},
{num:502,time:"00:40:41,039 --> 00:40:44,500",arabic:"وَاسْتَحْفَظَهُ مِنْ أُمُورِ رَعِيَّتِهِ...",segs:[{ar:"وَاسْتَحْفَظَهُ",uz:"Va unga saqlashni ishonib topshirgan"},{ar:"مِنْ أُمُورِ رَعِيَّتِهِ",uz:"raiyatining ishlaridan"}],full_uz:"Va raiyatining ishlaridan unga saqlashni ishonib topshirganlarida...",note:"اسْتَحْفَظَهُ شَيْئًا — unga bir narsani asrashni topshirmoq. رَعِيَّةٌ — hukmdor boshqaruvidagi xalq."},
{num:503,time:"00:40:44,500 --> 00:40:48,900",arabic:"بِمَنْ لَا يَثِقُ بِدِينِهِ.",segs:[{ar:"بِمَنْ",uz:"O‘sha kishiga"},{ar:"لَا يَثِقُ بِدِينِهِ",uz:"diniga ishonmaydigan"}],full_uz:"Diniga ishonmaydigan kishiga.",note:"Bu parcha oldingi مُسْتَعِينٍ va وَاثِقٍ so‘zlarini to‘ldiradi: uning yordamidan foydalanmaydi va unga ishonmaydi. وَثِقَ بِـ — ...ga ishonmoq."},
{num:504,time:"00:40:48,900 --> 00:41:00,840",arabic:"مَا لَنَا نَحْنُ بِهَذِهِ الْمَسَائِلِ؟",segs:[{ar:"مَا لَنَا نَحْنُ",uz:"Bizning nima aloqamiz bor"},{ar:"بِهَذِهِ الْمَسَائِلِ؟",uz:"bu masalalarga?"}],full_uz:"Bizning bu masalalarga nima aloqamiz bor?",note:"مَا لَنَا بِـ ...؟ — «bizning ...ga nima aloqamiz bor?» yoki «bizga ...ning nima keragi bor?»."},
{num:505,time:"00:41:00,840 --> 00:41:03,840",arabic:"أَلَا يَرْعَوُونَ عَنْ هَذِهِ الْأُمُورِ؟",segs:[{ar:"أَلَا يَرْعَوُونَ",uz:"O‘zlarini tiymaydilarmi"},{ar:"عَنْ هَذِهِ الْأُمُورِ؟",uz:"bu ishlardan?"}],full_uz:"Bu ishlardan o‘zlarini tiymaydilarmi?",note:"ارْعَوَى يَرْعَوِي — yomon yoki noo‘rin ishdan qaytmoq, o‘zini tiymoq."},
{num:506,time:"00:41:03,840 --> 00:41:05,700",arabic:"خَلْقُ الْقُرْآنِ.",segs:null,full_uz:"Qur’onning yaratilganligi.",note:null},
{num:507,time:"00:41:05,699 --> 00:41:09,319",arabic:"مَاذَا يُرَادُ مِنْ وَرَاءِ ذَلِكَ؟ لَا أَدْرِي.",segs:[{ar:"مَاذَا يُرَادُ مِنْ وَرَاءِ ذَلِكَ؟",uz:"Bundan qanday maqsad ko‘zlanmoqda?"},{ar:"لَا أَدْرِي",uz:"Bilmayman"}],full_uz:"Bundan qanday maqsad ko‘zlanmoqda? Bilmayman.",note:"مِنْ وَرَاءِ ذَلِكَ — so‘zma-so‘z «buning ortidan»; bu yerda ko‘zlangan maqsadni bildiradi. يُرَادُ — «istalmoqda», majhul nisbat."},
{num:508,time:"00:41:09,319 --> 00:41:16,119",arabic:"كُلَّ حِينٍ يَخُوضُونَ عَلَيْنَا بِمُصِيبَةٍ جَدِيدَةٍ تَفْتِنُ النَّاسَ.",segs:[{ar:"كُلَّ حِينٍ",uz:"Har safar"},{ar:"يَخُوضُونَ عَلَيْنَا بِمُصِيبَةٍ جَدِيدَةٍ",uz:"boshimizga yangi bir musibat bilan keladilar"},{ar:"تَفْتِنُ النَّاسَ",uz:"odamlarni fitnaga soladigan"}],full_uz:"Har safar boshimizga odamlarni fitnaga soladigan yangi bir musibat bilan keladilar.",note:"تَفْتِنُ النَّاسَ — odamlarni sinovga yoki fitnaga soladi. Bu gap مُصِيبَةٍ جَدِيدَةٍ birikmasini tavsiflaydi."},
{num:509,time:"00:41:16,119 --> 00:41:20,439",arabic:"غَفَرَ اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"غَفَرَ اللَّهُ",uz:"Alloh mag‘firat qilsin"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirini"}],full_uz:"Alloh mo‘minlar amirini mag‘firat qilsin.",note:"غَفَرَ اللَّهُ — shaklan o‘tgan zamon, ma’nosi duo. غَفَرَ لَهُ — uni kechirdi."},
{num:510,time:"00:41:34,840 --> 00:41:37,760",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"va Allohning rahmati hamda barakalari"}],full_uz:"Sizlarga ham tinchlik, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:511,time:"00:41:37,760 --> 00:41:40,700",arabic:"أَهْلًا بِالْأَمِيرِ أَبِي عَبْدِ اللَّهِ.",segs:null,full_uz:"Xush kelibsiz, amir Abu Abdulloh.",note:"أَهْلًا بِـ — kutib olish, xush kelibsiz deyish iborasi. أَبِي shakli oldidagi بِـ sababli qaratqich kelishigida kelgan."},
{num:512,time:"00:41:40,700 --> 00:41:43,840",arabic:"وَصَلَكَ كِتَابُ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"وَصَلَكَ",uz:"Sizga yetib keldimi"},{ar:"كِتَابُ أَمِيرِ الْمُؤْمِنِينَ؟",uz:"mo‘minlar amirining maktubi?"}],full_uz:"Mo‘minlar amirining maktubi sizga yetib keldimi?",note:"So‘roq yuklamasi yozilmagan bo‘lsa ham, ohang orqali savol berilishi mumkin. كِتَابُ bu gapning egasi."},
{num:513,time:"00:41:44,680 --> 00:41:45,840",arabic:"أَعِنْدَكَ عِلْمٌ بِذَلِكَ؟",segs:null,full_uz:"Bundan xabaringiz bormi?",note:"عِنْدَكَ عِلْمٌ بِـ — biror narsadan xabaringiz bor. Boshidagi أَ so‘roq yuklamasi."},
{num:514,time:"00:41:47,539 --> 00:41:52,900",arabic:"تَعْرِفُ أَنَّ قَاضِيَ الْقُضَاةِ الْأَمِيرَ ابْنَ أَبِي دُؤَادٍ يَحْرِصُ عَلَى أَنْ يُطْلِعَنِي عَلَى دَقَائِقِ الْأُمُورِ.",segs:[{ar:"تَعْرِفُ أَنَّ قَاضِيَ الْقُضَاةِ",uz:"Bilasizki, bosh qozi"},{ar:"الْأَمِيرَ ابْنَ أَبِي دُؤَادٍ",uz:"amir Ibn Abu Duod"},{ar:"يَحْرِصُ عَلَى أَنْ يُطْلِعَنِي",uz:"meni xabardor qilishga astoydil intiladi"},{ar:"عَلَى دَقَائِقِ الْأُمُورِ",uz:"ishlarning nozik tafsilotlaridan"}],full_uz:"Bilasizki, bosh qozi amir Ibn Abu Duod meni ishlarning nozik tafsilotlaridan xabardor qilishga astoydil intiladi.",note:"أَطْلَعَهُ عَلَى شَيْءٍ — uni bir narsadan xabardor qilmoq. دَقَائِقُ الْأُمُورِ — ishlarning nozik, mayda tafsilotlari."},
{num:515,time:"00:41:52,900 --> 00:41:55,579",arabic:"أَعْرِفُ، أَعْرِفُ، وَلَكِنْ...",segs:[{ar:"أَعْرِفُ، أَعْرِفُ",uz:"Bilaman, bilaman"},{ar:"وَلَكِنْ",uz:"lekin"}],full_uz:"Bilaman, bilaman, lekin...",note:null},
{num:516,time:"00:41:55,579 --> 00:42:01,120",arabic:"هَلْ أَرْسَلْتَ فِي طَلَبِ الْقَوْمِ؟",segs:[{ar:"هَلْ أَرْسَلْتَ",uz:"Odam yubordingizmi"},{ar:"فِي طَلَبِ الْقَوْمِ؟",uz:"u kishilarni chaqirtirish uchun?"}],full_uz:"U kishilarni chaqirtirish uchun odam yubordingizmi?",note:"أَرْسَلَ فِي طَلَبِ فُلَانٍ — birovni chaqirtirish uchun odam yubormoq."},
{num:517,time:"00:42:01,120 --> 00:42:03,660",arabic:"لَمْ يَكَدِ الْكِتَابُ يَصِلُنِي يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"لَمْ يَكَدِ الْكِتَابُ يَصِلُنِي",uz:"Maktub menga endigina yetib keldi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Maktub menga endigina yetib keldi, ey Abu Abdulloh.",note:"لَمْ يَكَدْ bu vaziyatda ishning endigina sodir bo‘lganini bildiradi. Keyingi so‘zga ulab o‘qilganda يَكَدِ shaklida kasra bilan talaffuz qilinadi."},
{num:518,time:"00:42:04,840 --> 00:42:08,840",arabic:"هَذِهِ الْأُمُورُ يُفْسِدُهَا التَّوَانِي وَالتَّأَنِّي أَيُّهَا الْوَالِي.",segs:[{ar:"هَذِهِ الْأُمُورُ",uz:"Bu ishlarni"},{ar:"يُفْسِدُهَا التَّوَانِي وَالتَّأَنِّي",uz:"sustkashlik va shoshmaslik buzadi"},{ar:"أَيُّهَا الْوَالِي",uz:"ey voliy"}],full_uz:"Ey voliy, bu ishlarni sustkashlik va shoshmaslik buzadi.",note:"التَّوَانِي — sustkashlik, paysalga solish. التَّأَنِّي — shoshmay ish tutish; bu suhbatda kechikishga sabab bo‘ladigan holat sifatida aytilgan."},
{num:519,time:"00:42:08,840 --> 00:42:11,519",arabic:"وَالْأَجْدَرُ الْإِسْرَاعُ بِإِنْفَاذِهَا.",segs:[{ar:"وَالْأَجْدَرُ",uz:"Ma’qulrog‘i esa"},{ar:"الْإِسْرَاعُ بِإِنْفَاذِهَا",uz:"ularni amalga oshirishga shoshilish"}],full_uz:"Ma’qulrog‘i, ularni amalga oshirishga shoshilishdir.",note:"أَجْدَرُ — munosibroq, ma’qulroq. إِنْفَاذٌ — buyruq yoki qarorni amalga oshirish."},
{num:520,time:"00:42:11,519 --> 00:42:14,320",arabic:"سَأَحْرِصُ عَلَى ذَلِكَ بِمَا أُمِرْتُ.",segs:[{ar:"سَأَحْرِصُ عَلَى ذَلِكَ",uz:"Bunga astoydil harakat qilaman"},{ar:"بِمَا أُمِرْتُ",uz:"menga buyurilganiga muvofiq"}],full_uz:"Menga buyurilganiga muvofiq, bunga astoydil harakat qilaman.",note:"أُمِرْتُ — menga buyurildi, majhul nisbat. أَمَرْتُ esa «men buyurdim» degani."},
{num:521,time:"00:42:14,320 --> 00:42:16,440",arabic:"وَبِسُرْعَةٍ.",segs:null,full_uz:"Va tezda.",note:null}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
